local VapeEvents = setmetatable({}, {
    __index = function(self, Index: string)
        local Bindable: BindableEvent = Instance.new("BindableEvent")
        self[Index] = {
            Event = {
                Connect = function(_, Callback: (...any) -> ())
                    return Bindable.Event:Connect(function(...)
                        if vape.ThreadFix then
                            setthreadidentity(8)
                        end
                        Callback(...)
                    end)
                end,
                Wait = function()
                    return Bindable.Event:Wait()
                end
            },
            Fire = function(_, ...)
                Bindable:Fire(...)
            end,
            Destroy = function()
                Bindable:Destroy()
            end
        }
        return self[Index]
    end
})
getgenv().vapeEvents = VapeEvents

