local function CreateGuiOverrides()
    local Objects: {[Instance]: any} = {}
    local function Restore()
        for Object: Instance, Saved: any in Objects do
            Saved.Destroying:Disconnect()
            for Property: string, Value: any in Saved.Properties do
                Value.Connection:Disconnect()
                if Object.Parent and Object[Property] == Value.Applied then
                    Object[Property] = Value.Original
                end
            end
        end
        table.clear(Objects)
    end

    local function Apply(Object: Instance, Properties: {[string]: any})
        local Saved = Objects[Object]
        if not Saved then
            Saved = {Properties = {}}
            Objects[Object] = Saved
            Saved.Destroying = Object.Destroying:Connect(function()
                Objects[Object] = nil
            end)
        end

        for Property: string, Applied: any in Properties do
            local Value = Saved.Properties[Property]
            if not Value then
                Value = {Original = Object[Property], Applied = Applied}
                Saved.Properties[Property] = Value
                Value.Connection = Object:GetPropertyChangedSignal(Property):Connect(function()
                    if Objects[Object] == Saved and Object[Property] ~= Value.Applied then
                        Value.Original = Object[Property]
                        Object[Property] = Value.Applied
                    end
                end)
            end
            Value.Applied = Applied
            Object[Property] = Applied
        end
    end

    return {Apply = Apply, Restore = Restore}
end

local function GetSword()
    local BestSword, BestSwordSlot, BestSwordDamage, BestSwordRange = nil, nil, -1, -1
    for Slot: number, v: any in Store.inventory.inventory.items do
        local ItemMeta = bedwars.ItemMeta[v.itemType]
        local SwordMeta = ItemMeta and ItemMeta.sword or nil
        if SwordMeta then
            local SwordDamage: number = SwordMeta.damage or 0
            local SwordRange: number = SwordMeta.attackRange or Store.swordDistance or 0
            if SwordDamage > BestSwordDamage or (SwordDamage == BestSwordDamage and SwordRange > BestSwordRange) then
                BestSword, BestSwordSlot, BestSwordDamage, BestSwordRange = v, Slot, SwordDamage, SwordRange
            end
        end
    end
    return BestSword, BestSwordSlot
end
getgenv().getSword = GetSword

