local function WaitForChildOfType(Object, Name: string, Timeout: number, Property: boolean?)
    local Deadline, Returned = tick() + Timeout
    repeat
        Returned = Property and Object[Name] or Object:FindFirstChildOfClass(Name)
        if Returned and Returned.Name ~= "UpperTorso" or Deadline < tick() then
            break
        end
        task.wait()
    until false
    return Returned
end

local FrictionTable, OldFriction = {}, setmetatable({}, {__mode = "k"})
local FrictionConnection
local FrictionState

local function ModifyVelocity(Part: Instance)
    if Part:IsA("BasePart") and Part.Name ~= "HumanoidRootPart" and not OldFriction[Part] then
        OldFriction[Part] = Part.CustomPhysicalProperties or "none"
        Part.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0.2, 0.5, 1, 1)
    end
end

local function UpdateVelocity(Force)
    local NewState: boolean = next(FrictionTable) ~= nil
    if FrictionState ~= NewState or Force then
        if FrictionConnection then
            FrictionConnection:Disconnect()
        end
        if NewState then
            if Entity.isAlive then
                for _, v: Instance in Entity.character.Character:GetDescendants() do
                    ModifyVelocity(v)
                end
                FrictionConnection = Entity.character.Character.DescendantAdded:Connect(ModifyVelocity)
            end
        else
            for Part: BasePart, v: PhysicalProperties | string in OldFriction do
                Part.CustomPhysicalProperties = v ~= "none" and v or nil
            end
            table.clear(OldFriction)
        end
    end
    FrictionState = NewState
end

local KitOrder: {[string]: number} = {
    hannah = 5,
    spirit_assassin = 4,
    dasher = 3,
    jade = 2,
    regent = 1
}

local SortMethods = {
    Damage = function(A, B): boolean
        return (A.Entity.Character:GetAttribute("LastDamageTakenTime") or 0) < (B.Entity.Character:GetAttribute("LastDamageTakenTime") or 0)
    end,
    Threat = function(A, B): boolean
        return GetStrength(A.Entity) > GetStrength(B.Entity)
    end,
    Kit = function(A, B): boolean
        return (A.Entity.Player and KitOrder[A.Entity.Player:GetAttribute("PlayingAsKits")] or 0) > (B.Entity.Player and KitOrder[B.Entity.Player:GetAttribute("PlayingAsKits")] or 0)
    end,
    Health = function(A, B): boolean
        return A.Entity.Health < B.Entity.Health
    end,
    Angle = function(A, B): boolean
        local SelfRootPosition: Vector3 = Entity.character.RootPart.Position
        local LocalFacing: Vector3 = Entity.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
        local DirectionA: Vector3 = (A.Entity.RootPart.Position - SelfRootPosition) * Vector3.new(1, 0, 1)
        local DirectionB: Vector3 = (B.Entity.RootPart.Position - SelfRootPosition) * Vector3.new(1, 0, 1)
        local AngleA: number = DirectionA.Magnitude > 0 and math.acos(math.clamp(LocalFacing:Dot(DirectionA.Unit), -1, 1)) or 0
        local AngleB: number = DirectionB.Magnitude > 0 and math.acos(math.clamp(LocalFacing:Dot(DirectionB.Unit), -1, 1)) or 0
        return AngleA < AngleB
    end,
    Mouse = function(A, B): boolean
        local Mouse: Mouse = LocalPlayer:GetMouse()
        local Origin: Vector2 = Vector2.new(Mouse.X, Mouse.Y)

        local PositionA, VisibleA = Camera:WorldToScreenPoint(A.Entity.RootPart.Position)
        local PositionB, VisibleB = Camera:WorldToScreenPoint(B.Entity.RootPart.Position)
        local DistanceA: number = VisibleA and (Vector2.new(PositionA.X, PositionA.Y) - Origin).Magnitude or math.huge
        local DistanceB: number = VisibleB and (Vector2.new(PositionB.X, PositionB.Y) - Origin).Magnitude or math.huge
        return (DistanceA == DistanceA and DistanceA or math.huge) < (DistanceB == DistanceB and DistanceB or math.huge)
    end
}
getgenv().sortmethods = SortMethods

local SortList: {string} = {}
for Name: string in SortMethods do
    table.insert(SortList, Name)
end
table.sort(SortList)
getgenv().sortlist = SortList

local Motion = setmetatable({}, {__mode = "k"})

local function GetHitChance(Ent, Flight: number?): number
    if not Flight or Flight ~= Flight or Flight <= 0 then
        return 0
    end

    local Root: BasePart = Ent.RootPart
    local Velocity: Vector3 = Root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
    local Sample = Motion[Root]
    if not Sample then
        Sample = {velocity = Velocity, clock = os.clock(), accel = 0, speed = Velocity.Magnitude}
        Motion[Root] = Sample
    end

    local Step: number = os.clock() - Sample.clock
    if Step >= 0.05 then
        local Blend: number = math.min(Step * 5, 1)
        Sample.accel += (((Velocity - Sample.velocity).Magnitude / Step) - Sample.accel) * Blend
        Sample.speed += (Velocity.Magnitude - Sample.speed) * Blend
        Sample.velocity, Sample.clock = Velocity, os.clock()
    end

    local Drift: number = math.max(Sample.speed, Velocity.Magnitude) * math.min(Flight, 0.4) * math.clamp(Sample.accel / 120, 0, 1)
    return 1 / (1 + ((Drift / 3) ^ 2))
end
getgenv().getHitChance = GetHitChance

local GetBlockHits
local BreakMethods = {
    Health = function(Block, BlockPosition)
        return GetBlockHits(Block, BlockPosition)
    end,
    Distance = function(Block, BlockPosition)
        local Position: Vector3 = (Entity.isAlive and (Entity.character.RootPart.Position - Vector3.new(0, 1, 0)) or Vector3.zero)
        return (Position - Vector3.new(Block.Position.X, Position.Y, Block.Position.Z)).Magnitude + GetBlockHits(Block, BlockPosition) * 0.01
    end
}

Run(function()
    local OldStart = Entity.start
    local function CustomEntity(Character: Model)
        if Character:HasTag("inventory-entity") and not Character:HasTag("Monster") and not Character:HasTag("trainingRoomDummy") then
            return
        end

        Entity.addEntity(Character, nil, Character:HasTag("Drone") and function(self)
            local DronePlayer: Player? = Players:GetPlayerByUserId(self.Character:GetAttribute("PlayerUserId"))
            return not DronePlayer or LocalPlayer:GetAttribute("Team") ~= DronePlayer:GetAttribute("Team")
        end or function(self)
            return LocalPlayer:GetAttribute("Team") ~= self.Character:GetAttribute("Team")
        end)
    end

    Entity.start = function()
        OldStart()
        if Entity.Running then
            for _, v: Model in CollectionService:GetTagged("entity") do
                CustomEntity(v)
            end
            table.insert(Entity.Connections, CollectionService:GetInstanceAddedSignal("entity"):Connect(CustomEntity))
            table.insert(Entity.Connections, CollectionService:GetInstanceRemovedSignal("entity"):Connect(function(Character: Model)
                Entity.removeEntity(Character)
            end))
        end
    end

    Entity.addPlayer = function(Player: Player)
        if Player.Character then
            Entity.refreshEntity(Player.Character, Player)
        end
        Entity.PlayerConnections[Player] = {
            Player.CharacterAdded:Connect(function(Character: Model)
                Entity.refreshEntity(Character, Player)
            end),
            Player.CharacterRemoving:Connect(function(Character: Model)
                Entity.removeEntity(Character, Player == LocalPlayer)
            end),
            Player:GetAttributeChangedSignal("Team"):Connect(function()
                for _, v: any in Entity.List do
                    if v.Targetable ~= Entity.targetCheck(v) then
                        Entity.refreshEntity(v.Character, v.Player)
                    end
                end

                if Player == LocalPlayer then
                    Entity.start()
                else
                    Entity.refreshEntity(Player.Character, Player)
                end
            end)
        }
    end

    Entity.addEntity = function(Character: Model, Player: Player?, TeamFunction)
        if not Character then
            return
        end
        Entity.EntityThreads[Character] = task.spawn(function()
            local Humanoid, HumanoidRootPart, Head
            if Player then
                Humanoid = WaitForChildOfType(Character, "Humanoid", 10)
                HumanoidRootPart = Humanoid and WaitForChildOfType(Humanoid, "RootPart", workspace.StreamingEnabled and 9e9 or 10, true)
                Head = Character:WaitForChild("Head", 10) or HumanoidRootPart
            else
                Humanoid = Character:FindFirstChildOfClass("Humanoid") or {HipHeight = 0.5}
                HumanoidRootPart = WaitForChildOfType(Character, "PrimaryPart", 10, true)
                Head = HumanoidRootPart
            end
            local UpdateObjects = Player and Player ~= LocalPlayer and {
                Character:WaitForChild("ArmorInvItem_0", 5),
                Character:WaitForChild("ArmorInvItem_1", 5),
                Character:WaitForChild("ArmorInvItem_2", 5),
                Character:WaitForChild("HandInvItem", 5)
            } or {}

            if Humanoid and HumanoidRootPart then
                local Ent = {
                    Connections = {},
                    Character = Character,
                    Health = (Character:GetAttribute("Health") or 100) + GetShieldAttribute(Character),
                    Head = Head,
                    Humanoid = Humanoid,
                    HumanoidRootPart = HumanoidRootPart,
                    HipHeight = Humanoid.HipHeight + (HumanoidRootPart.Size.Y / 2) + (Humanoid.RigType == Enum.HumanoidRigType.R6 and 2 or 0),
                    Jumps = 0,
                    JumpTick = tick(),
                    Jumping = false,
                    LandTick = tick(),
                    MaxHealth = Character:GetAttribute("MaxHealth") or 100,
                    NPC = Player == nil,
                    Player = Player,
                    RootPart = HumanoidRootPart,
                    TeamCheck = TeamFunction
                }

                if Player == LocalPlayer then
                    Ent.AirTime = tick()
                    Entity.character = Ent
                    Entity.isAlive = true
                    Entity.Events.LocalAdded:Fire(Ent)
                    table.insert(Ent.Connections, Character.AttributeChanged:Connect(function(Attribute: string)
                        VapeEvents.AttributeChanged:Fire(Attribute)
                    end))
                    table.insert(Ent.Connections, Character.AttributeChanged:Connect(function(Attribute: string)
                        if Attribute == "Health" or Attribute == "MaxHealth" or Attribute:find("Shield") then
                            Ent.Health = (Character:GetAttribute("Health") or 100) + GetShieldAttribute(Character)
                            Ent.MaxHealth = Character:GetAttribute("MaxHealth") or 100
                        end
                    end))
                    for _, v: RBXScriptSignal in {Humanoid:GetPropertyChangedSignal("HipHeight"), HumanoidRootPart:GetPropertyChangedSignal("Size")} do
                        table.insert(Ent.Connections, v:Connect(function()
                            Ent.HipHeight = Humanoid.HipHeight + (HumanoidRootPart.Size.Y / 2) + (Humanoid.RigType == Enum.HumanoidRigType.R6 and 2 or 0)
                        end))
                    end
                else
                    Ent.Targetable = Entity.targetCheck(Ent)

                    for _, v: any in Entity.getUpdateConnections(Ent) do
                        table.insert(Ent.Connections, v:Connect(function()
                            Ent.Health = (Character:GetAttribute("Health") or 100) + GetShieldAttribute(Character)
                            Ent.MaxHealth = Character:GetAttribute("MaxHealth") or 100
                            Ent.HipHeight = Humanoid.HipHeight + (HumanoidRootPart.Size.Y / 2) + (Humanoid.RigType == Enum.HumanoidRigType.R6 and 2 or 0)
                            Entity.Events.EntityUpdated:Fire(Ent)
                        end))
                    end

                    for _, v: ObjectValue in UpdateObjects do
                        table.insert(Ent.Connections, v:GetPropertyChangedSignal("Value"):Connect(function()
                            task.delay(0.1, function()
                                if bedwars.getInventory then
                                    Store.inventories[Player] = bedwars.getInventory(Player)
                                    Entity.Events.EntityUpdated:Fire(Ent)
                                end
                            end)
                        end))
                    end

                    if Player then
                        local JumpAnimation = Character:FindFirstChild("Animate")
                        if JumpAnimation then
                            pcall(function()
                                JumpAnimation = JumpAnimation.jump:FindFirstChildWhichIsA("Animation").AnimationId
                                table.insert(Ent.Connections, Humanoid.Animator.AnimationPlayed:Connect(function(PlayedAnimation: AnimationTrack)
                                    if PlayedAnimation.Animation.AnimationId == JumpAnimation then
                                        Ent.JumpTick = tick()
                                        Ent.Jumps += 1
                                        Ent.LandTick = tick() + 1
                                        Ent.Jumping = Ent.Jumps > 1
                                    end
                                end))
                            end)
                        end

                        task.delay(0.1, function()
                            if bedwars.getInventory then
                                Store.inventories[Player] = bedwars.getInventory(Player)
                            end
                        end)
                    end
                    table.insert(Entity.List, Ent)
                    Entity.Events.EntityAdded:Fire(Ent)
                end

                table.insert(Ent.Connections, Character.ChildRemoved:Connect(function(Part: Instance)
                    if Part == HumanoidRootPart or Part == Humanoid or Part == Head then
                        if Part == HumanoidRootPart and Humanoid.RootPart then
                            HumanoidRootPart = Humanoid.RootPart
                            Ent.RootPart = Humanoid.RootPart
                            Ent.HumanoidRootPart = Humanoid.RootPart
                            return
                        end
                        Entity.removeEntity(Character, Player == LocalPlayer)
                    end
                end))
            end
            Entity.EntityThreads[Character] = nil
        end)
    end

    Entity.getUpdateConnections = function(Ent)
        local Character: Model = Ent.Character
        local Signals = {
            Character:GetAttributeChangedSignal("Health"),
            Character:GetAttributeChangedSignal("MaxHealth"),
            {
                Connect = function()
                    Ent.Friend = Ent.Player and IsFriend(Ent.Player) or nil
                    Ent.Target = Ent.Player and IsTarget(Ent.Player) or nil
                    return {Disconnect = function() end}
                end
            }
        }

        if Ent.Player then
            table.insert(Signals, Ent.Player:GetAttributeChangedSignal("PlayingAsKits"))
        end

        table.insert(Signals, Character:GetAttributeChangedSignal("TotalShield"))

        return Signals
    end

    Entity.targetCheck = function(Ent)
        if Ent.TeamCheck then
            return Ent:TeamCheck()
        end
        if Ent.NPC then
            return true
        end
        if IsFriend(Ent.Player) then
            return false
        end
        return LocalPlayer:GetAttribute("Team") ~= Ent.Player:GetAttribute("Team")
    end
    vape:Clean(Entity.Events.LocalAdded:Connect(UpdateVelocity))
end)
Entity.start()

