Run(function()
	local BlockReach
	local BlockRange
	local BreakReach
	local BreakRange
	local SwordReach
	local SwordRange
	local AirHits
	
	local RandomGenerator, Old, OldSend = Random.new()
	local SwingConnection
	local LastExtendedSwing: number = 0
	
	local function ExtendedSwordHit()
	    if not Entity.isAlive then
	        return
	    end
	
	    local Sword = GetSword()
	    if not Sword or (tick() - LastExtendedSwing) < GetSwordSpeed(Sword.tool) then
	        return
	    end
	
	    local ReachDistance: number = GetReach(Sword.tool)
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local Target = Entity.EntityPosition({
	        Origin = LocalPosition,
	        Range = SwordRange.Value + 2,
	        Part = "RootPart",
	        Players = true,
	        NPCs = true,
	        Wallcheck = true
	    })
	    if not Target then
	        return
	    end
	
	    local Delta: Vector3 = Target.RootPart.Position - LocalPosition
	    if Delta.Magnitude <= ReachDistance or (Target.Humanoid and Target.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Target.RootPart.AssemblyLinearVelocity.Y) > 0.01) and RandomGenerator:NextNumber(0, 100) > AirHits:GetRandomValue() then
	        return
	    end
	
	    local Direction: Vector3 = CFrame.lookAt(LocalPosition, Target.RootPart.Position).LookVector
	    LastExtendedSwing = tick()
	    bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
	    bedwars.Handler:Get("SwordHit"):Fire("SendToServer", {
	        weapon = Sword.tool,
	        chargedAttack = {chargeRatio = 0},
	        entityInstance = Target.Character,
	        validate = {
	            raycast = {
	                cameraPosition = {value = Camera.CFrame.Position},
	                cursorDirection = {value = Direction}
	            },
	            targetPosition = {value = Target.Character:GetPivot().Position},
	            selfPosition = {value = LocalPosition + Direction * math.max(Delta.Magnitude - (ReachDistance - 0.001), 0)}
	        }
	    })
	end
	
	Reach = vape.Categories.Combat:CreateModule({
	    Name = "Reach",
	    Function = function(Callback: boolean)
	        bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Callback and SwordReach.Enabled and SwordRange.Value + 2 or 14.4
	        if Callback then
	            Old = bedwars.BlockSelector.getMouseInfo
	            bedwars.BlockSelector.getMouseInfo = function(self, Mode: number, Arguments)
	                Arguments = Arguments or {}
	                if Mode == 0 then
	                    Arguments.range = BlockReach.Enabled and BlockRange.Value or 24
	                elseif Mode == 1 then
	                    Arguments.range = BreakReach.Enabled and BreakRange.Value or 18
	                end
	                return Old(self, Mode, Arguments)
	            end
	            OldSend = bedwars.SwordController.sendServerRequest
	            bedwars.SwordController.sendServerRequest = function(self, Ent, ...)
	                local Character = Ent and Ent:getInstance()
	                local Humanoid: Humanoid? = Character and Character:FindFirstChildWhichIsA("Humanoid")
	                if Character and Character.PrimaryPart and Entity.isAlive and (Character.PrimaryPart.Position - Entity.character.RootPart.Position).Magnitude > GetReach(self:getHandItem().tool) and (Humanoid and Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Character.PrimaryPart.AssemblyLinearVelocity.Y) > 0.01) and RandomGenerator:NextNumber(0, 100) > AirHits:GetRandomValue() then
	                    return
	                end
	
	                return OldSend(self, Ent, ...)
	            end
	        else
	            bedwars.BlockSelector.getMouseInfo = Old
	            bedwars.SwordController.sendServerRequest = OldSend
	        end
	
	        if SwingConnection then
	            SwingConnection:Disconnect()
	            SwingConnection = nil
	        end
	        if not canDebug and Reach.Enabled and SwordReach.Enabled then
	            SwingConnection = UserInputService.InputBegan:Connect(function(Input: InputObject, Processed: boolean)
	                if Processed then
	                    return
	                end
	                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then
	                    return
	                end
	
	                ExtendedSwordHit()
	            end)
	        end
	    end,
	    Tooltip = "Allows you to place, attack, and break further"
	})
	
	SwordReach = Reach:CreateToggle({
	    Name = "Sword Reach",
	    Function = function(Callback: boolean)
	        bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and Callback and SwordRange.Value + 2 or 14.4
	        if AirHits then
	            SwordRange.Object.Visible = Callback
	            AirHits.Object.Visible = Callback
	        end
	
	        if SwingConnection then
	            SwingConnection:Disconnect()
	            SwingConnection = nil
	        end
	        if not canDebug and Reach.Enabled and Callback then
	            SwingConnection = UserInputService.InputBegan:Connect(function(Input: InputObject, Processed: boolean)
	                if Processed then
	                    return
	                end
	                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then
	                    return
	                end
	
	                ExtendedSwordHit()
	            end)
	        end
	    end,
	    Default = true
	})
	SwordRange = Reach:CreateSlider({
	    Name = "Sword Range",
	    Min = 1,
	    Max = 18,
	    Decimal = 5,
	    Darker = true,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Function = function(Val: number)
	        bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and SwordReach.Enabled and Val or 14.4
	    end,
	    Default = 18
	})
	AirHits = Reach:CreateTwoSlider({
	    Name = "Air reach hit chance",
	    Min = 0,
	    Max = 100,
	    DefaultMin = 100,
	    DefaultMax = 100,
	    Darker = true,
	    Tooltip = "Chance for a hit past normal reach to land while the target is off the ground, rolled fresh between the two values on every swing"
	})
	BlockReach = Reach:CreateToggle({
	    Name = "Placement Reach",
	    Function = function(Callback: boolean)
	        BlockRange.Object.Visible = Callback
	    end
	})
	BlockRange = Reach:CreateSlider({
	    Name = "Placement Range",
	    Min = 1,
	    Max = 60,
	    Default = 18,
	    Darker = true,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Visible = false
	})
	BreakReach = Reach:CreateToggle({
	    Name = "Break Reach",
	    Function = function(Callback: boolean)
	        BreakRange.Object.Visible = Callback
	    end
	})
	BreakRange = Reach:CreateSlider({
	    Name = "Break Range",
	    Min = 1,
	    Max = 30,
	    Default = 30,
	    Decimal = 5,
	    Darker = true,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Visible = false
	})
	Reach:CreateButton({
	    Name = "Reset to default reach",
	    Function = function()
	        BreakRange:SetValue(18)
	        BlockRange:SetValue(24)
	        SwordRange:SetValue(12.4)
	    end,
	    Tooltip = "Resets every range back to default"
	})
end)

Run(function()
	local SilentAim
	local Targets
	local TargetPart
	local Sort
	local Prediction
	local FOV
	local HitChance
	local HeadshotChance
	local OtherProjectiles
	local Blacklist
	
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.FilterType = Enum.RaycastFilterType.Include
	
	local OldNamecall
	local LastWarn: number = 0
	local RandomGenerator: Random = Random.new()
	
	local function SolveSilent(Arguments): Vector3?
	    local Origin, Velocity, ProjectileType = Arguments[4], Arguments[6], Arguments[3]
	    if typeof(Origin) ~= "Vector3" or typeof(Velocity) ~= "Vector3" or type(ProjectileType) ~= "string" then
	        return
	    end
	
	    if (not OtherProjectiles.Enabled) and not ProjectileType:find("arrow") then
	        return
	    end
	
	    if table.find(Blacklist.ListEnabled or {}, ((ProjectileType == "glue_trap" or ProjectileType == "glue_projectile") and "gloop" or ProjectileType)) then
	        return
	    end
	
	    local ProjectileMeta = bedwars.ProjectileMeta[ProjectileType]
	    if not ProjectileMeta then
	        return
	    end
	
	    local Speed: number = Velocity.Magnitude
	    if Speed <= 0 then
	        return
	    end
	
	    if RandomGenerator:NextNumber(0, 100) > HitChance:GetRandomValue() then
	        return
	    end
	
	    local Map: Instance? = workspace:FindFirstChild("Map")
	    if Map ~= RayCheck.FilterDescendantsInstances[1] then
	        RayCheck.FilterDescendantsInstances = Map and {Map} or {}
	    end
	    local Gravity: number = ProjectileMeta.gravitationalAcceleration or 196.2
	
	    local Target = Entity.EntityMouse({
	        Part = "RootPart",
	        Range = FOV.Value,
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Priority = Targets.Priority.Value,
	        Wallcheck = Targets.Walls.Enabled,
	        Sort = SortMethods[Sort.Value or "Distance"],
	        MouseOrigin = Camera.ViewportSize / 2,
	        Origin = Origin
	    })
	    if not Target then
	        return
	    end
	
	    local PartName: string = RandomGenerator:NextNumber(0, 100) < HeadshotChance:GetRandomValue() and "Head" or TargetPart.Value
	    local SelectedPart = GetTargetPart(Target, PartName)
	    local TargetPosition: Vector3?
	    if PartName == "Closest" then
	        local Center, ClosestDistance = Camera.ViewportSize / 2, 9e9
	        for _, v: Instance in Target.Character:GetChildren() do
	            if v:IsA("BasePart") then
	                local ScreenPosition, Visible = Camera:WorldToViewportPoint(v.Position)
	                if Visible then
	                    local PartDistance: number = (Center - Vector2.new(ScreenPosition.X, ScreenPosition.Y)).Magnitude
	                    if PartDistance < ClosestDistance then
	                        ClosestDistance, TargetPosition = PartDistance, v.Position
	                    end
	                end
	            end
	        end
	        TargetPosition = TargetPosition or Target.Character.PrimaryPart and Target.Character.PrimaryPart.Position
	    elseif PartName == "Dynamic" then
	        local Tool = Store.hand.tool
	        if IsHeadshotProjectile(Tool and Tool.Name) and Target.Character:FindFirstChild("Head") then
	            TargetPosition = Target.Character.Head.Position
	        else
	            TargetPosition = Target.Character.PrimaryPart and Target.Character.PrimaryPart.Position
	        end
	    end
	
	    TargetPosition = TargetPosition or SelectedPart and SelectedPart.Position
	    if not TargetPosition then
	        return
	    end
	    local PlayerGravity: number = workspace.Gravity
	    local Balloons = Target.Character:GetAttribute("InflatedBalloons")
	    if Balloons and Balloons > 0 then
	        PlayerGravity = workspace.Gravity * (1 - (Balloons >= 4 and 1.2 or Balloons >= 3 and 1 or 0.975))
	    end
	
	    if Target.Character.PrimaryPart and Target.Character.PrimaryPart:FindFirstChild("rbxassetid://8200754399") then
	        PlayerGravity = 6
	    end
	
	    if Target.Player and Target.Player:GetAttribute("IsOwlTarget") then
	        for _, v: Instance in CollectionService:GetTagged("Owl") do
	            if v:GetAttribute("Target") == Target.Player.UserId and v:GetAttribute("Status") == 2 then
	                PlayerGravity = 0
	            end
	        end
	    end
	
	    local IsPearl: boolean = ProjectileType == "telepearl"
	    local TargetVelocity: Vector3 = IsPearl and Vector3.zero or Target.RootPart.AssemblyLinearVelocity
	    local TargetAirborne: boolean = not IsPearl and Target.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(TargetVelocity.Y) > 0.01
	    local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(Origin, Speed * Prediction.Value, Gravity, TargetPosition, TargetVelocity, PlayerGravity, Target.HipHeight, Target.Jumping and 42.6 or nil, RayCheck, TargetAirborne, Target.RootPart.Position, Target.RootPart, nil, true)
	    if not AimPosition or not TravelTime or TravelTime > (ProjectileMeta.lifetimeSec or 3) then
	        return
	    end
	
	    TargetInfo.Targets[Target] = tick() + 1
	    Store.hitchance.SilentAim = {Value = GetHitChance(Target, TravelTime), Clock = tick()}
	    return CFrame.lookAt(Origin, AimPosition).LookVector * Speed
	end
	
	SilentAim = vape.Categories.Combat:CreateModule({
	    Name = "SilentAim",
	    Function = function(Callback: boolean)
	        if Callback and not canDebug then
	            SendNotification("SilentAim", "This executor cannot redirect native projectile calls. Use AimAssist instead", 5)
	            SilentAim:Toggle()
	            return
	        end
	        if Callback and not OldNamecall then
	            OldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(...)
	                if SilentAim.Enabled and not checkcaller() and getnamecallmethod() == "InvokeServer" and tostring(...) == "ProjectileFire" then
	                    local self = ...
	                    local Arguments = table.pack(select(2, ...))
	                    local Success, NewVelocity = pcall(SolveSilent, Arguments)
	                    if Success and typeof(NewVelocity) == "Vector3" then
	                        Arguments[6] = NewVelocity
	                    elseif not Success and shared.VapeDeveloper and tick() > LastWarn then
	                        LastWarn = tick() + 5
	                        warn(`[catvape] silentaim solve failed: {NewVelocity}`)
	                    end
	                    return self.InvokeServer(self, table.unpack(Arguments, 1, Arguments.n))
	                end
	                return OldNamecall(...)
	            end))
	        end
	    end,
	    Tooltip = "Redirects only the projectile values sent to the server, so enemies get hit while your shot flies exactly where you aimed on your own screen"
	})
	
	Targets = SilentAim:CreateTargets({
	    Players = true,
	    Walls = true
	})
	TargetPart = SilentAim:CreateDropdown({
	    Name = "Part",
	    List = {"RootPart", "Head", "Torso", "Left arm", "Right arm", "Left leg", "Right leg", "Random", "Dynamic", "Closest"}
	})
	local Methods: {string} = {"Damage", "Distance"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Sort = SilentAim:CreateDropdown({
	    Name = "Target Mode",
	    List = Methods,
	    Default = "Distance"
	})
	Prediction = SilentAim:CreateSlider({
	    Name = "Prediction",
	    Min = 0.1,
	    Max = 2,
	    Default = 1,
	    Decimal = 10
	})
	FOV = SilentAim:CreateSlider({
	    Name = "FOV",
	    Min = 1,
	    Max = 1000,
	    Default = 1000
	})
	HitChance = SilentAim:CreateTwoSlider({
	    Name = "Hit Chance",
	    Min = 0,
	    Max = 100,
	    DefaultMin = 100,
	    DefaultMax = 100,
	    Tooltip = "Chance in % for each shot to be redirected, rolled fresh between the two values on every shot. A missed roll leaves the shot where you aimed"
	})
	HeadshotChance = SilentAim:CreateTwoSlider({
	    Name = "Headshot Chance",
	    Min = 0,
	    Max = 100,
	    DefaultMin = 0,
	    DefaultMax = 0,
	    Tooltip = "Chance in % for each redirected shot to aim at the head instead of the Part setting, rolled fresh between the two values on every shot"
	})
	OtherProjectiles = SilentAim:CreateToggle({
	    Name = "Other Projectiles",
	    Function = function(Callback: boolean)
	        if Blacklist then
	            Blacklist.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Blacklist = SilentAim:CreateTextList({
	    Name = "Blacklist",
	    Default = {"gloop", "telepearl"},
	    Darker = true,
	    Placeholder = "projectile"
	})
end)

Run(function()
	local SilentAura
	local Targets
	local Speed
	local Range
	local Angle
	local Mode
	local Area
	local LegitAura
	local Mouse
	local Dynamic
	local Limit
	local SilentAim
	local SwingTime
	local Perfect
	local AirHits
	
	local Show
	local TargetColor
	local AttackColor
	
	local RandomGenerator: Random = Random.new()
	local CharacterParts: {[Model]: {Instance}} = setmetatable({}, {__mode = "k"})
	local LastEffect, LastAttack, LastSwing, OldSwing, SwingHook = 0, 0, 0, nil, nil
	local Session = nil
	local HitBudget, HitSpacing, GapFloor = 0.2, 0.296, 0.296
	local SafeSpacing, SafeFloor, HighSpacing, HighFloor = 0.296, 0.296, 0.2925, 0.2925
	local WeaponSpacing: {[number]: number} = {
	    [0.21] = 0.229,
	    [0.25] = 0.249,
	    [0.35] = 0.345,
	    [0.4] = 0.341,
	    [0.6] = 0.63
	}
	local WeaponMargin: number = 0.03
	local FuryScale: number = 1 - (bedwars.BlackMarketeerBalance.FURY_POTION_ATTACK_SPEED_MULTIPLIER - 1)
	task.spawn(function()
	    HitBudget = 60 / bedwars.Handler:Get("SwordHit"):GetRateLimit()
	end)
	
	local Box: BoxHandleAdornment = Instance.new("BoxHandleAdornment")
	Box.Adornee = nil
	Box.AlwaysOnTop = true
	Box.Size = Vector3.new(3, 5, 3)
	Box.CFrame = CFrame.new(0, -0.5, 0)
	Box.ZIndex = 0
	if vape.ThreadFix then
	    setthreadidentity(8)
	end
	Box.Parent = vape.gui
	
	SilentAura = vape.Categories.Combat:CreateModule({
	    Name = "SilentAura",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Current = {}
	            local Hook
	            Session = Current
	            local PreviousSwing = bedwars.SwordController.playSwordEffect
	            OldSwing = PreviousSwing
	            Hook = function(self, Meta, Charged, Config)
	                if not SilentAura.Enabled or SwingHook ~= Hook or (Config and Config.playAnimation == false) then
	                    return PreviousSwing(self, Meta, Charged, Config)
	                end
	                local EffectFloor: number = Perfect.Enabled and 0.11 or math.max(SwingTime.Value, 0.11)
	                if ((tick() - LastAttack) < 0.4 or (tick() - LastSwing) < 0.4) and (tick() - LastEffect) < EffectFloor then
	                    return
	                end
	                LastEffect = tick()
	                return PreviousSwing(self, Meta, Charged, Config)
	            end
	            SwingHook = Hook
	            bedwars.SwordController.playSwordEffect = SwingHook
	
	            local LastEnt, LastFound = nil, 0
	            local FoundAt: number = tick()
	            local LastAttacked: number = tick()
	
	            SilentAura:Clean(RunService.PostSimulation:Connect(function(DeltaTime: number)
	                if Entity.isAlive and LastEnt and LastEnt.RootPart and LastEnt.RootPart.Parent and tick() - LastFound < 0.5 then
	                    TargetInfo.Targets[LastEnt] = tick() + 0.5
	                    Entity.character.Humanoid.AutoRotate = not SilentAim.Enabled
	                    local T: number = math.min((tick() - FoundAt) / (1 / (Speed.Value * 0.5)), 1)
	                    local AimSpeed: number = Speed.Value * (T < 0.5 and 4 * T * T * T or 1 - math.pow(-2 * T + 2, 3) / 2)
	                    local AimPosition: Vector3 = LastEnt.RootPart.Position
	                    if Area.Value == "Closest" then
	                        if not CharacterParts[LastEnt.Character] then
	                            CharacterParts[LastEnt.Character] = LastEnt.Character:GetChildren()
	                        end
	
	                        local Center, ClosestDistance = UserInputService:GetMouseLocation(), 9e9
	                        for _, v: Instance in CharacterParts[LastEnt.Character] do
	                            if v and v.Parent and v:IsA("BasePart") then
	                                local ScreenPosition, Visible = Camera:WorldToViewportPoint(v.Position)
	                                if Visible then
	                                    local PartDistance: number = (Center - Vector2.new(ScreenPosition.X, ScreenPosition.Y)).Magnitude
	                                    if PartDistance < ClosestDistance then
	                                        ClosestDistance, AimPosition = PartDistance, v.Position
	                                    end
	                                end
	                            end
	                        end
	                    end
	
	                    local AimCFrame: CFrame = Camera.CFrame:Lerp(CFrame.lookAt(Camera.CFrame.p, AimPosition + Vector3.new((RandomGenerator:NextNumber() - 0.5) * 15 * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * 15 * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * 15 * DeltaTime)), AimSpeed * DeltaTime)
	                    if SilentAim.Enabled then
	                        local Root: BasePart = Entity.character.RootPart
	                        local Direction: Vector3 = Vector3.new(LastEnt.RootPart.Position.X - Root.Position.X, 0, LastEnt.RootPart.Position.Z - Root.Position.Z)
	                        if Direction.Magnitude > 0 then
	                            Root.CFrame = Root.CFrame:Lerp(CFrame.lookAlong(Root.Position, Direction), math.clamp((AimSpeed + 2) * DeltaTime, 0, 1))
	                        end
	                    else
	                        Camera.CFrame = AimCFrame
	                    end
	                elseif Entity.isAlive then
	                    Entity.character.Humanoid.AutoRotate = true
	                end
	            end))
	
	            local SwingCooldown, LastHit = 0, 0
	            local Swung
	            ;(function()
	                repeat
	                    task.wait()
	                    if not SilentAura.Enabled or Session ~= Current then break end
	                    local Sword, ItemMeta = nil, nil
	                    local Blocked: boolean = not Entity.isAlive
	                    Blocked = Blocked or (Mouse.Enabled and not UserInputService:IsMouseButtonPressed(0) and (bedwars.SwordController.lastSwing == Swung or (tick() - bedwars.SwordController.lastSwing) > 0.3))
	                    Blocked = Blocked or (LegitAura.Enabled and (tick() - bedwars.SwordController.lastSwing) > 0.3)
	                    Blocked = Blocked or ((LocalPlayer.Character:GetAttribute("StunnedUntilTime") or 0) - workspace:GetServerTimeNow() > 0)
	                    Blocked = Blocked or bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)
	                    if not Blocked then
	                        Sword = Limit.Enabled and store.hand or store.tools.sword
	                        if not Sword or not Sword.tool then
	                            Sword = nil
	                        elseif Limit.Enabled and (store.hand.toolType ~= "sword" or bedwars.DaoController.chargingMaid) then
	                            Sword = nil
	                        else
	                            ItemMeta = bedwars.ItemMeta[Sword.tool.Name]
	                        end
	                    end
	
	                    if Sword then
	                        local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                        local Ent = Entity.EntityPosition({
	                            Origin = LocalPosition,
	                            Range = bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE + Range.Value,
	                            Wallcheck = Targets.Walls.Enabled or nil,
	                            Part = "RootPart",
	                            Players = Targets.Players.Enabled,
	                            NPCs = Targets.NPCs.Enabled,
	                            Priority = Targets.Priority.Value,
	                            Sort = sortmethods[Mode.Value or "Distance"]
	                        })
	                        local ColorSlider = tick() - LastAttacked < 0.1 and AttackColor or TargetColor
	                        Box.Adornee = Show.Enabled and Ent and Ent.RootPart or nil
	                        Box.Transparency = 1 - ColorSlider.Opacity
	                        Box.Color3 = Color3.fromHSV(ColorSlider.Hue, ColorSlider.Sat, ColorSlider.Value)
	                        if Ent then
	                            if not store.hand or store.hand.tool ~= Sword.tool then
	                                local Hotbar = getHotbar(Sword.tool)
	                                if Hotbar then
	                                    hotbarSwitch(Hotbar)
	                                else
	                                    continue
	                                end
	                            end
	                            if store.hand.tool ~= Sword.tool then
	                                continue
	                            end
	
	                            local LocalFacing: Vector3 = (UserInputService.KeyboardEnabled and Camera or Entity.character.RootPart).CFrame.LookVector * Vector3.new(1, 0, 1)
	                            local Delta, Flat = (Ent.RootPart.Position - LocalPosition), ((Ent.RootPart.Position - LocalPosition) * Vector3.new(1, 0, 1))
	                            local FacingDot: number = Flat.Magnitude > 0 and LocalFacing.Magnitude > 0 and (LocalFacing / LocalFacing.Magnitude):Dot(Flat / Flat.Magnitude) or 0
	                            if FacingDot < math.cos(math.rad(Angle.Value) / 2) then
	                                continue
	                            end
	
	                            if not LegitAura.Enabled and (tick() - bedwars.SwordController.lastSwing) >= (Perfect.Enabled and (ItemMeta.sword.attackSpeed or 0.11) or math.max(SwingTime.Value, 0.11)) then
	                                Swung = tick()
	                                LastSwing = Swung
	                                bedwars.SwordController:playSwordEffect(ItemMeta, false, {itemSkin = Sword.itemSkin})
	                                bedwars.SwordController.lastSwing = Swung
	                            end
	
	                            if LastEnt ~= Ent or FacingDot < -0.5 then
	                                FoundAt = tick()
	                            end
	                            LastEnt, LastFound = Ent, tick()
	
	                            if Delta.Magnitude > bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE then
	                                continue
	                            end
	                            LastAttacked = tick()
	
	                            local SwordSpeed: number = ItemMeta and ItemMeta.sword and ItemMeta.sword.attackSpeed or 0.3
	                            local Fury: number = LocalPlayer.Character:GetAttribute("StatusEffect_fury_potion") and FuryScale or 1
	                            local Stock: boolean = SwordSpeed == 0.3
	                            local Spacing: number = (Stock and HitSpacing or WeaponSpacing[SwordSpeed] or (SwordSpeed + WeaponMargin)) * Fury
	                            local AttackSpeed: number = (SwordSpeed * Fury) - ((0.017999999225139618 / 10) + 0.013412)
	                            local HitFloor: number = Stock and GapFloor * Fury or Spacing
	                            local HitDelay: number = math.max(HitBudget, Spacing, (bedwars.SwordController.lastAttack + AttackSpeed) - workspace:GetServerTimeNow())
	                            if Dynamic.Enabled then
	                                local ReachDistance: number = math.max(getReach(Sword.tool), 0.001)
	                                local Ratio: number = math.min((Entity.character.RootPart.Position - Ent.RootPart.Position).Magnitude, ReachDistance) / ReachDistance
	                                HitDelay = math.clamp(HitDelay * Ratio, HitFloor, HitDelay)
	                            end
	
	                            if tick() >= SwingCooldown + HitDelay and (tick() - LastHit) >= HitFloor then
	                                local Airborne: boolean = (Ent.Humanoid and Ent.Humanoid.FloorMaterial == Enum.Material.Air) or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01
	                                local Direction: Vector3 = CFrame.lookAt(LocalPosition, Ent.RootPart.Position).LookVector
	                                local SelfPosition: Vector3 = LocalPosition + Direction * math.max(Delta.Magnitude - (getReach(Sword.tool) - 0.001), 0)
	                                bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
	                                LastAttack = tick()
	                                SwingCooldown = math.max(SwingCooldown + HitDelay, tick())
	                                LastHit = tick()
	
	                                if (not Airborne) or RandomGenerator:NextNumber(0, 100) <= AirHits:GetRandomValue() then
	                                    bedwars.Handler:Get("SwordHit"):Fire("SendToServer", {
	                                        weapon = Sword.tool,
	                                        chargedAttack = {chargeRatio = 0},
	                                        entityInstance = Ent.Character,
	                                        validate = {
	                                            raycast = {
	                                                cameraPosition = {value = Camera.CFrame.Position},
	                                                cursorDirection = {value = Direction}
	                                            },
	                                            targetPosition = {value = Ent.Character:GetPivot().Position},
	                                            selfPosition = {value = SelfPosition}
	                                        }
	                                    })
	                                end
	                            end
	                        else
	                            LastFound = 0
	                        end
	                    else
	                        Box.Adornee = nil
	                        LastFound = 0
	                    end
	                until not SilentAura.Enabled or Session ~= Current
	            end)()
	        else
	            if bedwars.SwordController.playSwordEffect == SwingHook then
	                bedwars.SwordController.playSwordEffect = OldSwing
	            end
	            OldSwing = nil
	            SwingHook = nil
	            LastEffect, LastAttack, LastSwing = 0, 0, 0
	            if Entity.isAlive then
	                Entity.character.Humanoid.AutoRotate = true
	            end
	            Box.Adornee = nil
	        end
	    end,
	    Tooltip = "Automatically aims and attacks nearby target"
	})
	
	Targets = SilentAura:CreateTargets({
	    Players = true,
	    NPCs = true
	})
	Speed = SilentAura:CreateSlider({
	    Name = "Aim speed",
	    Min = 1,
	    Max = 10,
	    Default = 6,
	    Decimal = 5,
	    Tooltip = "How fast the Aura is going to aim"
	})
	SwingTime = SilentAura:CreateSlider({
	    Name = "Swing time",
	    Darker = true,
	    Visible = false,
	    Min = 0,
	    Max = 0.5,
	    Default = 0.42,
	    Decimal = 100
	})
	Range = SilentAura:CreateSlider({
	    Name = "Extra swing distance",
	    Tooltip = "Where you will start swinging, not attacking",
	    Min = 0,
	    Max = 6,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Decimal = 5,
	    Default = 3
	})
	Angle = SilentAura:CreateSlider({
	    Name = "Max angle",
	    Min = 1,
	    Max = 360,
	    Default = 180
	})
	AirHits = SilentAura:CreateTwoSlider({
	    Name = "Air hit chance",
	    Min = 0,
	    Max = 100,
	    DefaultMin = 100,
	    DefaultMax = 100,
	    Tooltip = "Chance to land a hit while the target is off the ground, rolled fresh between the two values on every swing"
	})
	local Methods: {string} = {"Health", "Damage", "Distance"}
	for _, v: string in sortlist do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Mode = SilentAura:CreateDropdown({
	    Name = "Target mode",
	    Default = "Health",
	    List = Methods,
	    Tooltip = "How Aura should prioritize targets"
	})
	Area = SilentAura:CreateDropdown({
	    Name = "Target area",
	    List = {"Center", "Closest"},
	    Default = "Center",
	    Visible = false,
	    Tooltip = "Where the Aura will aim towards"
	})
	Perfect = SilentAura:CreateToggle({
	    Name = "Perfect Swing",
	    Function = function(Callback: boolean)
	        SwingTime.Object.Visible = not Callback
	    end,
	    Default = true,
	    Tooltip = "Follows sword item's swing time"
	})
	Mouse = SilentAura:CreateToggle({Name = "Require mouse down"})
	Dynamic = SilentAura:CreateToggle({
	    Name = "Dynamic hits",
	    Function = function(Callback: boolean)
	        HitSpacing = Callback and HighSpacing or SafeSpacing
	        GapFloor = Callback and HighFloor or SafeFloor
	    end,
	    Default = true,
	    Tooltip = "Goes for 35 hits every 10 seconds instead of a safe 34, at the cost of ghosting a hit now and then"
	})
	LegitAura = SilentAura:CreateToggle({Name = "Swing only"})
	SilentAim = SilentAura:CreateToggle({
	    Name = "Silent Aim",
	    Function = function(Callback: boolean)
	        Area.Object.Visible = not Callback
	    end,
	    Default = true,
	    Tooltip = "Uses catvape's aiming technology to silently aim while looking legit"
	})
	Show = SilentAura:CreateToggle({
	    Name = "Show target",
	    Function = function(Callback: boolean)
	        if TargetColor then
	            TargetColor.Object.Visible = Callback
	        end
	        if AttackColor then
	            AttackColor.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	TargetColor = SilentAura:CreateColorSlider({
	    Name = "Target color",
	    Darker = true,
	    DefaultOpacity = 0.5,
	    DefaultHue = 1
	})
	AttackColor = SilentAura:CreateColorSlider({
