	        for _, v: string in List do
	            if v:find("iron") then
	                table.insert(BlockList, "iron_ore_mesh_block")
	            else
	                table.insert(BlockList, v)
	            end
	        end
	    end,
	    Darker = true,
	    Visible = false
	})
end)

local Fly
local LongJump
Run(function()
    local Value
    local VerticalValue
    local WallCheck
    local PopBalloons
    local TeleportDown
    local ShowProgressbar
    local Bar = nil
    local AirLimit: number = 1.7
    local RayCheck: RaycastParams = RaycastParams.new()
    RayCheck.RespectCanCollide = true
    local FilterCharacter: Model?
    local FilterFallPart: Part?
    local Up, Down, Old = 0, 0

    local function RemoveBar()
        if Bar then
            Bar.Frame:Destroy()
            Bar = nil
        end
    end

    Fly = vape.Categories.Blatant:CreateModule({
        Name = "Fly",
        Function = function(Callback: boolean)
            FrictionTable.Fly = Callback or nil
            UpdateVelocity()
            if Callback then
                Up, Down, Old = 0, 0, bedwars.BalloonController.deflateBalloon
                bedwars.BalloonController.deflateBalloon = function() end
                local TeleportTick, TeleportToggle, OldY = tick(), true
                if ShowProgressbar.Enabled then
                    Bar = CreateProgressBar()
                end
                Fly:Clean(RemoveBar)

                if LocalPlayer.Character and (LocalPlayer.Character:GetAttribute("InflatedBalloons") or 0) == 0 and GetItem("balloon") then
                    bedwars.BalloonController:inflateBalloon()
                end
                Fly:Clean(VapeEvents.AttributeChanged.Event:Connect(function(AttributeName: string)
                    if AttributeName == "InflatedBalloons" and (LocalPlayer.Character:GetAttribute("InflatedBalloons") or 0) == 0 and GetItem("balloon") then
                        bedwars.BalloonController:inflateBalloon()
                    end
                end))
                Fly:Clean(RunService.PreSimulation:Connect(function(Delta: number)
                    if Entity.isAlive and not vape.MovementOwner and isnetworkowner(Entity.character.RootPart) then
                        local FlyAllowed: boolean = (LocalPlayer.Character:GetAttribute("InflatedBalloons") or 0) > 0 or Store.matchState == 2
                        if Bar then
                            local Waiting: boolean = not FlyAllowed and TeleportDown.Enabled
                            Bar.Frame.Visible = Waiting
                            if Waiting then
                                Bar.Set(AirLimit - (tick() - Entity.character.AirTime), AirLimit)
                            end
                        end
                        local Mass: number = (-0.02 + (FlyAllowed and 6 or 0) * (tick() % 0.4 < 0.2 and -1 or 1)) + ((Up + Down) * VerticalValue.Value)
                        local Root, MoveDirection = Entity.character.RootPart, Entity.character.Humanoid.MoveDirection
                        local CurrentSpeed: number = GetSpeed()
                        local Destination: Vector3 = MoveDirection * math.max(Value.Value - CurrentSpeed, 0) * Delta
                        if not LocalPlayer.Character or FilterCharacter ~= LocalPlayer.Character or FilterFallPart ~= AntiFallPart then
                            FilterCharacter, FilterFallPart = LocalPlayer.Character, AntiFallPart
                            RayCheck.FilterDescendantsInstances = {FilterCharacter, Camera, FilterFallPart}
                        end
                        RayCheck.CollisionGroup = Root.CollisionGroup

                        if WallCheck.Enabled then
                            local WallRay: RaycastResult? = workspace:Raycast(Root.Position, Destination, RayCheck)
                            if WallRay then
                                Destination = (WallRay.Position + WallRay.Normal) - Root.Position
                            end
                        end

                        if not FlyAllowed then
                            if TeleportToggle and not OldY and (tick() - Entity.character.AirTime) > AirLimit then
                                local GroundRay: RaycastResult? = workspace:Raycast(Root.Position, Vector3.new(0, -1000, 0), RayCheck)
                                if GroundRay and TeleportDown.Enabled then
                                    TeleportToggle = false
                                    OldY = Root.Position.Y
                                    TeleportTick = tick() + 0.11
                                    Root.CFrame = CFrame.lookAlong(Vector3.new(Root.Position.X, GroundRay.Position.Y + Entity.character.HipHeight, Root.Position.Z), Root.CFrame.LookVector)
                                end
                            elseif not TeleportToggle and OldY then
                                if TeleportTick < tick() then
                                    Root.CFrame = CFrame.lookAlong(Vector3.new(Root.Position.X, OldY, Root.Position.Z), Root.CFrame.LookVector)
                                    TeleportToggle = true
                                    OldY = nil
                                else
                                    Mass = 0
                                end
                            end
                        end

                        Root.CFrame += Destination
                        Root.AssemblyLinearVelocity = (MoveDirection * CurrentSpeed) + Vector3.new(0, Mass, 0)
                    elseif Bar then
                        Bar.Frame.Visible = false
                    end
                end))
                Fly:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)
                    if not UserInputService:GetFocusedTextBox() then
                        if Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA then
                            Up = 1
                        elseif Input.KeyCode == Enum.KeyCode.LeftShift or Input.KeyCode == Enum.KeyCode.ButtonL2 then
                            Down = -1
                        end
                    end
                end))
                Fly:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)
                    if Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA then
                        Up = 0
                    elseif Input.KeyCode == Enum.KeyCode.LeftShift or Input.KeyCode == Enum.KeyCode.ButtonL2 then
                        Down = 0
                    end
                end))
                if UserInputService.TouchEnabled then
                    pcall(function()
                        local JumpButton: ImageButton = LocalPlayer.PlayerGui.TouchGui.TouchControlFrame.JumpButton
                        Fly:Clean(JumpButton:GetPropertyChangedSignal("ImageRectOffset"):Connect(function()
                            Up = JumpButton.ImageRectOffset.X == 146 and 1 or 0
                        end))
                    end)
                end
            else
                bedwars.BalloonController.deflateBalloon = Old
                if PopBalloons.Enabled and Entity.isAlive and (LocalPlayer.Character:GetAttribute("InflatedBalloons") or 0) > 0 then
                    for _ = 1, 3 do
                        bedwars.BalloonController:deflateBalloon()
                    end
                end
            end
        end,
        ExtraText = function()
            return "Heatseeker"
        end,
        Tooltip = "Makes you go zoom."
    })

    Value = Fly:CreateSlider({
        Name = "Speed",
        Min = 1,
        Max = 23,
        Default = 23,
        Suffix = function(Val: number)
            return Val == 1 and "stud" or "studs"
        end
    })
    VerticalValue = Fly:CreateSlider({
        Name = "Vertical Speed",
        Min = 1,
        Max = 150,
        Default = 50,
        Suffix = function(Val: number)
            return Val == 1 and "stud" or "studs"
        end
    })
    WallCheck = Fly:CreateToggle({
        Name = "Wall Check",
        Default = true
    })
    PopBalloons = Fly:CreateToggle({
        Name = "Pop Balloons",
        Default = true
    })
    TeleportDown = Fly:CreateToggle({
        Name = "TP Down",
        Default = true
    })
    ShowProgressbar = Fly:CreateToggle({
        Name = "Show Progressbar",
        Default = true,
        Function = function(Callback: boolean)
            RemoveBar()
            if Callback and Fly.Enabled then
                Bar = CreateProgressBar()
            end
        end,
        Tooltip = "Shows a bar counting down to the next TP Down while you have no balloons"
    })
end)

Run(function()
	local Mode
	local Expand
	local Objects, Patched = setmetatable({}, {__mode = "k"})
	
	local function CreateHitbox(Ent)
	    if Ent.Targetable and Ent.Player then
	        local Hitbox: Part = Instance.new("Part")
	        Hitbox.Size = Vector3.new(3, 6, 3) + Vector3.one * (Expand.Value / 5)
	        Hitbox.Position = Ent.RootPart.Position
	        Hitbox.CanCollide = false
	        Hitbox.Massless = true
	        Hitbox.Transparency = 1
	        Hitbox.LocalTransparencyModifier = 1
	        Hitbox.Parent = Ent.Character
	        local Weld: Motor6D = Instance.new("Motor6D")
	        Weld.Part0 = Hitbox
	        Weld.Part1 = Ent.RootPart
	        Weld.Parent = Hitbox
	        Objects[Ent] = Hitbox
	    end
	end
	
	HitBoxes = vape.Categories.Blatant:CreateModule({
	    Name = "HitBoxes",
	    Function = function(Callback: boolean)
	        if Callback then
	            if Mode.Value == "Sword" then
	                debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, (Expand.Value / 3))
	                Patched = true
	            else
	                HitBoxes:Clean(Entity.Events.EntityAdded:Connect(CreateHitbox))
	                HitBoxes:Clean(Entity.Events.EntityRemoved:Connect(function(Ent)
	                    if Objects[Ent] then
	                        Objects[Ent]:Destroy()
	                        Objects[Ent] = nil
	                    end
	                end))
	                for _, v: any in Entity.List do
	                    CreateHitbox(v)
	                end
	            end
	        else
	            if Patched then
	                debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, 3.8)
	                Patched = nil
	            end
	            for _, v: Part in Objects do
	                v:Destroy()
	            end
	            table.clear(Objects)
	        end
	    end,
	    Tooltip = "Expands attack hitbox"
	})
	
	Mode = HitBoxes:CreateDropdown({
	    Name = "Mode",
	    List = {"Sword", "Player"},
	    Function = function()
	        if HitBoxes.Enabled then
	            HitBoxes:Toggle()
	            HitBoxes:Toggle()
	        end
	    end,
	    Tooltip = "Sword - Increases the range around you to hit entities\nPlayer - Increases the players hitbox"
	})
	Expand = HitBoxes:CreateSlider({
	    Name = "Expand amount",
	    Min = 0,
	    Max = 14.4,
	    Decimal = 10,
	    Function = function(Val: number)
	        if HitBoxes.Enabled then
	            if Mode.Value == "Sword" then
	                debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, (Val / 3))
	            else
	                for _, v: Part in Objects do
	                    v.Size = Vector3.new(3, 6, 3) + Vector3.one * (Val / 5)
	                end
	            end
	        end
	    end,
	    Default = 14.4,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
end)

Run(function()
	local InfiniteFly
	local VerticalValue
	local Label, ShadowLabel
	local Up, Down = 0, 0
	local Landing: boolean = false
	
	local HiddenPart: Part = Instance.new("Part")
	HiddenPart.Parent = workspace
	HiddenPart.Transparency = 1
	HiddenPart.CanQuery = false
	HiddenPart.CanTouch = false
	HiddenPart.CanCollide = false
	HiddenPart.Anchored = true
	vape:Clean(HiddenPart)
	
	local OldTransparency: {[BasePart]: number} = setmetatable({}, {__mode = "k"})
	
	local function FindGround()
	    for _, v: Vector3 in {Entity.character.Humanoid.MoveDirection, Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(-1, 0, 0), Vector3.new(0, 0, -1)} do
	        for Step: number = 1, 4 do
	            local Ground: RaycastResult? = workspace:Blockcast((Entity.character.RootPart.CFrame + Vector3.new(0, 200, 0)) + (v * Step), Vector3.new(3, 3, 3), Vector3.new(0, -1000, 0), store.airRay)
	            if Ground then
	                return Ground
	            end
	        end
	    end
	    return false
	end
	
	InfiniteFly = vape.Categories.Blatant:CreateModule({
	    Name = "InfiniteFly",
	    Function = function(Callback: boolean)
	        if Label and ShadowLabel then
	            Label.Visible = Callback
	            ShadowLabel.Visible = Callback
	        end
	        
	        if Callback then
	            if not Entity.isAlive or Landing or workspace:Raycast(Entity.character.RootPart.Position, Vector3.new(0, -1000, 0), store.airRay) then
	                notif("InfiniteFly", "Cannot fly at this state.", 8, "warning")
	                InfiniteFly:Toggle()
	                return
	            end
	            if Entity.isAlive then
	                Camera.CameraSubject = HiddenPart
	                for _, v: BasePart in Entity.character.Character:QueryDescendants("BasePart") do
	                    OldTransparency[v] = v.Transparency
	                    v.Transparency = 1
	                end
	            end
	
	            HiddenPart.CFrame = Entity.character.Character.Head.CFrame
	            store.infinitefly = true
	            vape.MovementOwner = "InfiniteFly"
	            Landing = true
	
	            local Root: BasePart = Entity.character.RootPart
	            local Start: CFrame = CFrame.new(Root.Position)
	            Root.CFrame = Start
	            InfiniteFly:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)
	                if not UserInputService:GetFocusedTextBox() then
	                    if Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA then
	                        Up = 1
	                    elseif Input.KeyCode == Enum.KeyCode.LeftShift or Input.KeyCode == Enum.KeyCode.ButtonL2 then
	                        Down = -1
	                    end
	                end
	            end))
	            InfiniteFly:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)
	                if Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA then
	                    Up = 0
	                elseif Input.KeyCode == Enum.KeyCode.LeftShift or Input.KeyCode == Enum.KeyCode.ButtonL2 then
	                    Down = 0
	                end
	            end))
	            InfiniteFly:Clean(RunService.PreSimulation:Connect(function(Delta: number)
	                if vape.ThreadFix then
	                    setthreadidentity(8)
	                end
	
	                if not Entity.isAlive or not Root or not isnetworkowner(Root) then
	                    notif("InfiniteFly", "Network ownership disowned", 10, "alert")
	                    InfiniteFly:Toggle()
	                    return
	                end
	
	                if workspace:Raycast(Root.Position, Vector3.new(0, -1000, 0), store.airRay) then
	                    notif("InfiniteFly", "Landing", 3.5, "alert")
	                    InfiniteFly:Toggle()
	                    return
	                end
	
	                local AnchorCFrame: CFrame = CFrame.new(Vector3.new(Root.Position.X, HiddenPart.CFrame.Y, Root.Position.Z))
	                if vape.ThreadFix then
	                    setthreadidentity(8)
	                end
	
	                HiddenPart.CFrame = AnchorCFrame + Vector3.new(0, Delta * ((Up + Down) * VerticalValue.Value), 0)
	                if Label and ShadowLabel then
	                    if vape.ThreadFix then
	                        setthreadidentity(8)
	                    end
	
	                    Label.Text = `{math.round((Start.Position - AnchorCFrame.Position).Magnitude / 3)} blocks`
	                    ShadowLabel.Text = Label.Text
	                end
	                if Root.CFrame.Y <= (HiddenPart.CFrame.Y + 4) or FindGround() then
	                    if vape.ThreadFix then
	                        setthreadidentity(8)
	                    end
	
	                    Root.CFrame = CFrame.lookAlong(Vector3.new(Root.CFrame.X, (HiddenPart.CFrame.Y + 4) + 125, Root.CFrame.Z), Root.CFrame.LookVector)
	                end
	            end))
	        elseif store.infinitefly then
	            store.infinitefly = false
	            local NoFall = vape.Modules.NoFall
	            if NoFall and not NoFall.Enabled then
	                NoFall:Toggle()
	            end
	            task.wait(0.3)
	            local Ground = Entity.isAlive and FindGround()
	            if Ground then
	                Entity.character.RootPart.CFrame = CFrame.new(Ground.Position + Vector3.new(0, 3.5, 0))
	                Entity.character.RootPart.AssemblyLinearVelocity = Vector3.zero
	            end
	            notif("InfiniteFly", "Landed", 2.5, "info")
	            Landing = false
	            if Entity.isAlive then
	                for _, v: BasePart in Entity.character.Character:QueryDescendants("BasePart") do
	                    v.Transparency = OldTransparency[v] or v.Transparency
	                end
	                Camera.CameraSubject = Entity.character.Character
	            end
	            if vape.MovementOwner == "InfiniteFly" then
	                vape.MovementOwner = nil
	            end
	        end
	    end,
	    Tooltip = "Makes you go zoom. Fly, InfiniteJump, HighJump, LongJump and the other movement modules except Speed stop working until it has fully landed",
	    ExtraText = function()
	        return "Heatseeker"
	    end
	})
	
	VerticalValue = InfiniteFly:CreateSlider({
	    Name = "Vertical Speed",
	    Min = 1,
	    Max = 150,
	    Default = 50,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	InfiniteFly:CreateToggle({
	    Name = "Show distance",
	    Function = function(Callback: boolean)
	        if Callback then
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            Label = Instance.new("TextLabel")
	            Label.Size = UDim2.fromOffset(100, 20)
	            Label.Position = UDim2.new(0.5, 6, 0.5, 60)
	            Label.BackgroundTransparency = 1
	            Label.AnchorPoint = Vector2.new(0.5, 0)
	            Label.Text = "0 blocks"
	            Label.ZIndex = 6
	            Label.TextColor3 = Color3.new(1, 1, 1)
	            Label.TextSize = 18
	            Label.RichText = true
	            Label.FontFace = vape.Libraries.uipallet.FontDisplay
	            Label.Visible = InfiniteFly.Enabled
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	            Label.Parent = vape.gui
	            ShadowLabel = Label:Clone()
	            ShadowLabel.ZIndex = 5
	            ShadowLabel.AnchorPoint = Vector2.new(0.5, 0)
	            ShadowLabel.Position += UDim2.fromOffset(1, 1)
	            ShadowLabel.Text = Label.ContentText
	            ShadowLabel.TextColor3 = Color3.new()
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	            ShadowLabel.Parent = vape.gui
	        else
	            if ShadowLabel then
	                if vape.ThreadFix then
	                    setthreadidentity(8)
	                end
	
	                ShadowLabel:Destroy()
	                ShadowLabel = nil
	            end
	            if Label then
	                if vape.ThreadFix then
	                    setthreadidentity(8)
	                end
	
	                Label:Destroy()
	                Label = nil
	            end
	        end
	    end,
	    Default = true
	})
	
end)

