	                                end
	
	                                local Delta: Vector3 = (v.RootPart.Position - SelfPosition)
	                                local Flat: Vector3 = Delta * FlatScale
	                                if Flat.Magnitude > 0.001 and math.acos(math.clamp(LocalFacing:Dot(Flat.Unit), -1, 1)) > (math.rad(AngleSlider.Value) / 2) then
