Run(function()
	local Value
	local CameraDirection
	local Start: Vector3?
	local JumpTick, JumpSpeed, Direction = tick(), 0
	local Coast: number = 1.1
	local ProjectileRemote = {InvokeServer = function() end}
	task.spawn(function()
	    ProjectileRemote = bedwars.Handler:Get("ProjectileFire").Remote.instance
	end)
	
	local Boosts = {
	    cannon = {Multiplier = 5.25, Duration = 2.3},
	    cat = {Multiplier = 4, Duration = 2.5},
	    grappling_hook = {Multiplier = 2.5, Duration = 2.5},
	    jade_hammer = {Multiplier = 1.4, Duration = 2.5},
	    wood_dao = {Multiplier = 4.5, Duration = 2.4}
	}
	for _, v: string in {"stone_dao", "iron_dao", "diamond_dao", "emerald_dao"} do
	    Boosts[v] = Boosts.wood_dao
	end
	Boosts.void_axe = Boosts.jade_hammer
	
	local function Scaled(Name: string)
	    local Boost = Boosts[Name]
	    if not Boost then
	        return nil
	    end
	    return Boost.Multiplier * Value.Value, Boost.Duration
	end
	
	local function JumpAbility(Item): string
	    return `{Item.itemType:find("jade_hammer") and "jade_hammer" or Item.itemType}_jump`
	end
	
	local function Ready(Name: string, Item): boolean
	    local Options = {disableBlockedAbilityAlert = true}
	    if Name == "cat" then
	        return bedwars.AbilityController:canUseAbility("CAT_POUNCE", Options)
	    elseif Name:find("_dao") then
	        return (LocalPlayer.Character:GetAttribute("CanDashNext") or 0) < workspace:GetServerTimeNow() and bedwars.AbilityController:canUseAbility("dash", Options)
	    elseif Boosts[Name] == Boosts.jade_hammer then
	        return bedwars.AbilityController:canUseAbility(JumpAbility(Item), Options)
	    end
	    return true
	end
	
	local function Knockback(DamageTable)
	    if DamageTable.entityInstance ~= LocalPlayer.Character or DamageTable.fromEntity ~= LocalPlayer.Character or DamageTable.knockbackMultiplier and DamageTable.knockbackMultiplier.disabled then
	        return nil
	    end
	
	    local Position: Vector3? = DamageTable.fromPosition and Vector3.new(DamageTable.fromPosition.X, DamageTable.fromPosition.Y, DamageTable.fromPosition.Z) or DamageTable.fromEntity and DamageTable.fromEntity.PrimaryPart.Position
	    if not Position then
	        return nil
	    end
	    local Speed: number = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {
	        vertical = 0,
	        horizontal = (DamageTable.knockbackMultiplier and DamageTable.knockbackMultiplier.horizontal or 1)
	    }).Magnitude * 1.1
	    return Speed, 2.5, Entity.character.RootPart.Position - Position
	end
	
	local function Transit(DataTable)
	    if DataTable.hookFunction == "PLAYER_IN_TRANSIT" then
	        return Scaled("grappling_hook")
	    end
	    return nil
	end
	
	local function Propel(LookVector: Vector3, Speed: number, Duration: number)
	    JumpSpeed = Speed
	    JumpTick = tick() + Duration
	    Direction = Vector3.new(LookVector.X, 0, LookVector.Z).Unit
	end
	
	local Launcher = {
	    Active = function(): boolean
	        return LongJump.Enabled
	    end,
	    Propel = Propel,
	    Anchor = function(Position: Vector3)
	        Start = Position
	    end,
	    Clean = function(Connection)
	        LongJump:Clean(Connection)
	    end
	}
	
	local LongJumpMethods = {
	    cannon = function(_, Position: Vector3, LookVector: Vector3, Launch)
	        Position = Position - Vector3.new(0, (Entity.character.HipHeight + (Entity.character.RootPart.Size.Y / 2)) - 3, 0)
	        local Rounded: Vector3 = Vector3.new(math.round(Position.X / 3) * 3, math.round(Position.Y / 3) * 3, math.round(Position.Z / 3) * 3)
	        bedwars.placeBlock(Rounded, "cannon", false)
	
	        task.delay(0, function()
	            local Block, BlockPosition = GetPlacedBlock(Rounded)
	            if Block and Block.Name == "cannon" and (Entity.character.RootPart.Position - Block.Position).Magnitude < 20 then
	                local BreakType = bedwars.ItemMeta[Block.Name].block.breakType
	                local Tool = Store.tools[BreakType]
	                if Tool then
	                    SwitchItem(Tool.tool)
	                end
	
	                bedwars.Handler:Get("AimCannon"):Fire("SendToServer", {
	                    cannonBlockPos = BlockPosition,
	                    lookVector = LookVector
	                })
	
	                local BreakDelay: number = 0.1
	                if bedwars.BlockController:calculateBlockDamage(LocalPlayer, {blockPosition = BlockPosition}) < Block:GetAttribute("Health") then
	                    BreakDelay = 0.4
	                    bedwars.breakBlock(Block, true, true)
	                end
	
	                task.delay(BreakDelay, function()
	                    for _ = 1, 3 do
	                        local Call = bedwars.Handler:Get("LaunchSelfFromCannon"):Fire("CallServer", {cannonBlockPos = BlockPosition})
	                        if Call then
	                            bedwars.breakBlock(Block, true, true)
	                            Launch.Propel(LookVector, Scaled("cannon"))
	                            break
	                        end
	                        task.wait(0.1)
	                    end
	                end)
	            end
	        end)
	    end,
	    cat = function(_, _, LookVector: Vector3, Launch)
	        Launch.Clean(VapeEvents.CatPounce.Event:Connect(function()
	            Launch.Propel(LookVector, Scaled("cat"))
	            Entity.character.RootPart.AssemblyLinearVelocity = Vector3.zero
	        end))
	
	        if not Ready("cat") then
	            repeat
	                task.wait()
	            until Ready("cat") or not Launch.Active()
	        end
	
	        if Ready("cat") and Launch.Active() then
	            bedwars.AbilityController:useAbility("CAT_POUNCE")
	        end
	    end,
	    fireball = function(Item, Position: Vector3?, LookVector: Vector3)
	        if not Position then
	            return
	        end
	
	        Position = Position - LookVector * 0.1
	        local ShootCFrame: CFrame = (CFrame.lookAlong(Position, Vector3.new(0, -60, 0)) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ)))
	        SwitchItem(Item.tool, 0)
	        task.wait(0.1)
	        local Result = ProjectileRemote:InvokeServer(Item.tool, "fireball", "fireball", ShootCFrame.Position, Position, ShootCFrame.LookVector * 60, bedwars.IdUtil.generateId(8), bedwars.getShotData(Item.itemType), workspace:GetServerTimeNow() - 0.045)
	        if type(Result) == "table" and Result.accepted then
	            local LaunchSound = bedwars.ItemMeta[Item.itemType].projectileSource.launchSound
	            LaunchSound = LaunchSound and LaunchSound[math.random(1, #LaunchSound)] or nil
	            if LaunchSound then
	                bedwars.AudioManager:playAudio(LaunchSound)
	            end
	        end
	    end,
	    grappling_hook = function(Item, Position: Vector3?, LookVector: Vector3)
	        if not Position then
	            return
	        end
	
	        Position = Position - LookVector * 0.1
	        local ShootCFrame: CFrame = (CFrame.lookAlong(Position, Vector3.new(0, -140, 0)) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ)))
	        SwitchItem(Item.tool, 0)
	        task.wait(0.1)
	        local Result = ProjectileRemote:InvokeServer(Item.tool, nil, "grappling_hook_projectile", ShootCFrame.Position, Position, ShootCFrame.LookVector * 140, bedwars.IdUtil.generateId(8), bedwars.getShotData(Item.itemType), workspace:GetServerTimeNow() - 0.045)
	        if type(Result) == "table" and Result.accepted then
	            local LaunchSound = bedwars.ItemMeta[Item.itemType].projectileSource.launchSound
	            LaunchSound = LaunchSound and LaunchSound[math.random(1, #LaunchSound)] or nil
	            if LaunchSound then
	                bedwars.AudioManager:playAudio(LaunchSound)
	            end
	        end
	    end,
	    jade_hammer = function(Item, Position: Vector3, LookVector: Vector3, Launch)
	        if not Ready("jade_hammer", Item) then
	            repeat
	                task.wait()
	            until Ready("jade_hammer", Item) or not Launch.Active()
	        end
	
	        if Ready("jade_hammer", Item) and Launch.Active() then
	            SwitchItem(Item.tool, 0)
	            LocalPlayer.Character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	            Launch.Anchor(Position + Vector3.new(0, 3.1, 0))
	            task.wait(0.1)
	            bedwars.AbilityController:useAbility(JumpAbility(Item))
	            Launch.Propel(LookVector, Scaled("jade_hammer"))
	        end
	    end,
	    tnt = function(Item, Position: Vector3?, LookVector: Vector3, Launch)
	        if not Position then
	            return
	        end
	
	        local Feet: Vector3 = Position - Vector3.new(0, (Entity.character.HipHeight + (Entity.character.RootPart.Size.Y / 2)) - 3, 0)
	        local Rounded: Vector3 = Vector3.new(math.round(Feet.X / 3) * 3, math.round(Feet.Y / 3) * 3, math.round(Feet.Z / 3) * 3)
	        Launch.Anchor(Vector3.new(Rounded.X, Position.Y, Rounded.Z) + (LookVector * (Item.itemType == "pirate_gunpowder_barrel" and 2.6 or 0.2)))
	        bedwars.placeBlock(Rounded, Item.itemType, false)
	    end,
	    wood_dao = function(Item, Position: Vector3, LookVector: Vector3, Launch)
	        if not Ready("wood_dao") then
	            repeat
	                task.wait()
	            until Ready("wood_dao") or not Launch.Active()
	        end
	
	        if Launch.Active() then
	            bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
	            SwitchItem(Item.tool, 0.1)
	            ReplicatedStorage["events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"].useAbility:FireServer("dash", {
	                direction = LookVector,
	                origin = Position,
	                weapon = Item.itemType
	            })
	            Launch.Propel(LookVector, Scaled("wood_dao"))
	        end
	    end
	}
	for _, v: string in {"stone_dao", "iron_dao", "diamond_dao", "emerald_dao"} do
	    LongJumpMethods[v] = LongJumpMethods.wood_dao
	end
	LongJumpMethods.void_axe = LongJumpMethods.jade_hammer
	LongJumpMethods.siege_tnt = LongJumpMethods.tnt
	LongJumpMethods.pirate_gunpowder_barrel = LongJumpMethods.tnt
	
	LongJump = vape.Categories.Blatant:CreateModule({
	    Name = "LongJump",
	    Function = function(Callback: boolean)
	        if Callback and vape.MovementOwner then
	            SendNotification("LongJump", `Unavailable until {vape.MovementOwner} has landed`, 3, "warning")
	            LongJump:Toggle()
	            return
	        end
	        FrictionTable.LongJump = Callback or nil
	        UpdateVelocity()
	        if Callback then
	            LongJump:Clean(VapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)
	                local Speed, Duration, Away = Knockback(DamageTable)
	                if Speed and Speed >= JumpSpeed then
	                    Propel(Away, Speed, Duration)
	                end
	            end))
	            LongJump:Clean(VapeEvents.GrapplingHookFunctions.Event:Connect(function(DataTable)
	                local Speed, Duration = Transit(DataTable)
	                if Speed then
	                    Propel(Entity.character.RootPart.CFrame.LookVector, Speed, Duration)
	                end
	            end))
	
	            Start = Entity.isAlive and Entity.character.RootPart.Position or nil
	            LongJump:Clean(RunService.PreSimulation:Connect(function(Delta: number)
	                local Root = Entity.isAlive and Entity.character.RootPart or nil
	                if vape.MovementOwner then
	                    return
	                elseif Root and isnetworkowner(Root) then
	                    if JumpTick > tick() then
	                        local CurrentSpeed: number = GetSpeed()
	                        local Destination: Vector3 = (Direction * math.max(((JumpTick - tick()) > Coast and JumpSpeed or 0), 0) * Delta)
	                        Root.CFrame += Destination
	                        Root.AssemblyLinearVelocity = (Direction * CurrentSpeed) + Vector3.new(0, 15, 0)
	                        Start = nil
	                    else
	                        if Start then
	                            Root.CFrame = CFrame.lookAlong(Start, Root.CFrame.LookVector)
	                        end
	                        Root.AssemblyLinearVelocity = Vector3.zero
	                        JumpSpeed = 0
	                    end
	                else
	                    Start = nil
	                end
	            end))
	
	            if Store.hand and LongJumpMethods[Store.hand.tool.Name] then
	                task.spawn(LongJumpMethods[Store.hand.tool.Name], GetItem(Store.hand.tool.Name), Start, (CameraDirection.Enabled and Camera or Entity.character.RootPart).CFrame.LookVector, Launcher)
	                return
	            end
	
	            for Name: string, Method: (...any) -> ...any in LongJumpMethods do
	                local Item = GetItem(Name, nil, true)
	                if Item or Store.equippedKit == Name then
	                    task.spawn(Method, Item, Start, (CameraDirection.Enabled and Camera or Entity.character.RootPart).CFrame.LookVector, Launcher)
	                    break
	                end
	            end
	        else
	            JumpTick = tick()
	            Direction = nil
	            JumpSpeed = 0
	        end
	    end,
	    ExtraText = function()
	        return "Heatseeker"
	    end,
	    Tooltip = "Lets you jump farther"
	})
	LongJump.Launch = {
	    Methods = LongJumpMethods,
	    Coast = Coast,
	    Ready = Ready,
	    Scaled = Scaled,
	    Knockback = Knockback,
	    Transit = Transit
	}
	
	Value = LongJump:CreateSlider({
	    Name = "Speed",
	    Min = 1,
	    Max = 37,
	    Default = 37,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	CameraDirection = LongJump:CreateToggle({
	    Name = "Camera Direction"
	})
end)

Run(function()
	local NoFall
	local Damage
	local Disabled: {[Humanoid]: {any}} = setmetatable({}, {__mode = "k"})
	local GroundHit = bedwars.Handler:Get("GroundHit")
	
	NoFall = vape.Categories.Blatant:CreateModule({
	    Name = "NoFall",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Humanoid = Entity.isAlive and Entity.character.Humanoid
	            if canDebug and Humanoid and not Disabled[Humanoid] and getconnections then
	                Disabled[Humanoid] = {}
	                for _, v: any in getconnections(Humanoid.StateChanged) do
	                    v:Disable()
	                    table.insert(Disabled[Humanoid], v)
	                end
	            end
	
	            local Tracked: number = 0
	            NoFall:Clean(RunService.PostSimulation:Connect(function()
	                if Entity.isAlive and Store.matchState == 1 and not Store.cannonFlight and not Store.infinitefly then
	                    local Root: BasePart = Entity.character.RootPart
	                    local Velocity: Vector3 = Root.AssemblyLinearVelocity
	
	                    if Tracked < -(45 + (Damage.Value * 0.75)) then
	                        local Cushion: Vector3 = Vector3.new(0, 2.5, 0)
	                        Root.AssemblyLinearVelocity = Cushion
	                        Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Landed)
	                        RunService.PreRender:Wait()
	                        if Root.AssemblyLinearVelocity == Cushion then
	                            Root.AssemblyLinearVelocity = Velocity
	                        end
	                        GroundHit:Fire("SendToServer", nil, Vector3.new(0, Tracked, 0), workspace:GetServerTimeNow())
	                    end
	                    Tracked = Velocity.Y
	                else
	                    Tracked = 0
	                end
	            end))
	
	            NoFall:Clean(Entity.Events.LocalAdded:Connect(function(Ent)
	                if Ent.Humanoid:WaitForChild("Animator", 5) then
	                    task.wait(0.5)
	                    if canDebug and NoFall.Enabled and not Disabled[Ent.Humanoid] and getconnections then
	                        Disabled[Ent.Humanoid] = {}
	                        for _, v: any in getconnections(Ent.Humanoid.StateChanged) do
	                            v:Disable()
	                            table.insert(Disabled[Ent.Humanoid], v)
	                        end
	                    end
	                end
	            end))
	        else
	            for _, Connections: {any} in Disabled do
	                for _, v: any in Connections do
	                    v:Enable()
	                end
	            end
	
	            table.clear(Disabled)
	        end
	    end,
	    Tooltip = "Prevents taking fall damage."
	})
	
	Damage = NoFall:CreateSlider({
	    Name = "Damage",
	    Min = 0,
	    Max = 100,
	    Default = 0,
	    Suffix = "%",
	    Tooltip = "How much of each fall lands on you, it only starts saving you once you are dropping faster than this lets through"
	})
end)

Run(function()
	local Old: (...any) -> ...any
	
	vape.Categories.Blatant:CreateModule({
	    Name = "NoSlow",
	    Function = function(Callback: boolean)
	        local Modifier = bedwars.SprintController:getMovementStatusModifier()
	        if Callback then
	            Old = Modifier.addModifier
	            Modifier.addModifier = function(self, NewModifier)
	                if NewModifier.moveSpeedMultiplier then
	                    NewModifier.moveSpeedMultiplier = math.max(NewModifier.moveSpeedMultiplier, 1)
	                end
	                return Old(self, NewModifier)
	            end
	
	            for ActiveModifier: any in Modifier.modifiers do
	                if (ActiveModifier.moveSpeedMultiplier or 1) < 1 then
	                    Modifier:removeModifier(ActiveModifier)
	                end
	            end
	        else
	            Modifier.addModifier = Old
	        end
	    end,
	    Tooltip = "Prevents slowing down when using items."
	})
end)

Run(function()
	local OwlAura
	local Targets
	local Mode
	local Range
	local LastOwl: Instance?
	
	OwlAura =vape.Categories.Blatant:CreateModule({
	    Name = "OwlAura",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Owls = Collection("Owl", OwlAura, function(List, Object)
	                task.delay(1, function()
	                    if Object and Object.Parent and Object:GetAttribute("Owner") == LocalPlayer.UserId then
	                        table.insert(List, Object)
	                    end
	                end)
	            end)
	            repeat
	                if Store.equippedKit ~= "owl" then
	                    task.wait(1)
	                    continue
	                end
	
	                if Entity.isAlive then
	                    local Owl = Owls[1]
	                    if Owl then
	                        local Origin: Vector3 = Owl.Part.Position
	                        local Ent = Entity.EntityPosition({
	                            Origin = Origin,
	                            Range = Range.Value,
	                            Part = "RootPart",
	                            Players = Targets.Players.Enabled,
	                            NPCs = Targets.NPCs.Enabled,
	                            Priority = Targets.Priority.Value,
	                            Wallcheck = Targets.Walls.Enabled,
	                            Sort = SortMethods[Mode.Value]
	                        })
	
	                        if Ent then
	                            local ProjectileMeta = bedwars.ProjectileMeta.owl_projectile
	                            local TargetVelocity: Vector3 = Ent.RootPart.AssemblyLinearVelocity
	                            local TargetAirborne: boolean = Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(TargetVelocity.Y) > 0.01
	                            local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(Origin, ProjectileMeta.launchVelocity, ProjectileMeta.gravitationalAcceleration, Ent.RootPart.Position, TargetVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, Store.airRay, TargetAirborne, Ent.RootPart.Position, Ent.RootPart, nil, true)
	                            if AimPosition and TravelTime and TravelTime <= (ProjectileMeta.lifetimeSec or 3) then
	                                local Direction: Vector3 = CFrame.lookAt(Origin, AimPosition).LookVector * ProjectileMeta.launchVelocity
	                                LastOwl = Owl.Part
	                                bedwars.Handler:Get("OwlAiming"):Fire("SendToServer", {
	                                    owl = Owl.Part,
	                                    starting = true
	                                })
	                                bedwars.Handler:Get("OwlFireProjectile"):Fire("SendToServer", {
	                                    ProjectileRefId = bedwars.IdUtil.generateId(8),
	                                    direction = Direction,
	                                    fromPosition = Origin,
	                                    initialVelocity = Direction
	                                })
	                                task.wait(Store.ping.total or 0)
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not OwlAura.Enabled
	        elseif LastOwl then
	            bedwars.Handler:Get("OwlAiming"):Fire("SendToServer", {
	                owl = LastOwl,
	                starting = false
	            })
	            LastOwl = nil
	        end
	    end,
	    Tooltip = "Automatically shoots projectiles with whisper kit"
	})
	
	Targets = OwlAura:CreateTargets({
	    Players = true,
	    Wallcheck = true
	})
	local Methods: {string} = {"Distance", "Damage"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Mode = OwlAura:CreateDropdown({
	    Name = "Target mode",
	    List = Methods,
	    Default = "Distance"
	})
	Range = OwlAura:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 50,
	    Default = 50,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
end)

Run(function()
	local ProjectileAimbot
	local TargetPart
	local Targets
	local Sort
	local FOV
	local Distance
	local CircleColor
	local CircleTransparency
	local CircleThickness
	local CircleFilled
	local CircleObject
	local Horizontal
	local Vertical
	local AutoCharge
	local Aim = {}
	local OtherProjectiles
	local UseUmeko
	local Potions
	local Blacklist
	local Old, Hook
	local ArcCheck: RaycastParams = RaycastParams.new()
	ArcCheck.FilterType = Enum.RaycastFilterType.Exclude
	
	local function GetMouseOrigin()
	    return UserInputService.TouchEnabled and Camera.ViewportSize / 2 or UserInputService:GetMouseLocation()
	end
	
	ProjectileAimbot = vape.Categories.Blatant:CreateModule({
	    Name = "ProjectileAimbot",
	    Function = function(Callback: boolean)
	        if Callback and not canDebug then
	            SendNotification("ProjectileAimbot", "This executor cannot hook native projectile launches. Use AimAssist instead", 5)
	            ProjectileAimbot:Toggle()
	            return
	        end
	        if CircleObject then
	            CircleObject.Visible = Callback
	        end
	
	        if Callback then
	            local function UpdateCircle()
	                if CircleObject then
	                    CircleObject.Position = GetMouseOrigin()
	                end
	            end
	
	            ProjectileAimbot:Clean(RunService.RenderStepped:Connect(UpdateCircle))
	            ProjectileAimbot:Clean(Camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
	                UpdateCircle()
	            end))
	            if Hook then
	                return
	            end
	            Old = bedwars.ProjectileController.calculateImportantLaunchValues
	            local function AimLaunchValues(self, LaunchData, WorldMeta, Origin, ShootPosition: Vector3?)
	                local LaunchPosition: Vector3? = ShootPosition or self:getLaunchPosition(Origin)
	                if not LaunchPosition then
	                    return
	                end
	
	                if LaunchData.projectile:find("splash_potion") then
	                    if not Potions.Enabled then
	                        return
	                    end
	                elseif (not OtherProjectiles.Enabled) and not LaunchData.projectile:find("arrow") and not (UseUmeko.Enabled and LaunchData.projectile:find("^ninja_chakram")) then
	                    return
	                end
	
	                if table.find(Blacklist.ListEnabled or {}, ((LaunchData.projectile == "glue_trap" or LaunchData.projectile == "glue_projectile") and "gloop" or LaunchData.projectile)) then
	                    return
	                end
	
	                local ProjectileMeta = LaunchData:getProjectileMeta()
	                local Lifetime: number = (WorldMeta and ProjectileMeta.predictionLifetimeSec or ProjectileMeta.lifetimeSec or 3)
	                local Gravity: number = (ProjectileMeta.gravitationalAcceleration or 196.2) * LaunchData.gravityMultiplier
	                local ProjectileSpeed: number = (ProjectileMeta.launchVelocity or 100) * ((AutoCharge.Enabled or not Aim.Enabled) and 1 or LaunchData.velocityMultiplier)
	                local OffsetPosition: Vector3 = LaunchPosition + (LaunchData.projectile == "owl_projectile" and Vector3.zero or LaunchData.fromPositionOffset)
	                local Tool = Store.hand.tool
	                local PartName: string = TargetPart.Value == "Dynamic" and (IsHeadshotProjectile(Tool and Tool.Name) and "Head" or "RootPart") or TargetPart.Value
	                local Filtered: boolean = false
	
	                local function GetLaunchValues(Ent)
	                    local Balloons: number? = Ent.Character:GetAttribute("InflatedBalloons")
	                    local PlayerGravity: number = workspace.Gravity
	
	                    if Balloons and Balloons > 0 then
	                        PlayerGravity = (workspace.Gravity * (1 - ((Balloons >= 4 and 1.2 or Balloons >= 3 and 1 or 0.975))))
	                    end
	
	                    if Ent.Character.PrimaryPart:FindFirstChild("rbxassetid://8200754399") then
	                        PlayerGravity = 6
	                    end
	
	                    if Ent.Player and Ent.Player:GetAttribute("IsOwlTarget") then
	                        for _, v: Instance in CollectionService:GetTagged("Owl") do
	                            if v:GetAttribute("Target") == Ent.Player.UserId and v:GetAttribute("Status") == 2 then
	                                PlayerGravity = 0
	                            end
	                        end
	                    end
	
	                    local AimPart: BasePart = GetTargetPart(Ent, PartName)
	                    local Velocity: Vector3 = LaunchData.projectile == "telepearl" and Vector3.zero or AimPart.AssemblyLinearVelocity
	                    local Airborne: boolean = Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01
	                    local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(OffsetPosition, ProjectileSpeed, Gravity, AimPart.Position, Velocity, PlayerGravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, Store.airRay, Airborne, Ent.RootPart.Position, Ent.RootPart, nil, true)
	                    if AimPosition and TravelTime and (Horizontal.Value ~= 1 or Vertical.Value ~= 1) then
	                        local Rise: number = (Velocity.Y * TravelTime) - (PlayerGravity * TravelTime * TravelTime * 0.5)
	                        local Lead: Vector3 = Vector3.new(Velocity.X * TravelTime * (Horizontal.Value - 1), Rise * (Vertical.Value - 1), Velocity.Z * TravelTime * (Horizontal.Value - 1))
	                        local AdjustedPosition, _, AdjustedTime = PredictionLib.SolveTrajectory(OffsetPosition, ProjectileSpeed, Gravity, AimPart.Position + Lead, Velocity, PlayerGravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, Store.airRay, Airborne, Ent.RootPart.Position, Ent.RootPart, nil, true)
	                        if AdjustedPosition then
	                            AimPosition, TravelTime = AdjustedPosition, AdjustedTime or TravelTime
	                        end
	                    end
	
	                    if not AimPosition or not TravelTime or TravelTime > Lifetime then
	                        return nil
	                    end
	
	                    Store.hitchance.ProjectileAimbot = {Value = GetHitChance(Ent, TravelTime), Clock = tick()}
	                    local LaunchVelocity: Vector3 = (AimPosition - OffsetPosition).Unit * ProjectileSpeed
	                    if Targets.Walls.Enabled and TravelTime then
	                        if not Filtered then
	                            local IgnoreList: {Instance} = {Camera, LocalPlayer.Character}
	                            for _, v: any in Entity.List do
	                                if v.Character then
	                                    table.insert(IgnoreList, v.Character)
	                                end
	                            end
	                            ArcCheck.FilterDescendantsInstances = IgnoreList
	                            Filtered = true
	                        end
	
	                        if not PredictionLib.IsTrajectoryClear(OffsetPosition, LaunchVelocity, Gravity, TravelTime, ArcCheck) then
	                            return nil
	                        end
	                    end
	
	                    return {
	                        initialVelocity = LaunchVelocity,
	                        positionFrom = OffsetPosition,
	                        deltaT = Lifetime,
	                        gravitationalAcceleration = Gravity,
	                        drawDurationSeconds = AutoCharge.Enabled and 5 or LaunchData.drawDurationSeconds
	                    }
	                end
	
	                local Values, Attempts, Started = nil, 0, os.clock()
	                local Ent = Entity.EntityMouse({
	                    Part = "RootPart",
	                    Range = FOV.Value,
	                    Players = Targets.Players.Enabled,
	                    NPCs = Targets.NPCs.Enabled,
	                    Priority = Targets.Priority.Value,
	                    Origin = Entity.isAlive and (ShootPosition or Entity.character.RootPart.Position) or Vector3.zero,
	                    MouseOrigin = GetMouseOrigin(),
	                    Sort = SortMethods[Sort.Value],
	                    Check = function(Candidate)
	                        if (Candidate.RootPart.Position - Entity.character.RootPart.Position).Magnitude > Distance.Value then
	                            return false
	                        end
	                        if Attempts >= 10 or (Attempts > 0 and (os.clock() - Started) > 0.0015) then
	                            return false
	                        end
	                        Attempts += 1
	                        Values = GetLaunchValues(Candidate)
	                        return Values ~= nil
	                    end
	                })
	
	                if Ent and Values then
	                    TargetInfo.Targets[Ent] = tick() + 1
	                    return Values
	                end
	            end
	
	            Hook = function(self, LaunchData, WorldMeta, Origin, ShootPosition: Vector3?, ...)
	                if ProjectileAimbot.Enabled then
	                    local Success, Values = pcall(AimLaunchValues, self, LaunchData, WorldMeta, Origin, ShootPosition)
	                    if Success and Values then
	                        return Values
	                    end
	                end
	
	                return Old(self, LaunchData, WorldMeta, Origin, ShootPosition, ...)
	            end
	            bedwars.ProjectileController.calculateImportantLaunchValues = Hook
	        elseif Hook and bedwars.ProjectileController.calculateImportantLaunchValues == Hook then
	            bedwars.ProjectileController.calculateImportantLaunchValues = Old
	            Old, Hook = nil, nil
	        end
	    end,
	    Tooltip = "Silently adjusts your aim towards the enemy"
	})
	
	Targets = ProjectileAimbot:CreateTargets({
	    Players = true,
	    Walls = true
	})
	local Methods: {string} = {"Distance", "Damage"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Sort = ProjectileAimbot:CreateDropdown({
	    Name = "Target mode",
	    List = Methods,
	    Default = "Distance"
	})
	TargetPart = ProjectileAimbot:CreateDropdown({
	    Name = "Part",
	    List = {"RootPart", "Head", "Torso", "Left arm", "Right arm", "Left leg", "Right leg", "Random", "Dynamic"},
	    Tooltip = "Dynamic aims at the head with headshot-capable bows, including tactical bows and Archer, and at the body with everything else"
	})
	FOV = ProjectileAimbot:CreateSlider({
	    Name = "FOV",
	    Min = 1,
	    Max = 1000,
	    Function = function(Val: number)
	        if CircleObject then
	            CircleObject.Radius = Val
	        end
	    end,
	    Default = 1000
	})
	Distance = ProjectileAimbot:CreateSlider({
	    Name = "Distance",
	    Min = 1,
	    Max = 1000,
	    Default = 1000,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end,
	    Tooltip = "Maximum enemy distance from you"
	})
	ProjectileAimbot:CreateToggle({
	    Name = "Range Circle",
	    Function = function(Callback: boolean)
	        if Callback then
	            CircleObject = Drawing.new("Circle")
	            CircleObject.Filled = CircleFilled.Enabled
	            CircleObject.Color = Color3.fromHSV(CircleColor.Hue, CircleColor.Sat, CircleColor.Value)
	            CircleObject.Position = GetMouseOrigin()
	            CircleObject.Radius = FOV.Value
	            CircleObject.NumSides = 100
	            CircleObject.Thickness = CircleThickness.Value
	            CircleObject.Transparency = 1 - CircleTransparency.Value
	            CircleObject.Visible = ProjectileAimbot.Enabled
	        else
	            pcall(function()
	                CircleObject.Visible = false
	                CircleObject:Remove()
	            end)
	            CircleObject = nil
	        end
	        CircleColor.Object.Visible = Callback
	        CircleTransparency.Object.Visible = Callback
	        CircleThickness.Object.Visible = Callback
	        CircleFilled.Object.Visible = Callback
	    end
	})
	CircleColor = ProjectileAimbot:CreateColorSlider({
	    Name = "Circle Color",
	    Function = function(Hue: number, Sat: number, Val: number)
	        if CircleObject then
	            CircleObject.Color = Color3.fromHSV(Hue, Sat, Val)
	        end
	    end,
	    Darker = true,
	    Visible = false
	})
	CircleTransparency = ProjectileAimbot:CreateSlider({
	    Name = "Transparency",
	    Min = 0,
	    Max = 1,
	    Decimal = 10,
	    Function = function(Val: number)
	        if CircleObject then
	            CircleObject.Transparency = 1 - Val
	        end
	    end,
	    Darker = true,
	    Default = 0.5,
	    Visible = false
	})
	CircleThickness = ProjectileAimbot:CreateSlider({
	    Name = "Thickness",
	    Min = 1,
	    Max = 10,
	    Decimal = 10,
	    Function = function(Val: number)
	        if CircleObject then
	            CircleObject.Thickness = Val
	        end
	    end,
	    Darker = true,
	    Default = 1,
	    Visible = false,
	    Tooltip = "How wide the circle's outline is, has no effect while Circle Filled is on"
	})
	CircleFilled = ProjectileAimbot:CreateToggle({
	    Name = "Circle Filled",
	    Function = function(Callback: boolean)
	        if CircleObject then
	            CircleObject.Filled = Callback
	        end
	    end,
	    Darker = true,
	    Visible = false
	})
	Horizontal = ProjectileAimbot:CreateSlider({
	    Name = "Horizontal prediction",
	    Min = 0,
	    Max = 2,
	    Default = 1,
	    Decimal = 100,
	    Tooltip = "Scales how far ahead of the target you aim sideways"
	})
	Vertical = ProjectileAimbot:CreateSlider({
	    Name = "Vertical prediction",
	    Min = 0,
	    Max = 2,
	    Default = 1,
	    Decimal = 100,
	    Tooltip = "Scales how far ahead of the target you aim while it rises or falls"
	})
	AutoCharge = ProjectileAimbot:CreateToggle({
	    Name = "Auto Charge",
	    Function = function(Callback: boolean)
	        if Aim.Object then
	            Aim.Object.Visible = Callback
	        end
	    end,
	    Default = true,
	    Tooltip = "Fully charges your bow, Allowing your projectile to deal more damage"
	})
	Aim = ProjectileAimbot:CreateToggle({
	    Name = "Aim change",
	    Default = true,
	    Darker = true,
	    Tooltip = "Changes your trajectory to match charge percentage."
	})
	OtherProjectiles = ProjectileAimbot:CreateToggle({
	    Name = "Other Projectiles",
	    Default = true,
	    Tooltip = "Aims everything that is not an arrow or a splash potion"
	})
	UseUmeko = ProjectileAimbot:CreateToggle({
	    Name = "Use umeko",
	    Tooltip = "Aims umeko's chakram even with Other Projectiles off"
	})
	Potions = ProjectileAimbot:CreateToggle({
	    Name = "Shoot pots",
	    Default = true,
	    Tooltip = "Aims heal, poison and sleep splash potions, separate from Other Projectiles"
