	task.spawn(RefreshList)
end)

Run(function()
	local Scaffold
	local Expand
	local Tower
	local Downwards
	local Diagonal
	local LimitItem
	local Mouse
	local FillColor
	local OutlineColor
	local Adjacent, LastPosition, Label, VisualBlock = {}, Vector3.zero
	local VisualTween, VisualPosition
	local VisualSpeed: number = 0.1
	
	for X: number = -3, 3, 3 do
	    for Y: number = -3, 3, 3 do
	        for Z: number = -3, 3, 3 do
	            local Offset: Vector3 = Vector3.new(X, Y, Z)
	            if Offset ~= Vector3.zero then
	                table.insert(Adjacent, Offset)
	            end
	        end
	    end
	end
	
	local function NearCorner(BlockPosition: Vector3, Position: Vector3): Vector3
	    local StartPosition: Vector3 = BlockPosition - Vector3.new(3, 3, 3)
	    local EndPosition: Vector3 = BlockPosition + Vector3.new(3, 3, 3)
	    local Check: Vector3 = BlockPosition + (Position - BlockPosition).Unit * 100
	    return Vector3.new(math.clamp(Check.X, StartPosition.X, EndPosition.X), math.clamp(Check.Y, StartPosition.Y, EndPosition.Y), math.clamp(Check.Z, StartPosition.Z, EndPosition.Z))
	end
	getgenv().nearCorner = NearCorner
	
	local function BlockProximity(Position: Vector3): Vector3?
	    local Magnitude, Closest = 60
	    local Blocks = GetBlocksInPoints(bedwars.BlockController:getBlockPosition(Position - Vector3.new(21, 21, 21)), bedwars.BlockController:getBlockPosition(Position + Vector3.new(21, 21, 21)))
	    for _, v: Vector3 in Blocks do
	        local BlockPosition: Vector3 = NearCorner(v, Position)
	        local NewMagnitude: number = (Position - BlockPosition).Magnitude
	        if NewMagnitude < Magnitude then
	            Magnitude, Closest = NewMagnitude, BlockPosition
	        end
	    end
	    table.clear(Blocks)
	    return Closest
	end
	getgenv().blockProximity = BlockProximity
	
	local function CheckAdjacent(Position: Vector3): boolean
	    for _, v: Vector3 in Adjacent do
	        if GetPlacedBlock(Position + v) then
	            return true
	        end
	    end
	    return false
	end
	getgenv().checkAdjacent = CheckAdjacent
	
	local function GetScaffoldBlock()
	    if Store.hand.toolType == "block" then
	        return Store.hand.tool.Name, Store.hand.amount
	    elseif (not LimitItem.Enabled) then
	        local Wool, Amount = GetWool()
	        if Wool then
	            return Wool, Amount
	        else
	            for _, v: any in Store.inventory.inventory.items do
	                if bedwars.ItemMeta[v.itemType].block then
	                    return v.itemType, v.amount
	                end
	            end
	        end
	    end
	
	    return nil, 0
	end
	
	Scaffold = vape.Categories.Utility:CreateModule({
	    Name = "Scaffold",
	    Function = function(Callback: boolean)
	        if Label then
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            Label.Visible = Callback
	        end
	
	        if Callback then
	            repeat
	                if vape.ThreadFix then
	                    setthreadidentity(8)
	                end
	
	                if Entity.isAlive and not vape.MovementOwner then
	                    local Wool, Amount = GetScaffoldBlock()
	
	                    if Mouse.Enabled then
	                        if not UserInputService:IsMouseButtonPressed(0) then
	                            Wool = nil
	                        end
	                    end
	
	                    if Label then
	                        Amount = Amount or 0
	                        if vape.ThreadFix then
	                            setthreadidentity(8)
	                        end
	
	                        Label.Text = `{Amount} <font color="rgb(170, 170, 170)">(Scaffold)</font>`
	                        Label.TextColor3 = Color3.fromHSV((Amount / 128) / 2.8, 0.86, 1)
	                    end
	
	                    if Wool then
	                        local Root: BasePart = Entity.character.RootPart
	                        if Tower.Enabled and UserInputService:IsKeyDown(Enum.KeyCode.Space) and (not UserInputService:GetFocusedTextBox()) then
	                            Root.AssemblyLinearVelocity = Vector3.new(Root.AssemblyLinearVelocity.X, 38, Root.AssemblyLinearVelocity.Z)
	                        end
	
	                        for Step: number = Expand.Value, 1, -1 do
	                            local CurrentPosition: Vector3 = RoundPosition(Root.Position - Vector3.new(0, Entity.character.HipHeight + (Downwards.Enabled and UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) and 4.5 or 1.5), 0) + Entity.character.Humanoid.MoveDirection * (Step * 3))
	                            if Diagonal.Enabled then
	                                if math.abs(math.round(math.deg(math.atan2(-Entity.character.Humanoid.MoveDirection.X, -Entity.character.Humanoid.MoveDirection.Z)) / 45) * 45) % 90 == 45 then
	                                    local Delta: Vector3 = (LastPosition - CurrentPosition)
	                                    if ((Delta.X == 0 and Delta.Z ~= 0) or (Delta.X ~= 0 and Delta.Z == 0)) and ((LastPosition - Root.Position) * Vector3.new(1, 0, 1)).Magnitude < 2.5 then
	                                        CurrentPosition = LastPosition
	                                    end
	                                end
	                            end
	
	                            if VisualBlock and CurrentPosition then
	                                local VisualTarget: Vector3 = bedwars.BlockController:getBlockPosition(CurrentPosition) * 3
	                                if VisualPosition ~= VisualTarget then
	                                    if vape.ThreadFix then
	                                        setthreadidentity(8)
	                                    end
	
	                                    if VisualTween then
	                                        VisualTween:Cancel()
	                                        VisualTween = nil
	                                    end
	
	                                    if VisualBlock.Parent == Camera then
	                                        VisualTween = TweenService:Create(VisualBlock, TweenInfo.new(VisualSpeed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CFrame = CFrame.new(VisualTarget)})
	                                        VisualTween:Play()
	                                    else
	                                        VisualBlock.CFrame = CFrame.new(VisualTarget)
	                                        VisualBlock.Parent = Camera
	                                    end
	                                    VisualPosition = VisualTarget
	                                end
	                            end
	
	                            local Block, BlockPosition = GetPlacedBlock(CurrentPosition)
	                            if not Block then
	                                BlockPosition = CheckAdjacent(BlockPosition * 3) and BlockPosition * 3 or BlockProximity(CurrentPosition)
	                                if BlockPosition then
	                                    task.delay(0, bedwars.placeBlock, BlockPosition, Wool, false)
	                                end
	                            end
	                            LastPosition = CurrentPosition
	                        end
	                    end
	                end
	                task.wait(0.03)
	            until not Scaffold.Enabled
	            if VisualTween then
	                VisualTween:Cancel()
	                VisualTween = nil
	            end
	            if VisualBlock then
	                if vape.ThreadFix then
	                    setthreadidentity(8)
	                end
	
	                VisualBlock.Parent = nil
	            end
	            VisualPosition = nil
	        end
	    end,
	    Tooltip = "Helps you make bridges/scaffold walk."
	})
	
	Expand = Scaffold:CreateSlider({
	    Name = "Expand",
	    Min = 1,
	    Max = 6
	})
	Tower = Scaffold:CreateToggle({
	    Name = "Tower",
	    Default = true
	})
	Downwards = Scaffold:CreateToggle({
	    Name = "Downwards",
	    Default = true
	})
	Diagonal = Scaffold:CreateToggle({
	    Name = "Diagonal",
	    Default = true
	})
	LimitItem = Scaffold:CreateToggle({Name = "Limit to items"})
	Mouse = Scaffold:CreateToggle({Name = "Require mouse down"})
	Scaffold:CreateToggle({
	    Name = "Visual",
	    Function = function(Callback: boolean)
	        if vape.ThreadFix then
	            setthreadidentity(8)
	        end
	
	        FillColor.Object.Visible = Callback
	        OutlineColor.Object.Visible = Callback
	        if Callback then
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            VisualBlock = Instance.new("Part")
	            VisualBlock.Size = Vector3.new(3, 3, 3)
	            VisualBlock.Anchored = true
	            VisualBlock.CanCollide = false
	            VisualBlock.CanQuery = false
	            VisualBlock.CanTouch = false
	            VisualBlock.CastShadow = false
	            VisualBlock.Transparency = 1
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            local Selection: SelectionBox = Instance.new("SelectionBox")
	            Selection.Adornee = VisualBlock
	            Selection.LineThickness = 0.04
	            Selection.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)
	            Selection.Transparency = 1 - OutlineColor.Opacity
	            Selection.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)
	            Selection.SurfaceTransparency = 1 - FillColor.Opacity
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            Selection.Parent = VisualBlock
	            bedwars.QueryUtil:setQueryIgnored(VisualBlock, true)
	        else
	            if VisualTween then
	                VisualTween:Cancel()
	                VisualTween = nil
	            end
	            if VisualBlock then
	                if vape.ThreadFix then
	                    setthreadidentity(8)
	                end
	
	                VisualBlock.Parent = nil
	            end
	            VisualPosition = nil
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            VisualBlock:Destroy()
	            VisualBlock = nil
	        end
	    end,
	    Tooltip = "Renders an overlay on the block about to be placed"
	})
	FillColor = Scaffold:CreateColorSlider({
	    Name = "Fill Color",
	    DefaultSat = 0,
	    DefaultOpacity = 0.4,
	    Darker = true,
	    Visible = false,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        if VisualBlock then
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            VisualBlock.SelectionBox.SurfaceColor3 = Color3.fromHSV(Hue, Sat, Val)
	            VisualBlock.SelectionBox.SurfaceTransparency = 1 - Opacity
	        end
	    end
	})
	OutlineColor = Scaffold:CreateColorSlider({
	    Name = "Outline Color",
	    DefaultValue = 0,
	    Darker = true,
	    Visible = false,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        if VisualBlock then
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            VisualBlock.SelectionBox.Color3 = Color3.fromHSV(Hue, Sat, Val)
	            VisualBlock.SelectionBox.Transparency = 1 - Opacity
	        end
	    end
	})
	Scaffold:CreateToggle({
	    Name = "Block Count",
	    Function = function(Callback: boolean)
	        if Callback then
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            Label = Instance.new("TextLabel")
	            Label.Size = UDim2.fromOffset(100, 20)
	            Label.Position = UDim2.new(0.5, 6, 0.5, 60)
	            Label.BackgroundTransparency = 1
	            Label.AnchorPoint = Vector2.new(0.5, 0)
	            Label.Text = "0"
	            Label.TextColor3 = Color3.new(0, 1, 0)
	            Label.TextSize = 18
	            Label.RichText = true
	            Label.Font = Enum.Font.Arial
	            Label.Visible = Scaffold.Enabled
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	            Label.Parent = vape.gui
	        else
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            Label:Destroy()
	            Label = nil
	        end
	    end
	})
	
end)

Run(function()
	local SetEmote
	local Emote
	local Track: AnimationTrack?
	
	local List, EmoteTypes = {}, {}
	for EmoteType: any, v: any in bedwars.EmoteMeta do
	    if EmoteType ~= bedwars.EmoteType.NONE and v.name and not EmoteTypes[v.name] then
	        EmoteTypes[v.name] = EmoteType
	        table.insert(List, v.name)
	    end
	end
	table.sort(List)
	
	local function CancelEmote()
	    if Entity.isAlive then
	        if Track then
	            Track:Stop()
	            Track:Destroy()
	            Track = nil
	        end
	        if LocalPlayer.Character:GetAttribute("PlayingEmote") then
	            LocalPlayer.Character:SetAttribute("PlayingEmote", nil)
	        end
	    end
	end
	
	SetEmote = vape.Categories.Utility:CreateModule({
	    Name = "SetEmote",
	    Function = function(Callback: boolean)
	        if Callback then
	            SetEmote:Toggle()
	            if Entity.isAlive then
	                local EmoteType = EmoteTypes[Emote.Value]
	                local Meta = bedwars.EmoteMeta[EmoteType]
	                if Meta then
	                    LocalPlayer.Character:SetAttribute("PlayingEmote", EmoteType)
	                    local PlayBeginSounds = bedwars.EmoteController.createEmoteBeginAudioPlayers or bedwars.EmoteController.playEmoteBeginSounds
	                    if PlayBeginSounds then
	                        PlayBeginSounds(bedwars.EmoteController, EmoteType, LocalPlayer)
	                    end
	                    local Animation = Meta.animation
	                    if not Animation and Meta.emoteDisplayType then
	                        local Display = bedwars.EmoteDisplayMeta[Meta.emoteDisplayType]
	                        Animation = Display and Display.animation
	                    end
	                    if Animation and not noAutoPlayAnimation then
	                        Track = LocalPlayer.Character.Humanoid:LoadAnimation(bedwars.GameAnimationUtil:getAnimation(Animation.type))
	                        Track.Looped = Animation.looped or false
	                        Track:Play(nil, nil, Animation.speed or 1)
	                    end
	                    if not Meta.animation then
	                        local Gui: BillboardGui = Instance.new("BillboardGui")
	                        Gui.Size = UDim2.fromScale(6, 2.5)
	                        Gui.StudsOffset = Vector3.new(0, 2, 0)
	                        Gui.AlwaysOnTop = true
	                        Gui.Adornee = LocalPlayer.Character.Head
	
	                        local Image: ImageLabel = Instance.new("ImageLabel")
	                        Image.AnchorPoint = Vector2.new(0.5, 1)
	                        Image.Position = UDim2.fromScale(0.5, 1)
	                        Image.Size = UDim2.fromScale(0, 0)
	                        Image.Image = Meta.image
	                        Image.BackgroundTransparency = 1
	                        Image.ImageTransparency = 1
	                        Image.ScaleType = Enum.ScaleType.Fit
	                        Image.Parent = Gui
	
	                        Gui.Parent = LocalPlayer.Character.Head
	                        TweenService:Create(Image, TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
	                            Position = UDim2.fromScale(0.5, 0.5),
	                            Size = UDim2.fromScale(1, 1),
	                            ImageTransparency = 0
	                        }):Play()
	                    end
	                    if Meta.allowMovement then
	                        task.delay(6, CancelEmote)
	                    else
	                        LocalPlayer.Character.Humanoid:GetPropertyChangedSignal("MoveDirection"):Once(CancelEmote)
	                    end
	                end
	            end
	        end
	    end,
	    Tooltip = "Plays the selected emote on your character, other players can see it too"
	})
	
	Emote = SetEmote:CreateDropdown({
	    Name = "Emote",
	    List = List,
	    Default = "nightmare"
	})
end)

Run(function()
	local ShopQuickBuy
	local HoldDelay
	local CPS
	
	local Holding: boolean = false
	local ClickThread: thread?
	
	local function GetShopId()
	    if not Entity.isAlive then
	        return nil
	    end
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local Id
	    for _, v: any in Store.shop do
	        if v.Shop and (v.RootPart.Position - LocalPosition).Magnitude <= 20 then
	            Id = v.Id
	        end
	    end
	    return Id
	end
	
	local function GetHoveredItem(): string?
	    local MousePosition: Vector2 = (UserInputService:GetMouseLocation() - GuiService:GetGuiInset())
	    for _, v: GuiObject in LocalPlayer.PlayerGui:GetGuiObjectsAtPosition(MousePosition.X, MousePosition.Y) do
	        local Object: Instance? = v
	        while Object and Object ~= LocalPlayer.PlayerGui do
	            local ItemType: string? = Object.Name:match("^(.+)_ShopItemCard$")
	            if ItemType then
	                return ItemType
	            end
	            Object = Object.Parent
	        end
	    end
	end
	
	local function StartClicking(ItemType: string)
	    if ClickThread then
	        task.cancel(ClickThread)
	    end
	    ClickThread = task.spawn(function()
	        repeat
	            local ShopId = bedwars.AppController:isAppOpen("BedwarsItemShopApp") and Store.shopLoaded and GetShopId()
	            if ShopId and bedwars.BedwarsShopController.alreadyPurchasedMap[ItemType] == nil then
	                local Item = bedwars.Shop.getShopItem(ItemType, LocalPlayer, {shopId = ShopId})
	                local Currency = Item and GetItem(Item.currency)
	                local Buyable = Item and not (Item.ignoredByKit and table.find(Item.ignoredByKit, Store.equippedKit or "")) and not Item.lockedByForge and not Item.disabled and (Currency and Currency.amount or 0) >= Item.price
	                if Buyable and Item.require and Item.require.teamUpgrade and (bedwars.Store:getState().Bedwars.teamUpgrades[Item.require.teamUpgrade.upgradeId] or -1) < Item.require.teamUpgrade.lowestTierIndex then
	                    Buyable = false
	                end
	
	                if Buyable then
	                    bedwars.Handler:Get("BedwarsPurchaseItem"):Fire("CallServerAsync", {
	                        shopItem = Item,
	                        shopId = ShopId
	                    }):andThen(function(Success)
	                        if not Success then
	                            return
	                        end
	                        bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM)
	                        bedwars.Store:dispatch({
	                            type = "BedwarsAddItemPurchased",
	                            itemType = ItemType
	                        })
	                        if Item.tiered then
	                            bedwars.BedwarsShopController.alreadyPurchasedMap[ItemType] = true
	                        end
	                    end)
	                end
	            end
	            task.wait(1 / CPS.Value)
	        until not Holding
	        ClickThread = nil
	    end)
	end
	
	ShopQuickBuy = vape.Categories.Utility:CreateModule({
	    Name = "ShopClicker",
	    Function = function(Callback: boolean)
	        if Callback then
	            ShopQuickBuy:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)
	                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then
	                    return
	                end
	                if not bedwars.AppController:isAppOpen("BedwarsItemShopApp") then
	                    return
	                end
	
	                local ItemType: string? = GetHoveredItem()
	                if not ItemType then
	                    return
	                end
	
	                Holding = true
	                task.delay(HoldDelay.Value, function()
	                    if Holding and GetHoveredItem() == ItemType then
	                        StartClicking(ItemType)
	                    end
	                end)
	            end))
	
	            ShopQuickBuy:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)
	                if Input.UserInputType == Enum.UserInputType.MouseButton1 then
	                    Holding = false
	                end
	            end))
	        else
	            Holding = false
	            if ClickThread then
	                task.cancel(ClickThread)
	                ClickThread = nil
	            end
	        end
	    end,
	    Tooltip = "Hold on a shop item to rapidly buy it."
	})
	
	HoldDelay = ShopQuickBuy:CreateSlider({
	    Name = "Hold Delay",
	    Min = 0,
	    Max = 1,
	    Default = 0.15,
	    Decimal = 20,
	    Suffix = "seconds"
	})
	CPS = ShopQuickBuy:CreateSlider({
	    Name = "CPS",
	    Min = 1,
	    Max = 20,
	    Default = 20,
	    Darker = true
	})
end)

Run(function()
	local StaffDetector
	local Mode
	local Clans
	local Party
	local Profile
	local Users
	local BlacklistedClans: {string} = {"gg", "gg2", "DV", "DV2"}
	local BlacklistedUserIds: {number} = {1502104539, 3826146717, 4531785383, 1049767300, 4926350670, 653085195, 184655415, 2752307430, 5087196317, 5744061325, 1536265275}
	local Joined, Rejoins, JoinTimes = {}, {}, {}
	local Watchers: {[Player]: RBXScriptConnection} = {}
	local Counts: {[string]: number} = {Spectate = 0, Mod = 0, Impossible = 0}
	local FlagColors: {[string]: string} = {Spectate = "rgb(236,129,43)", Mod = "rgb(250,50,56)", Impossible = "rgb(180,90,250)"}
	local Entries = {}
	local Window, InfoLabel, Expanded
	
	local function RefreshViewer()
	    if not Window then
	        return
	    end
	
	    local ShowList = Expanded and #Entries > 0
	    local Lines: {string} = {"<b>StaffDetector</b>", '<font size="4"> </font>'}
	    for _, v: string in {"Spectate", "Mod", "Impossible"} do
	        table.insert(Lines, `<font color="{FlagColors[v]}">{v}: {Counts[v]}</font>`)
	    end
	
	    if ShowList then
	        table.insert(Lines, '<font size="4"> </font>')
	        for i: number, v: {Name: string, Reason: string, Category: string} in Entries do
	            if i > 8 then
	                break
	            end
	            table.insert(Lines, `{v.Name} <font color="{FlagColors[v.Category]}">{v.Reason}</font>`)
	        end
	    end
	
	    InfoLabel.Text = table.concat(Lines, "\n")
	    local Bounds: Vector2 = GetFontBounds(RemoveTags(InfoLabel.Text), InfoLabel.TextSize, InfoLabel.FontFace)
	    local TitleBounds: Vector2 = GetFontBounds("StaffDetector", InfoLabel.TextSize, Font.new(InfoLabel.FontFace.Family, Enum.FontWeight.Bold))
	    Window.Size = UDim2.fromOffset(math.max(Bounds.X, TitleBounds.X) + 16, Bounds.Y + (ShowList and -8 or 4))
	end
	
	local function StaffFunction(Player: Player, CheckType: string)
	    if not vape.Loaded then
	        repeat task.wait() until vape.Loaded
	    end
	
	    SendNotification("StaffDetector", `Staff Detected ({CheckType}): {Player.Name} ({Player.UserId})`, 60, "alert")
	    Whitelist.customtags[Player.Name] = {{text = "GAME STAFF", color = Color3.new(1, 0, 0)}}
	    local Category: string = CheckType == "impossible_join" and "Impossible" or CheckType == "spectator" and "Spectate" or "Mod"
	    Counts[Category] += 1
	    table.insert(Entries, 1, {Name = Player.Name, Reason = CheckType, Category = Category})
	    RefreshViewer()
	
	    if Party.Enabled and not CheckType:find("clan") then
	        bedwars.PartyController:leaveParty()
	    end
	
	    if Mode.Value == "Uninject" then
	        task.spawn(function()
	            vape:Uninject()
	        end)
	        game:GetService("StarterGui"):SetCore("SendNotification", {
	            Title = "StaffDetector",
	            Text = `Staff Detected ({CheckType})\n{Player.Name} ({Player.UserId})`,
	            Duration = 60,
	        })
	    elseif Mode.Value == "Requeue" then
	        bedwars.QueueController:joinQueue(Store.queueType)
	    elseif Mode.Value == "Profile" then
	        vape.Save = function() end
	        if vape.Profile ~= Profile.Value then
	            vape:Load(true, Profile.Value)
	        end
	    elseif Mode.Value == "AutoConfig" then
	        local SafeModules: {string} = {"AutoClicker", "Reach", "Sprint", "HitFix", "StaffDetector"}
	        vape.Save = function() end
	        for ModuleName: string, v: any in vape.Modules do
	            if not (table.find(SafeModules, ModuleName) or v.Category == "Render") then
	                if v.Enabled then
	                    v:Toggle()
	                end
	                v:SetBind("")
	            end
	        end
	    end
	end
	
	local function NoteSpectator(Player: Player, Reason: string)
	    SendNotification("StaffDetector", `Spectator {Player.Name} joined {Reason}`, 20, "warning")
	    Counts.Spectate += 1
	    table.insert(Entries, 1, {Name = Player.Name, Reason = "spectator", Category = "Spectate"})
	    RefreshViewer()
	end
	
	local function CheckJoin(Player: Player, Connection: RBXScriptConnection)
	    if Player:GetAttribute("Team") or not Player:GetAttribute("Spectator") or Store.matchState ~= 1 or bedwars.Store:getState().Game.customMatch or (tick() - (JoinTimes[Player.UserId] or 0)) > 20 then
	        return
	    end
	
	    Connection:Disconnect()
	    task.wait(5)
	    if (not StaffDetector.Enabled) or Player.Parent ~= Players or Player:GetAttribute("Team") or not Player:GetAttribute("Spectator") then
	        return
	    end
	
	    if Rejoins[Player.UserId] then
	        NoteSpectator(Player, "back after leaving")
	        return
	    end
	
	    if Player.FollowUserId ~= 0 and Joined[Player.FollowUserId] then
	        NoteSpectator(Player, `following {Joined[Player.FollowUserId]}`)
	        return
	    end
	
	    local Success, Pages = pcall(Players.GetFriendsAsync, Players, Player.UserId)
	    if not Success then
	        return
	    end
	
	    local Friend, Finished = nil, Pages.IsFinished
	    for _ = 1, 6 do
	        for _, v: any in Pages:GetCurrentPage() do
	            if Joined[v.Id] then
	                Friend = Joined[v.Id]
	                break
	            end
	        end
	        if Friend or Finished then
	            break
	        end
	        if not pcall(Pages.AdvanceToNextPageAsync, Pages) then
	            return
	        end
	        Finished = Pages.IsFinished
	    end
	
	    if Friend then
	        NoteSpectator(Player, `from {Friend}`)
	    elseif Finished then
	        StaffFunction(Player, "impossible_join")
	        return true
	    end
	end
	
	local function Added(Player: Player)
	    if Joined[Player.UserId] then
	        Rejoins[Player.UserId] = true
	    end
	    Joined[Player.UserId] = Player.Name
	    local Teleported = Player:GetAttribute("LastTeleported")
	    JoinTimes[Player.UserId] = Teleported and (tick() - math.min(workspace:GetServerTimeNow() - Teleported, 60)) or tick()
	    if Player == LocalPlayer then
	        return
	    end
	
	    if table.find(BlacklistedUserIds, Player.UserId) or table.find(Users.ListEnabled, tostring(Player.UserId)) then
	        StaffFunction(Player, "blacklisted_user")
	    else
	        local Success, Response = pcall(function()
	            return Player:GetRankInGroup(5774246)
	        end)
	        if not Success then
	            SendNotification("StaffDetector", Response, 30, "alert")
	        end
	
	        if (Success and Response or 0) >= 100 then
	            StaffFunction(Player, "staff_role")
	        else
	            local Connection: RBXScriptConnection
	            Connection = Player:GetAttributeChangedSignal("Spectator"):Connect(function()
	                CheckJoin(Player, Connection)
	            end)
	            Watchers[Player] = Connection
	            StaffDetector:Clean(Connection)
	            if CheckJoin(Player, Connection) then
	                return
	            end
	
	            if not Player:GetAttribute("ClanTag") then
	                Player:GetAttributeChangedSignal("ClanTag"):Wait()
	            end
	
	            if table.find(BlacklistedClans, Player:GetAttribute("ClanTag")) and vape.Loaded and Clans.Enabled then
	                Connection:Disconnect()
	                StaffFunction(Player, `blacklisted_clan_{Player:GetAttribute("ClanTag"):lower()}`)
	            end
	        end
	    end
	end
	
	StaffDetector = vape.Categories.Utility:CreateModule({
	    Name = "StaffDetector",
	    Function = function(Callback: boolean)
	        if Callback then
	            StaffDetector:Clean(Players.PlayerAdded:Connect(Added))
	            StaffDetector:Clean(Players.PlayerRemoving:Connect(function(Player: Player)
	                local Connection: RBXScriptConnection? = Watchers[Player]
	                if Connection then
	                    Connection:Disconnect()
	                    Watchers[Player] = nil
	                end
	            end))
	            for _, v: Player in Players:GetPlayers() do
	                task.spawn(Added, v)
	            end
	        else
	            table.clear(Joined)
	            table.clear(Rejoins)
	            table.clear(JoinTimes)
	            table.clear(Watchers)
	        end
	    end,
	    Tooltip = "Detects people with a staff rank ingame"
	})
	
	Mode = StaffDetector:CreateDropdown({
	    Name = "Mode",
	    List = {"Uninject", "Profile", "Requeue", "AutoConfig", "Notify"},
	    Function = function(Val: string)
	        if Profile.Object then
	            Profile.Object.Visible = Val == "Profile"
	        end
	    end
	})
	Clans = StaffDetector:CreateToggle({
	    Name = "Blacklist clans",
	    Default = true
	})
	Party = StaffDetector:CreateToggle({
	    Name = "Leave party"
	})
	Profile = StaffDetector:CreateTextBox({
	    Name = "Profile",
	    Default = "default",
	    Darker = true,
	    Visible = false
	})
	Users = StaffDetector:CreateTextList({
	    Name = "Users",
	    Placeholder = "player (userid)"
	})
	StaffDetector:CreateToggle({
	    Name = "Viewer",
	    Function = function(Callback: boolean)
	        if Callback and not Window then
	            Window = Instance.new("TextButton")
	            Window.Name = "StaffDetectorViewer"
	            Window.Position = UDim2.fromOffset(12, 120)
	            Window.BackgroundColor3 = Color3.new()
	            Window.BackgroundTransparency = 0.5
	            Window.Text = ""
	            Window.AutoButtonColor = false
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	            Window.Parent = vape.gui.ScaledGui
	            AddBlur(Window)
	            local Corner: UICorner = Instance.new("UICorner")
	            Corner.CornerRadius = UDim.new(0, 5)
	            Corner.Parent = Window
	
	            InfoLabel = Instance.new("TextLabel")
	            InfoLabel.Size = UDim2.new(1, -16, 1, -16)
	            InfoLabel.Position = UDim2.fromOffset(8, 8)
	            InfoLabel.BackgroundTransparency = 1
	            InfoLabel.TextXAlignment = Enum.TextXAlignment.Left
	            InfoLabel.TextYAlignment = Enum.TextYAlignment.Top
	            InfoLabel.TextSize = 16
	            InfoLabel.TextColor3 = Color3.new(1, 1, 1)
	            InfoLabel.TextStrokeColor3 = Color3.new()
	            InfoLabel.TextStrokeTransparency = 0.8
	            InfoLabel.Font = Enum.Font.Arial
	            InfoLabel.RichText = true
	            InfoLabel.Parent = Window
	            StaffDetector:AddHUD(Window)
	
	            local PressPosition: UDim2? = nil
	            Window.MouseButton1Down:Connect(function()
	                PressPosition = Window.Position
	            end)
	
	            Window.MouseButton1Click:Connect(function()
	                if PressPosition == Window.Position then
	                    Expanded = not Expanded
	                    RefreshViewer()
	                end
	            end)
	        end
	
	        if Window then
	            Window.Visible = Callback
	            RefreshViewer()
	        end
	    end,
	    Tooltip = "Shows a panel with detection counts, click it to list who tripped them and drag it while the GUI is open to move it"
	})
	task.spawn(function()
	    repeat task.wait(1) until vape.Loaded or vape.Loaded == nil
	    if vape.Loaded and StaffDetector.Toggle and not StaffDetector.Enabled then
	        StaffDetector:Toggle()
	    end
	end)
end)

