Run(function()
	local AutoTool
	local Mode
	local Delay = {}
	local SwitchBack
	local BreakEvent
	local Looking, Deadline, Previous, Switching = nil, 0, nil, false
	
	local function IsMining(): boolean
	    local Mining = Store.breakTool
	    return Mining ~= nil and Mining.expires > tick() and not (Mining.session and Mining.session.Cancelled)
	end
	
	local function GetToolSlot(Block)
	    if IsMining() or not Block or Block:GetAttribute("NoBreak") or Block:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or 0}NoBreak`) then
	        return
	    end
	
	    local Meta = bedwars.ItemMeta[Block.Name]
	    local Tool = Meta and Meta.block and Store.tools[Meta.block.breakType]
	    if not Tool or (Store.hand and Store.hand.tool == Tool.tool) then
	        return
	    end
	
	    for i: number, v: any in Store.inventory.hotbar do
	        if v.item and v.item.itemType == Tool.itemType then
	            return i - 1
	        end
	    end
	    return
	end
	
	local function SwitchTo(Slot: number)
	    if Switching then
	        return
	    end
	
	    Switching = true
	    task.spawn(function()
	        if not IsMining() then
	            HotbarSwitch(Slot)
	        end
	        Switching = false
	    end)
	end
	
	AutoTool = vape.Categories.World:CreateModule({
	    Name = "AutoTool",
	    Function = function(Callback: boolean)
	        if Callback then
	            Looking, Deadline, Previous, Switching = nil, 0, nil, false
	
	            local Event: BindableEvent = Instance.new("BindableEvent")
	            BreakEvent = Event
	            AutoTool:Clean(Event)
	            AutoTool:Clean(Event.Event:Connect(function()
	                ContextActionService:CallFunction("block-break", Enum.UserInputState.Begin, newproxy(true))
	            end))
	
	            AutoTool:Clean(RunService.Heartbeat:Connect(function()
	                if Mode.Value ~= "Look" or not Entity.isAlive or IsMining() then
	                    return
	                end
	
	                local HeldMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]
	                if not (HeldMeta and HeldMeta.breakBlock) then
	                    Looking, Previous = nil, nil
	                    return
	                end
	
	                local Placer = Store.blockPlacer or (bedwars.BlockPlacementController and bedwars.BlockPlacementController.blockPlacer)
	                local Selector = Placer and Placer.clientManager and Placer.clientManager:getBlockSelector()
	                local Info = Selector and Selector:getMouseInfo(1, {ray = not UserInputService.KeyboardEnabled and Camera:ScreenPointToRay(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2 - GuiService:GetGuiInset().Y) or nil})
	                local Block = Info and Info.target and Info.target.blockInstance or nil
	                if not Block then
	                    Looking = nil
	                    if SwitchBack.Enabled and Previous then
	                        SwitchTo(Previous)
	                        Previous = nil
	                    end
	                    return
	                end
	
	                if Block ~= Looking then
	                    Looking, Deadline = Block, tick() + Delay:GetRandomValue()
	                    return
	                end
	                if tick() < Deadline then
	                    return
	                end
	
	                local Slot = GetToolSlot(Block)
	                if Slot then
	                    Previous = Previous or (Store.hand.tool and GetHotbar(Store.hand.tool) or nil)
	                    SwitchTo(Slot)
	                end
	            end))
	
	            bedwars.BlockBreakCallbacks.AutoTool = function(self, Maid, MouseRay, ...)
	                if Mode.Value == "Break" then
	                    local Info = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = MouseRay})
	                    local Slot = GetToolSlot(Info and Info.target and Info.target.blockInstance or nil)
	                    if Slot then
	                        task.spawn(function()
	                            if not AutoTool.Enabled or BreakEvent ~= Event or IsMining() then return end
	                            if HotbarSwitch(Slot) and AutoTool.Enabled and BreakEvent == Event and UserInputService:IsMouseButtonPressed(0) then
	                                Event:Fire()
	                            end
	                        end)
	                    end
	                end
	            end
	        else
	            Looking, Previous = nil, nil
	            bedwars.BlockBreakCallbacks.AutoTool = nil
	            BreakEvent = nil
	        end
	    end,
	    Tooltip = "Automatically selects the correct tool"
	})
	
	Mode = AutoTool:CreateDropdown({
	    Name = "Mode",
	    List = {"Look", "Break"},
	    Function = function(Val: string)
	        if Delay.Object then
	            Delay.Object.Visible = Val == "Look"
	            SwitchBack.Object.Visible = Val == "Look"
	        end
	    end,
	    Default = "Break",
	    Tooltip = "Look swaps while you are still aiming at the block, Break swaps on the first hit like it used to"
	})
	Delay = AutoTool:CreateTwoSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    DefaultMin = 0.06,
	    DefaultMax = 0.16,
	    Darker = true,
	    Suffix = "seconds",
	    Tooltip = "How long you have to be looking at the block before it swaps"
	})
	SwitchBack = AutoTool:CreateToggle({
	    Name = "Switch back",
	    Darker = true,
	    Tooltip = "Puts the item you were holding back once you look away"
	})
end)

Run(function()
	local BedAssist
	local AimMode
	local Speed
	local Range
	local Angle
	local Shake
	local Mode
	local Limit
	local AutoMine
	local MineBed
	local Started, NextSearch = 0, 0
	local Target, TargetBed, TargetPosition
	local OldHit, HitBlock, Session, Pending
	local Generator: Random = Random.new()
	local Sides: {Vector3} = {Vector3.xAxis, -Vector3.xAxis, Vector3.yAxis, -Vector3.yAxis, Vector3.zAxis, -Vector3.zAxis}
	local Points: {Vector3} = {Vector3.zero, Vector3.xAxis * 1.35, -Vector3.xAxis * 1.35, Vector3.yAxis * 1.35, -Vector3.yAxis * 1.35, Vector3.zAxis * 1.35, -Vector3.zAxis * 1.35}
	local RayParams: RaycastParams = RaycastParams.new()
	RayParams.FilterType = Enum.RaycastFilterType.Exclude
	
	local function GetAim(Block, Position: Vector3, Direction: Vector3)
	    for _, v: Vector3 in Points do
	        if Block.Name == "bed" and (v == Vector3.zero or GetPlacedBlock(Position + v.Unit * 3)) then
	            continue
	        end
	        local Aim: Vector3 = Position + v
	        local Offset: Vector3 = Aim - Camera.CFrame.Position
	        if Offset.Magnitude > 0.001 and Offset.Unit:Dot(Direction) >= math.cos(math.rad(Angle.Value)) then
	            local Hit: RaycastResult? = bedwars.QueryUtil:raycast(Camera.CFrame.Position, Offset.Unit * (Offset.Magnitude + 3), RayParams)
	            if Hit and (Hit.Instance == Block or Hit.Instance:IsDescendantOf(Block)) then
	                if Block.Name == "bed" then
	                    local Handler = bedwars.BlockController:getHandlerRegistry():getHandler("bed")
	                    local Closest, Distance = nil, math.huge
	                    for _, Cell: Vector3 in Handler:getContainedPositions(Block) do
	                        local Magnitude: number = (Cell * 3 - (Hit.Position - Hit.Normal * 0.1)).Magnitude
	                        if Magnitude < Distance then
	                            Closest, Distance = Cell * 3, Magnitude
	                        end
	                    end
	                    if Closest ~= Position then
	                        continue
	                    end
	                end
	                return Hit.Position
	            end
	        end
	    end
	    return nil
	end
	
	local function GetBestPosition(Bed: BasePart, Direction: Vector3)
	    local Handler = bedwars.BlockController:getHandlerRegistry():getHandler(Bed.Name)
	    local Positions = Handler and Handler:getContainedPositions(Bed) or {bedwars.BlockController:getBlockPosition(Bed.Position)}
	    local Queue, Distances, Depths, Visited = {}, {}, {}, {}
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local BlockStore = bedwars.BlockController:getStore()
	    local Cost, Depth, Distance, Magnitude = math.huge, math.huge, math.huge, math.huge
	    local Block, Position
	    for _, v: Vector3 in Positions do
	        if BlockStore:getBlockAt(v) == Bed then
	            Distances[v], Depths[v] = 0, 0
	            table.insert(Queue, {position = v, cost = 0, depth = 0})
	        end
	    end
	
	    for _ = 1, 512 do
	        local BestIndex, Node
	        for i: number, v: {position: Vector3, cost: number, depth: number} in Queue do
	            if not Node or v.cost < Node.cost or v.cost == Node.cost and v.depth < Node.depth then
	                BestIndex, Node = i, v
	            end
	        end
	        if not Node or Node.cost > Cost then
	            break
	        end
	        table.remove(Queue, BestIndex)
	        if Visited[Node.position] then
	            continue
	        end
	        Visited[Node.position] = true
	        local Current = BlockStore:getBlockAt(Node.position)
	        local WorldPosition: Vector3 = Node.position * 3
	        local NodeMagnitude: number = (LocalPosition - WorldPosition).Magnitude
	        local NodeDistance: number = math.huge
	        for _, v: Vector3 in Positions do
	            NodeDistance = math.min(NodeDistance, (Node.position - v).Magnitude)
	        end
	        if Current and NodeMagnitude <= math.min(Range.Value, bedwars.BlockBreaker:getRange()) then
	            local Point = GetAim(Current, WorldPosition, Direction)
	            if Point and (Node.cost < Cost or Node.depth < Depth or Node.depth == Depth and (NodeDistance < Distance or NodeDistance == Distance and ((Current == Target and Block ~= Target) or (Current == Target) == (Block == Target) and NodeMagnitude < Magnitude))) then
	                Block, Position = Current, WorldPosition
	                Cost, Depth, Distance, Magnitude = Node.cost, Node.depth, NodeDistance, NodeMagnitude
	            end
	        end
	
	        for _, v: Vector3 in Sides do
	            local NextPosition: Vector3 = Node.position + v
	            if Visited[NextPosition] or (NextPosition * 3 - Bed.Position).Magnitude > 18 then
	                continue
	            end
	            local NextBlock = BlockStore:getBlockAt(NextPosition)
	            local Meta = NextBlock and bedwars.ItemMeta[NextBlock.Name]
	            if not Meta or not Meta.block or NextBlock:GetAttribute("NoBreak") or NextBlock:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) or not bedwars.BlockController:isBlockBreakable({blockPosition = NextPosition}, LocalPlayer) then
	                continue
	            end
	            local Data = BlockStore:getBlockData(NextPosition)
	            local Health = Data and Data:GetAttribute(bedwars.BlockBreaker.blockHealthbar:getHealthKey(NextBlock)) or NextBlock:GetAttribute("Health") or Meta.block.health
	            local Damage = bedwars.BlockController:calculateBlockDamage(LocalPlayer, {blockPosition = NextPosition})
	            if Damage <= 0 then
	                continue
	            end
	            local Hits: number = Node.cost + math.max(math.ceil((Health or 10) / Damage), 1)
	            local Steps: number = Node.depth + 1
	            if Hits < (Distances[NextPosition] or math.huge) or Hits == Distances[NextPosition] and Steps < Depths[NextPosition] then
	                Distances[NextPosition], Depths[NextPosition] = Hits, Steps
	                table.insert(Queue, {position = NextPosition, cost = Hits, depth = Steps})
	            end
	        end
	    end
	    return Block, Position, Cost, Depth, Magnitude
	end
	
	BedAssist = vape.Categories.World:CreateModule({
	    Name = "BedAssist",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Current = {}
	            Session, Pending = Current, nil
	            local Beds = Collection("bed", BedAssist)
	            local Maid = getmetatable(bedwars.BlockBreaker.maid).new()
	            BedAssist:Clean(function()
	                Maid:DoCleaning()
	            end)
	            OldHit = bedwars.BlockBreaker.hitBlock
	            HitBlock = function(self, Cleanup, MouseRay, ...)
	                local Info = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = MouseRay, range = math.min(Range.Value, self:getRange())})
	                local Selected = Info and Info.target
	                if Session ~= Current or not MineBed.Enabled or not Selected or Selected.blockInstance.Name ~= "bed" then
	                    return OldHit(self, Cleanup, MouseRay, ...)
	                end
	                if Pending and tick() - Pending.sent < math.max(1, LocalPlayer:GetNetworkPing() * 4 + 0.5) or not Entity.isAlive or Store.matchState ~= 1 or LocalPlayer:GetAttribute("DenyBlockBreak") or tick() - self.lastHitTime < self:getCooldown() or not bedwars.BlockController:isBlockBreakable(Selected.blockRef, LocalPlayer) then
	                    return
	                end
	                local Block = Selected.blockInstance
	                if Block:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) or (Block:GetAttribute("BedShieldEndTime") or 0) > workspace:GetServerTimeNow() then
	                    return
	                end
	                local Data = bedwars.BlockController:getStore():getBlockData(Selected.blockRef.blockPosition)
	                local HealthKey: string = self.blockHealthbar:getHealthKey(Block)
	                local Before: number = Data and Data:GetAttribute(HealthKey) or Block:GetAttribute("Health")
	                local Request = {sent = tick()}
	                Pending = Request
	                self.lastHitTime = tick()
	                Store.lastHit = self.lastHitTime
	                for _, Function: (...any) -> () in bedwars.BlockBreakCallbacks do
	                    Function(self, Cleanup, MouseRay, ...)
	                end
	                local Animation = bedwars.AnimationUtil:playAnimation(LocalPlayer, bedwars.BlockController:getAnimationController():getAssetId(1))
	                if Animation then
	                    Cleanup:GiveTask(function()
	                        Animation:Stop()
	                        Animation:Destroy()
	                    end)
	                end
	                self.onBreak:Fire()
	                bedwars.ClientDamageBlock:Get("DamageBlock"):CallServerAsync({
	                    blockRef = Selected.blockRef,
	                    hitPosition = Selected.hitPosition,
	                    hitNormal = Selected.hitNormal
	                }):andThen(function(Result)
	                    if Session ~= Current then return end
	                    if Result == "destroyed" then
	                        self.blockHealthbar:destroy()
	                        self.breakTextureHandler:removeTexture(Selected.blockRef)
	                        if bedwars.BlockController:getStore():getBlockAt(Selected.blockRef.blockPosition) == Block then
	                            bedwars.BlockController:destroyBlock(Selected.blockRef)
	                        end
	                        self.breakEffect:playBreak(Block.Name, Selected.blockRef.blockPosition, LocalPlayer)
	                    elseif Result == "damaged" then
	                        local After: number = Data and Data:GetAttribute(HealthKey) or Block:GetAttribute("Health")
	                        self:updateHealthbar(Selected.blockRef, Before, Block:GetAttribute("MaxHealth"), math.max(Before - After, 0), Block)
	                        self.breakEffect:playHit(Block.Name, Selected.blockRef.blockPosition, LocalPlayer)
	                    end
	                    NextSearch = 0
	                end):catch(function()
	                    if Session == Current then NextSearch = 0 end
	                end):finally(function()
	                    if Pending == Request then Pending = nil end
	                end)
	                return nil
	            end
	            bedwars.BlockBreaker.hitBlock = HitBlock
	
	            BedAssist:Clean(RunService.PostSimulation:Connect(function(DeltaTime: number)
	                local HeldMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]
	                if not Entity.isAlive or Store.matchState ~= 1 or LocalPlayer:GetAttribute("Spectator") or LocalPlayer:GetAttribute("DenyBlockBreak") or UserInputService:GetFocusedTextBox() or GuiService.MenuIsOpen or bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) or Limit.Enabled and not (HeldMeta and HeldMeta.breakBlock) then
	                    Target, TargetBed, TargetPosition, NextSearch = nil, nil, nil, 0
	                    return
	                end
	
	                local MouseLocation: Vector2 = UserInputService.MouseEnabled and UserInputService:GetMouseLocation() or Camera.ViewportSize / 2
	                local MouseRay: Ray = Camera:ViewportPointToRay(MouseLocation.X, MouseLocation.Y)
	                RayParams.FilterDescendantsInstances = {LocalPlayer.Character, Camera}
	                if tick() >= NextSearch or Target and not Target.Parent then
	                    local Block, Bed, Position
	                    local Cost, Depth, Distance = math.huge, math.huge, math.huge
	                    for _, v: BasePart in Beds do
	                        if not v.Parent or v:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) or (v:GetAttribute("BedShieldEndTime") or 0) > workspace:GetServerTimeNow() or (v.Position - Entity.character.RootPart.Position).Magnitude > Range.Value + 3 or not bedwars.BlockController:isBlockBreakable({blockPosition = bedwars.BlockController:getBlockPosition(v.Position)}, LocalPlayer) then
	                            continue
	                        end
	                        local BedBlock, BedPosition, BedCost, BedDepth, BedMagnitude = GetBestPosition(v, MouseRay.Direction)
	                        if BedBlock and (BedCost < Cost or BedCost == Cost and (BedDepth < Depth or BedDepth == Depth and BedMagnitude < Distance)) then
	                            Block, Bed, Position, Cost, Depth, Distance = BedBlock, v, BedPosition, BedCost, BedDepth, BedMagnitude
	                        end
	                    end
	                    if Block ~= Target then
	                        Started = tick()
	                    end
	                    Target, TargetBed, TargetPosition, NextSearch = Block, Bed, Position, tick() + 0.15
	                end
	
	                if not Target or not Target.Parent or not TargetBed.Parent or TargetBed:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) or (TargetBed:GetAttribute("BedShieldEndTime") or 0) > workspace:GetServerTimeNow() or Target == TargetBed and not MineBed.Enabled or (Entity.character.RootPart.Position - TargetPosition).Magnitude > math.min(Range.Value, bedwars.BlockBreaker:getRange()) then
	                    return
	                end
	                local AimPosition = GetAim(Target, TargetPosition, MouseRay.Direction)
	                if not AimPosition then
	                    return
	                end
	                local AimSpeed: number = Speed.Value
	                if AimMode.Value == "Adaptive" then
	                    local Progress: number = math.clamp((tick() - Started) * AimSpeed * 0.5, 0, 1)
	                    AimSpeed *= Progress < 0.5 and 4 * Progress ^ 3 or 1 - (-2 * Progress + 2) ^ 3 / 2
	                end
	                local Alpha: number = 1 - math.exp(-AimSpeed * DeltaTime)
	                local Aim: Vector3 = AimPosition + Vector3.new(Generator:NextNumber(-1, 1), Generator:NextNumber(-1, 1), Generator:NextNumber(-1, 1)) * Shake.Value * 0.005
	                if Mode.Value == "Mouse" then
	                    local Screen, Visible = Camera:WorldToViewportPoint(Aim)
	                    if Visible then
	                        local Delta: Vector2 = (Vector2.new(Screen.X, Screen.Y) - MouseLocation) * Alpha
	                        mousemoverel(Delta.X, Delta.Y)
	                    end
	                else
	                    local Direction: Vector3 = (Aim - MouseRay.Origin).Unit
	                    local Axis: Vector3 = MouseRay.Direction:Cross(Direction)
	                    if Axis.Magnitude > 0.0001 then
	                        local Rotation: CFrame = CFrame.fromAxisAngle(Axis.Unit, math.acos(math.clamp(MouseRay.Direction:Dot(Direction), -1, 1)) * Alpha)
	                        Camera.CFrame = CFrame.new(Camera.CFrame.Position) * Rotation * Camera.CFrame.Rotation
	                    end
	                end
	
	                if AutoMine.Enabled and not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) and tick() - bedwars.BlockBreaker.lastHitTime >= bedwars.BlockBreaker:getCooldown() then
	                    MouseRay = Camera:ViewportPointToRay(MouseLocation.X, MouseLocation.Y)
	                    local Info = bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(1, {ray = MouseRay, range = math.min(Range.Value, bedwars.BlockBreaker:getRange())})
	                    if Info and Info.target and Info.target.blockInstance == Target then
	                        Maid:DoCleaning()
	                        bedwars.BlockBreaker:hitBlock(Maid, MouseRay)
	                    end
	                end
	            end))
	        else
	            if bedwars.BlockBreaker.hitBlock == HitBlock then
	                bedwars.BlockBreaker.hitBlock = OldHit
	            end
	            Session, Pending = nil, nil
	            Target, TargetBed, TargetPosition, NextSearch = nil, nil, nil, 0
	        end
	    end,
	    Tooltip = "Smoothly aims and mines the weakest visible route into an enemy bed using normal reach and mining speed"
	})
	
	AimMode = BedAssist:CreateDropdown({
	    Name = "Mode",
	    List = {"Simple", "Adaptive"},
	    Default = "Simple"
	})
	local AimModes: {string} = {"Camera"}
	if UserInputService.MouseEnabled and mousemoverel then
	    table.insert(AimModes, "Mouse")
	end
	Mode = BedAssist:CreateDropdown({
	    Name = "Aim mode",
	    List = AimModes,
	    Default = "Camera"
	})
	Speed = BedAssist:CreateSlider({
	    Name = "Aim speed",
	    Min = 1,
	    Max = 20,
	    Default = 7
	})
	Range = BedAssist:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 30,
	    Default = 18,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "Never exceeds the game's normal mining reach"
	})
	Angle = BedAssist:CreateSlider({
	    Name = "View angle",
	    Min = 5,
	    Max = 180,
	    Default = 60,
	    Suffix = "degrees",
	    Tooltip = "Maximum angle away from your crosshair, 180 allows every direction"
	})
	Shake = BedAssist:CreateSlider({
	    Name = "Shake",
	    Min = 0,
	    Max = 100,
	    Default = 3
	})
	Limit = BedAssist:CreateToggle({Name = "Limit to item", Default = true})
	AutoMine = BedAssist:CreateToggle({
	    Name = "Auto mine",
	    Default = true,
	    Tooltip = "Mines only when your crosshair reaches the chosen block; disable for aim assistance only"
	})
	MineBed = BedAssist:CreateToggle({
	    Name = "Mine bed",
	    Default = true,
	    Tooltip = "Mines the bed as soon as it is visible; disable to stop once the defense is open"
	})
end)

Run(function()
	local BedPatcher
	local Mode
	local Whitelist
	local PlaceRange
	local Radius
	local Wool
	local Switch
	local NoAnimation
	local Limit
	local Layout, Adjacent = {}, {}
	local PlaceAnimation = bedwars.BlockController:getAnimationController():getAssetId(0)
	local Placing, Old = false
	
	for _, v: EnumItem in Enum.NormalId:GetEnumItems() do
	    table.insert(Adjacent, Vector3.FromNormalId(v) * 3)
	end
	
	local function GetBedNear()
	    local LocalPosition: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Vector3.zero
	    for _, v: BasePart in CollectionService:GetTagged("bed") do
	        if (LocalPosition - v.Position).Magnitude < (PlaceRange.Value + Radius.Value) and v:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) then
	            return v
	        end
	    end
	    return nil
	end
	
	local function GetBlock(ItemType: string?)
	    if Limit.Enabled then
	        local Hand = Store.hand.toolType == "block" and Store.hand.tool
	        if Hand and (not Wool.Enabled or Hand.Name:find("wool")) and table.find(Whitelist.ListEnabled, Hand.Name:find("wool") and "wool" or Hand.Name) then
	            return Hand.Name, Hand
	        end
	        return nil
	    end
	
	    local Best, Health
	    for _, v: any in Store.inventory.inventory.items do
	        local Block = bedwars.ItemMeta[v.itemType].block
	        if not Block or (Wool.Enabled and not v.itemType:find("wool")) then
	            continue
	        end
	        if not table.find(Whitelist.ListEnabled, v.itemType:find("wool") and "wool" or v.itemType) then
	            continue
	        end
	        if v.itemType == ItemType then
	            return v.itemType, v.tool
	        end
	        if not Health or (Block.health or 0) > Health then
	            Best, Health = v, Block.health or 0
	        end
	    end
	    return Best and Best.itemType or nil, Best and Best.tool or nil
	end
	
	local function ScanBed(Bed: BasePart)
	    table.clear(Layout)
	    for _, v: BasePart in Store.blocks do
	        if not v:HasTag("bed") and (v.Position - Bed.Position).Magnitude <= Radius.Value then
	            Layout[v.Position] = v.Name
	        end
	    end
	
	    local Holes = {}
	    for Position: Vector3, v: string in Layout do
	        for _, Offset: Vector3 in Adjacent do
	            local Cell: Vector3 = Position + Offset
	            if Layout[Cell] or Holes[Cell] or GetPlacedBlock(Cell) then
	                continue
	            end
	
	            local Walls: number = 0
	            for _, Side: Vector3 in Adjacent do
	                if Layout[Cell + Side] then
	                    Walls += 1
	                end
	            end
	
	            if Walls >= 4 then
	                Holes[Cell] = v
	            end
	        end
	    end
	
	    for Position: Vector3, v: string in Holes do
	        Layout[Position] = v
	    end
	end
	
	BedPatcher = vape.Categories.World:CreateModule({
	    Name = "BedPatcher",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Bed
	            Old = bedwars.AnimationUtil.playAnimation
	            bedwars.AnimationUtil.playAnimation = function(self, Player, AssetId, Config)
	                if Placing and NoAnimation.Enabled and AssetId == PlaceAnimation then
	                    return
	                end
	                return Old(self, Player, AssetId, Config)
	            end
	
	            BedPatcher:Clean(CollectionService:GetInstanceAddedSignal("block"):Connect(function(Block)
	                if Bed and not Block:HasTag("bed") and (Block.Position - Bed.Position).Magnitude <= Radius.Value then
	                    Layout[Block.Position] = Block.Name
	                end
	            end))
	
	            BedPatcher:Clean(VapeEvents.BreakBlockEvent.Event:Connect(function(BlockTable)
	                local Player = BlockTable.player
	                if Player and (Player == LocalPlayer or Player:GetAttribute("Team") == LocalPlayer:GetAttribute("Team")) then
	                    Layout[BlockTable.blockRef.blockPosition * 3] = nil
	                end
	            end))
	
	            repeat
	                local Found = GetBedNear()
	                if Found ~= Bed then
	                    Bed = Found
	                    if Bed then
	                        ScanBed(Bed)
	                    else
	                        table.clear(Layout)
	                    end
	                end
	
	                if Bed and Entity.isAlive then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    local Holes = {}
	
	                    for Position: Vector3, v: string in Layout do
	                        if (LocalPosition - Position).Magnitude <= PlaceRange.Value and not GetPlacedBlock(Position) then
	                            table.insert(Holes, {Position, v})
	                        end
	                    end
	
	                    table.sort(Holes, function(A, B): boolean
	                        return (A[1] - Bed.Position).Magnitude < (B[1] - Bed.Position).Magnitude
	                    end)
	
	                    for _, v: {any} in Holes do
	                        local Position, ItemType = unpack(v)
	                        if GetPlacedBlock(Position) then
	                            continue
	                        end
	
	                        local Item, Tool = GetBlock(ItemType)
	                        if not Item then
	                            break
	                        end
	
	                        if Switch.Enabled and GetHotbar(Tool) and HotbarSwitch(GetHotbar(Tool)) then
	                            task.wait()
	                        end
	
	                        Placing = true
	                        bedwars.placeBlock(Position, Item)
	                        Placing = false
	                        task.wait(1 / bedwars.SharedConstants.BLOCK_PLACE_CPS)
	                    end
	                elseif not Bed and Mode.Value == "On Key" then
	                    SendNotification("BedPatcher", "Unable to locate bed", 5)
	                    BedPatcher:Toggle()
	                    break
	                end
	
	                task.wait(0.5)
	                if Mode.Value == "On Key" then
	                    BedPatcher:Toggle()
	                    break
	                end
	            until not BedPatcher.Enabled
	        else
	            bedwars.AnimationUtil.playAnimation = Old
	            Placing = false
	        end
	    end,
	    Tooltip = "Puts back the blocks an enemy broke out of your bed defense."
	})
	
	Mode = BedPatcher:CreateDropdown({
	    Name = "Mode",
	    List = {"Toggle", "On Key"},
	    Default = "Toggle"
	})
	Whitelist = BedPatcher:CreateTextList({
	    Name = "Whitelist",
	    Default = {"wool", "obsidian"}
	})
	PlaceRange = BedPatcher:CreateSlider({
	    Name = "Place Range",
	    Min = 1,
	    Max = 60,
	    Default = 15
	})
	Radius = BedPatcher:CreateSlider({
	    Name = "Defense Radius",
	    Min = 3,
	    Max = 30,
	    Default = 15,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end,
	    Tooltip = "How far out from the bed still counts as your defense"
	})
	Wool = BedPatcher:CreateToggle({Name = "Wool only", Tooltip = "Only uses wools to patch."})
	Switch = BedPatcher:CreateToggle({Name = "Auto Switch"})
	NoAnimation = BedPatcher:CreateToggle({
	    Name = "No Animation",
	    Tooltip = "Hides the arm swing every patched block would otherwise play"
	})
	Limit = BedPatcher:CreateToggle({Name = "Limit to item"})
end)

Run(function()
	local BedPlates
	local Background
	local Color
	local LayerCounter
	local LayerColor
	local Reference = {}
	local Shown: {[BillboardGui]: string} = setmetatable({}, {__mode = "k"})
	local Folder: Folder = Instance.new("Folder")
	if vape.ThreadFix then
	    setthreadidentity(8)
	end
	Folder.Parent = vape.gui
	
	local function GetBlockLayerHealth(Block: string): number
	    local Meta = bedwars.ItemMeta[Block]
	    return Meta and Meta.block and Meta.block.health or 0
	end
	
	local function ScanSide(self, Start: Vector3, Layers)
	    for _, v: Vector3 in Sides do
	        local Found = {}
	        for Depth: number = 1, 15 do
	            local Block = GetPlacedBlock(Start + (v * Depth))
	            if not Block or Block == self or Block.Name == "bed" then
	                break
	            end
	            if not Block:GetAttribute("NoBreak") then
	                Found[Block.Name] = (Found[Block.Name] or 0) + 1
	            end
	        end
	
	        for Name: string, Count: number in Found do
	            Layers[Name] = math.max(Layers[Name] or 0, Count)
	        end
	    end
	end
	
	local function RefreshAdornee(Billboard: BillboardGui)
	    local Start: Vector3 = Billboard.Adornee.Position
	    local Layers = {}
	    local AlreadyGot = {}
	    ScanSide(Billboard.Adornee, Start, Layers)
	    ScanSide(Billboard.Adornee, Start + Vector3.new(0, 0, 3), Layers)
	    for Name: string, Count: number in Layers do
	        table.insert(AlreadyGot, {Name, Count})
	    end
	    table.sort(AlreadyGot, function(A, B): boolean
	        local HealthA, HealthB = GetBlockLayerHealth(A[1]), GetBlockLayerHealth(B[1])
	        return HealthA == HealthB and A[1] < B[1] or HealthA > HealthB
	    end)
	    Billboard.Enabled = #AlreadyGot > 0
	
	    local Key: {string} = {tostring(not LayerCounter or LayerCounter.Enabled)}
	    for _, v: {any} in AlreadyGot do
	        table.insert(Key, `{v[1]}:{v[2]}`)
	    end
	    local LayerKey: string = table.concat(Key, ",")
	    if Shown[Billboard] == LayerKey then return end
	    Shown[Billboard] = LayerKey
	
	    for _, v: Instance in Billboard.Frame:GetChildren() do
	        if v:IsA("ImageLabel") and v.Name ~= "Blur" then
	            v:Destroy()
	        end
	    end
	
	    for _, v: {any} in AlreadyGot do
	        local Block, Amount = v[1], v[2]
	        local BlockImage: ImageLabel = Instance.new("ImageLabel")
	        BlockImage.Size = UDim2.fromOffset(32, 32)
	        BlockImage.BackgroundTransparency = 1
	        BlockImage.Image = bedwars.getIcon({itemType = Block}, true)
	        BlockImage.Parent = Billboard.Frame
	        if Amount > 1 and (not LayerCounter or LayerCounter.Enabled) then
	            local AmountText: TextLabel = Instance.new("TextLabel")
	            AmountText.Name = "Amount"
	            AmountText.Size = UDim2.fromScale(1, 1)
	            AmountText.BackgroundTransparency = 1
	            AmountText.Text = tostring(Amount)
	            AmountText.TextColor3 = (LayerColor and Color3.fromHSV(LayerColor.Hue, LayerColor.Sat, LayerColor.Value) or Color3.new(1, 1, 1))
	            AmountText.TextSize = 16
	            AmountText.TextStrokeTransparency = 0.3
	            AmountText.Font = Enum.Font.Arial
	            AmountText.Parent = BlockImage
	        end
	    end
	end
	
	local function Added(Bed: BasePart)
	    if Reference[Bed] then return end
	
	    local Billboard: BillboardGui = Instance.new("BillboardGui")
	    Billboard.Parent = Folder
	    Billboard.Name = "bed"
	    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	    Billboard.Size = UDim2.fromOffset(36, 36)
	    Billboard.AlwaysOnTop = true
	    Billboard.ClipsDescendants = false
	    Billboard.Adornee = Bed
	    local Blur: ImageLabel = AddBlur(Billboard)
	    Blur.Visible = Background.Enabled
	    local Frame: Frame = Instance.new("Frame")
	    Frame.Size = UDim2.fromScale(1, 1)
	    Frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	    Frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	    Frame.Parent = Billboard
	    local Layout: UIListLayout = Instance.new("UIListLayout")
	    Layout.FillDirection = Enum.FillDirection.Horizontal
	    Layout.Padding = UDim.new(0, 4)
	    Layout.VerticalAlignment = Enum.VerticalAlignment.Center
	    Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	    Layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
	        Billboard.Size = UDim2.fromOffset(math.max(Layout.AbsoluteContentSize.X + 4, 36), 36)
	    end)
	    Layout.Parent = Frame
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(0, 4)
	    Corner.Parent = Frame
	    Reference[Bed] = Billboard
	    RefreshAdornee(Billboard)
	end
	
	local function RefreshNear(Data)
	    Data = Data.blockRef.blockPosition * 3
	    for Bed: BasePart, v: BillboardGui in Reference do
	        if (Data - Bed.Position).Magnitude <= 30 then
	            RefreshAdornee(v)
	        end
	    end
	end
	
	BedPlates = vape.Categories.World:CreateModule({
	    Name = "BedPlates",
	    Function = function(Callback: boolean)
	        if Callback then
	            for _, v: BasePart in CollectionService:GetTagged("bed") do
	                task.spawn(Added, v)
	            end
	            BedPlates:Clean(VapeEvents.PlaceBlockEvent.Event:Connect(RefreshNear))
	            BedPlates:Clean(VapeEvents.BreakBlockEvent.Event:Connect(RefreshNear))
	            BedPlates:Clean(CollectionService:GetInstanceAddedSignal("bed"):Connect(Added))
	            BedPlates:Clean(CollectionService:GetInstanceRemovedSignal("bed"):Connect(function(Bed: Instance)
	                if Reference[Bed] then
	                    Reference[Bed]:Destroy()
	                    Reference[Bed] = nil
	                end
	            end))
	        else
	            table.clear(Reference)
	            Folder:ClearAllChildren()
	        end
	    end,
	    Tooltip = "Displays blocks over the bed"
	})
	
	Background = BedPlates:CreateToggle({
	    Name = "Background",
	    Function = function(Callback: boolean)
	        if Color and Color.Object then
	            Color.Object.Visible = Callback
	        end
	        for _, v: BillboardGui in Reference do
	            v.Frame.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)
	            v.Blur.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Color = BedPlates:CreateColorSlider({
	    Name = "Background Color",
	    DefaultValue = 0,
	    DefaultOpacity = 0.5,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        for _, v: BillboardGui in Reference do
	            v.Frame.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
	            v.Frame.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)
	        end
	    end,
	    Darker = true
	})
	LayerCounter = BedPlates:CreateToggle({
	    Name = "Layer Counter",
	    Function = function(Callback: boolean)
	        if LayerColor and LayerColor.Object then
	            LayerColor.Object.Visible = Callback
	        end
	        for _, v: BillboardGui in Reference do
	            RefreshAdornee(v)
	        end
	    end,
	    Default = true
	})
	LayerColor = BedPlates:CreateColorSlider({
	    Name = "Counter Text Color",
	    Function = function()
	        local TextColor: Color3 = (LayerColor and Color3.fromHSV(LayerColor.Hue, LayerColor.Sat, LayerColor.Value) or Color3.new(1, 1, 1))
	        for _, Billboard: BillboardGui in Reference do
	            for _, v: Instance in Billboard.Frame:GetDescendants() do
	                if v:IsA("TextLabel") and v.Name == "Amount" then
	                    v.TextColor3 = TextColor
	                end
	            end
	        end
	    end,
	    DefaultSat = 0,
	    DefaultValue = 1
	})
end)

Run(function()
	local BedProtector
	local PlaceRange
	local Layers
	local Blacklist
	local Wool
	local Mode
	local Smart
	local Switch
	
	local function GetBlocks()
	    local Blocks = {}
	    for _, v: any in Store.inventory.inventory.items do
	        local Block = bedwars.ItemMeta[v.itemType].block
	        if Block and (Wool.Enabled and v.itemType:find("wool") or not Wool.Enabled and not table.find(Blacklist.ListEnabled, v.itemType:find("wool") and "wool" or v.itemType)) then
	            table.insert(Blocks, {Type = v.itemType, Health = Block.health, Tool = v.tool, Amount = v.amount or math.huge})
	        end
	    end
	    if #Blocks > 1 then
	        table.sort(Blocks, function(A, B): boolean
	            return A.Health > B.Health
	        end)
	    end
	    return Blocks
	end
	
	local function GetLayerBlock(Blocks, Layer: number)
	    local Count: number = #Blocks
	    for i: number = 0, Count - 1 do
	        local Block = Blocks[(math.min(Layer, Count) + i - 1) % Count + 1]
	        if Block.Amount > 0 then
	            return Block
	        end
	    end
	    return nil
	end
	
	local function GetPyramid(Size: number, Grid: number): {Vector3}
	    local Positions: {Vector3} = {}
	    for Height: number = Size, 0, -1 do
	        for Width: number = Height, 0, -1 do
	            table.insert(Positions, Vector3.new(Width, (Size - Height), ((Height + 1) - Width)) * Grid)
	            table.insert(Positions, Vector3.new(Width * -1, (Size - Height), ((Height + 1) - Width)) * Grid)
	            table.insert(Positions, Vector3.new(Width, (Size - Height), (Height - Width) * -1) * Grid)
	            table.insert(Positions, Vector3.new(Width * -1, (Size - Height), (Height - Width) * -1) * Grid)
	        end
	    end
	    return Positions
	end
	
	local function GetPyramidRange(Size: number): number
	    local Far: number = 0
	    for _, v: Vector3 in GetPyramid(Size, 3) do
	        Far = math.max(Far, v.Magnitude)
	    end
	    return Far
	end
	
	local function GetBedNear()
	    local LocalPosition: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Vector3.zero
	    local Range: number = PlaceRange.Value + GetPyramidRange(Layers.Value)
	    for _, v: BasePart in CollectionService:GetTagged("bed") do
	        if (LocalPosition - v.Position).Magnitude < Range and v:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) then
	            return v
	        end
	    end
	    return nil
	end
	
	local function PlaceLayer(Bed: BasePart, Blocks, Layer: number): boolean
	    local PlaceDelay: number = 1 / math.min(bedwars.DefaultPlaceCPS or math.huge, bedwars.SharedConstants.BLOCK_PLACE_CPS)
	    for _, Offset: Vector3 in GetPyramid(Layer, 3) do
	        if not BedProtector.Enabled or not Entity.isAlive then
	            return false
	        end
	        local Position: Vector3 = (Bed.CFrame * CFrame.new(Offset)).Position
	        if GetPlacedBlock(Position) then
	            continue
	        end
	        if (Entity.character.RootPart.Position - Position).Magnitude > PlaceRange.Value then
	            continue
	        end
	        local Block = GetLayerBlock(Blocks, Layer)
	        if not Block then
	            return false
	        end
	
	        repeat
	            task.wait()
	        until not BedProtector.Enabled or not Entity.isAlive or (workspace:GetServerTimeNow() - bedwars.BlockCpsController.lastPlaceTimestamp) >= PlaceDelay
	        if not BedProtector.Enabled or not Entity.isAlive then
	            return false
	        end
	
	        if Switch.Enabled and HotbarSwitch(GetHotbar(Block.Tool)) then
	            task.wait()
	        end
	        task.spawn(bedwars.placeBlock, Position, Block.Type, false)
	        if GetPlacedBlock(Position) then
	            Block.Amount -= 1
	        end
	    end
	    return true
	end
	
	BedProtector = vape.Categories.World:CreateModule({
	    Name = "BedProtector",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                local Bed = GetBedNear()
	                if Bed then
	                    local Blocks = GetBlocks()
	                    local PreviousSlot: number? = Switch.Enabled and Store.hand and Store.hand.tool and GetHotbar(Store.hand.tool) or nil
	
	                    for Layer: number = 1, Layers.Value do
	                        if #Blocks == 0 or not PlaceLayer(Bed, Blocks, Layer) then
	                            break
	                        end
	                    end
	
	                    if PreviousSlot and HotbarSwitch(PreviousSlot) then
	                        task.wait()
	                    end
	                else
	                    if Mode.Value == "On Key" then
	                        SendNotification("BedProtector", "Unable to locate bed", 5)
	                        BedProtector:Toggle()
	                        break
	                    end
	                end
	                task.wait(0.5)
	                if Mode.Value == "On Key" then
	                    BedProtector:Toggle()
	                    break
	                end
	            until not BedProtector.Enabled
	        end
	    end,
	    Tooltip = "Automatically places strong blocks around the bed."
	})
	
	Mode = BedProtector:CreateDropdown({
	    Name = "Mode",
	    List = {"Toggle", "On Key"},
	    Function = function(Val: string)
	        if Smart then
	            Smart.Object.Visible = Val == "Toggle"
	        end
	    end,
	    Default = "Toggle"
	})
	Blacklist = BedProtector:CreateTextList({
	    Name = "Blacklist",
	    Default = {"siege_tnt", "tnt"}
	})
	PlaceRange = BedProtector:CreateSlider({
	    Name = "Place Range",
	    Min = 1,
	    Max = 30,
	    Default = 15
	})
	Layers = BedProtector:CreateSlider({
	    Name = "Layers",
	    Min = 1,
	    Max = 6,
	    Default = 2,
	    Tooltip = "How many layers go around your bed. Your strongest block goes closest to it, and your weakest one is reused when you have fewer block types than layers"
	})
	Wool = BedProtector:CreateToggle({Name = "Wool only", Tooltip = "Only uses wools to bed defend."})
	Switch = BedProtector:CreateToggle({Name = "Auto Switch"})
	Smart = BedProtector:CreateToggle({Name = "Smart", Default = true})
end)

Run(function()
	local BlockIn
	local Mode
	local PlacementMode
	local PlacementSpeed
	local Center
	local Priority
	local Return
	local Switch
	local Wool
	local Blacklist
	local CenterOrigin: Vector3?
	local LastPlace: number = 0
	
	local Scan: number = 30
	local Directions: {Vector3} = {
	    Vector3.new(1, 0, 0),
	    Vector3.new(-1, 0, 0),
	    Vector3.new(0, 0, 1),
	    Vector3.new(0, 0, -1)
	}
	local Priorities = {
	    ["Lowest cost"] = function(A, B): boolean
	        return A.Health < B.Health
	    end,
	    ["Hardest"] = function(A, B): boolean
	        return A.Health > B.Health
	    end
	}
	
	local function GetOrigin(): Vector3
	    local Position: Vector3 = Entity.character.RootPart.Position
	    local Hit: RaycastResult? = Entity.Raycast(Position, Vector3.new(0, -Scan, 0), Store.airRay)
	    return RoundPosition(Hit and Vector3.new(Position.X, Hit.Position.Y + 1.5, Position.Z) or Position)
	end
	
	local function GetBedNear()
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    for _, v: BasePart in CollectionService:GetTagged("bed") do
	        if (LocalPosition - v.Position).Magnitude >= 14 or v:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) then
	            continue
	        end
	
	        local Handler = bedwars.BlockController:getHandlerRegistry():getHandler(v.Name)
	        local Cells = Handler and Handler:getContainedPositions(v) or {v.Position / 3}
	        local Occupied = {}
	        for _, Cell: Vector3 in Cells do
	            Occupied[Cell * 3] = true
	        end
	
	        local Defended: boolean = true
	        for _, Cell: Vector3 in Cells do
	            for i: number = 1, #Sides do
	                local Position: Vector3 = (Cell * 3) + Sides[i]
	                if not Occupied[Position] and not GetPlacedBlock(Position) then
	                    Defended = false
	                    break
	                end
	            end
	            if not Defended then
	                break
	            end
	        end
	
	        if Defended then
	            return v
	        end
	    end
	    return nil
	end
	
	local function GetBlocks()
	    local Blocks = {}
	    for _, v: any in Store.inventory.inventory.items do
	        local Block = bedwars.ItemMeta[v.itemType].block
	        if Block and (Wool.Enabled and v.itemType:find("wool") or not Wool.Enabled and not table.find(Blacklist.ListEnabled, v.itemType:find("wool") and "wool" or v.itemType)) then
	            local Slot: number? = GetHotbar(v.tool)
	            if Slot or not Switch.Enabled then
	                table.insert(Blocks, {Type = v.itemType, Health = Block.health, Slot = Slot, Amount = v.amount or math.huge})
	            end
	        end
	    end
	    if #Blocks > 1 then
	        table.sort(Blocks, Priorities[Priority.Value])
	    end
	    return Blocks
	end
	
	local function GetEnclosure(Origin: Vector3, Grounded: boolean): {Vector3}
	    local Enemy = Entity.EntityPosition({
	        Range = 60,
	        Part = "RootPart",
	        Players = true
	    })
	    local Facing: Vector3 = Enemy and Enemy.RootPart.Position - Origin or Vector3.zero
	    local Order: {Vector3} = table.clone(Directions)
	    table.sort(Order, function(A: Vector3, B: Vector3): boolean
	        return A:Dot(Facing) > B:Dot(Facing)
	    end)
	
	    local Cells: {Vector3} = {}
	    if Grounded and not Entity.Raycast(Origin, Vector3.new(0, -3, 0), Store.airRay) then
	        table.insert(Cells, Vector3.new(0, -3, 0))
	    end
	    for _, Height: number in {0, 3} do
	        for _, Direction: Vector3 in Order do
	            table.insert(Cells, Vector3.new(Direction.X * 3, Height, Direction.Z * 3))
	        end
	    end
	    if Grounded then
	        table.insert(Cells, Vector3.new(Order[1].X * 3, 6, Order[1].Z * 3))
	        table.insert(Cells, Vector3.new(0, 6, 0))
	    end
	    return Cells
	end
	
	local function HoldCenter()
	    if not CenterOrigin or PlacementMode.Value ~= "Blatant" or not Center.Enabled or vape.MovementOwner or not Entity.isAlive then
	        return
	    end
	
	    local Root: BasePart = Entity.character.RootPart
	    if isnetworkowner(Root) then
	        Root.CFrame = CFrame.new(CenterOrigin.X, Root.Position.Y, CenterOrigin.Z) * Root.CFrame.Rotation
	        Root.AssemblyLinearVelocity = Vector3.new(0, Root.AssemblyLinearVelocity.Y, 0)
	    end
	end
	
	local function GetPlaceDelay(): number
	    local CPS: number = math.min(bedwars.DefaultPlaceCPS or math.huge, bedwars.SharedConstants.BLOCK_PLACE_CPS)
	    if PlacementMode.Value == "Legit" then
	        CPS = math.min(CPS, PlacementSpeed.Value)
	    end
	    return 1 / math.max(CPS, 1)
	end
	
	local function PlacePattern(Origin: Vector3, Cells: {Vector3}, Blocks, Limit: number)
	    local Hotbar = Store.hand.tool and GetHotbar(Store.hand.tool) or nil
	    local Placed: number = 0
	
	    for _, Offset: Vector3 in Cells do
	        if Placed >= Limit or not BlockIn.Enabled or not Entity.isAlive then
	            break
	        end
	        local Position: Vector3 = Origin + Offset
	        if GetPlacedBlock(Position) then
	            continue
	        end
	        while Blocks[1] and Blocks[1].Amount <= 0 do
	            table.remove(Blocks, 1)
	        end
	        local Block = Blocks[1]
	        if not Block then
	            break
	        end
	
	        if PlacementMode.Value == "Blatant" and Center.Enabled then
	            CenterOrigin = Origin
	        end
	        repeat
	            task.wait()
	        until not BlockIn.Enabled or not Entity.isAlive or (workspace:GetServerTimeNow() - math.max(LastPlace, bedwars.BlockCpsController.lastPlaceTimestamp)) >= GetPlaceDelay()
	        if not BlockIn.Enabled or not Entity.isAlive then
	            break
	        end
	        if PlacementMode.Value == "Legit" then
	            local OffsetPosition: Vector3 = (Entity.character.RootPart.Position - Origin) * Vector3.new(1, 0, 1)
	            if math.max(math.abs(OffsetPosition.X), math.abs(OffsetPosition.Z)) > 1.5 then
	                break
	            end
	        end
	
	        if Switch.Enabled then
	            HotbarSwitch(Block.Slot)
	        end
	        LastPlace = workspace:GetServerTimeNow()
	        task.spawn(bedwars.placeBlock, Position, Block.Type)
	        if GetPlacedBlock(Position) then
	            Block.Amount -= 1
	            Placed += 1
	        end
	    end
	    if Return.Enabled and Switch.Enabled and Hotbar then
	        HotbarSwitch(Hotbar)
	    end
	end
	
	BlockIn = vape.Categories.World:CreateModule({
	    Name = "Block-In",
	    Function = function(Callback: boolean)
	        if Callback then
	            LastPlace = 0
	            BlockIn:Clean(RunService.PreSimulation:Connect(HoldCenter))
	            BlockIn:Clean(function()
	                CenterOrigin = nil
	            end)
	
	            repeat
	                if Entity.isAlive and (Mode.Value == "On bind" or GetBedNear()) then
	                    local Blocks = GetBlocks()
	                    local Early: boolean = false
	                    repeat
	                        task.wait()
	                        if Entity.isAlive and not Early then
	                            local Origin: Vector3 = GetOrigin()
	                            local Drop: number = Entity.character.RootPart.Position.Y - Origin.Y
	                            Early = Drop >= 6 and Drop <= 24
	                            if Early then
	                                PlacePattern(Origin, GetEnclosure(Origin, false), Blocks, PlacementMode.Value == "Blatant" and Center.Enabled and math.huge or 3)
	                            end
	                        end
	                    until not BlockIn.Enabled or not Entity.isAlive or Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air
	
	                    if Entity.isAlive then
	                        local Origin: Vector3 = GetOrigin()
	                        PlacePattern(Origin, GetEnclosure(Origin, true), Blocks, math.huge)
	                    end
	                    CenterOrigin = nil
	                end
	
	                if Mode.Value == "On bind" then
	                    if BlockIn.Enabled then BlockIn:Toggle() end
	                    break
	                end
	                task.wait(0.5)
	            until not BlockIn.Enabled
	        end
	    end,
	    Tooltip = "Automatically blocks you in by building walls around you"
	})
	
	Mode = BlockIn:CreateDropdown({
	    Name = "Mode",
	    List = {"On bind", "When near"},
	    Default = "On bind",
	    Tooltip = "On bind blocks you in once per keypress, When near keeps you blocked in while you are on an enemy bed"
	})
	PlacementMode = BlockIn:CreateDropdown({
	    Name = "Placement mode",
	    List = {"Legit", "Blatant"},
	    Default = "Legit",
	    Function = function(Val: string)
	        if PlacementSpeed then PlacementSpeed.Object.Visible = Val == "Legit" end
	        if Center then Center.Object.Visible = Val == "Blatant" end
	    end,
	    Tooltip = "Legit uses your placement speed and lets you move freely, Blatant builds at the normal limit with optional centering"
	})
	PlacementSpeed = BlockIn:CreateSlider({
	    Name = "Placement speed",
	    Min = 1,
	    Max = math.max(bedwars.DefaultPlaceCPS or bedwars.SharedConstants.BLOCK_PLACE_CPS, 1),
	    Default = 4,
	    Visible = true,
	    Suffix = "blocks/s",
	    Tooltip = "Blocks placed per second in Legit mode"
	})
	Center = BlockIn:CreateToggle({
	    Name = "Center",
	    Default = true,
	    Visible = false,
	    Tooltip = "Holds you in the middle of your block while it builds, so no side gets skipped"
	})
	Priority = BlockIn:CreateDropdown({
	    Name = "Block priority",
	    List = {"Lowest cost", "Hardest"},
	    Default = "Lowest cost"
	})
	Switch = BlockIn:CreateToggle({Name = "Switch", Default = true})
	Return = BlockIn:CreateToggle({Name = "Return to last slot", Default = true})
	Wool = BlockIn:CreateToggle({Name = "Wool only"})
	Blacklist = BlockIn:CreateTextList({
	    Name = "Blacklist",
	    Default = {"cannon", "siege_tnt", "tnt"}
	})
end)

Run(function()
	local ChestSteal
	local Range
	local Open
	local Skywars
	local Legit
	local Visualize
	local FillColor
	local OutlineColor
	local Animate
	local Speed
	local Delays = {}
	local Boxes = {}
	local Tweens = {}
	local BoxTargets = {}
	
	local function UpdateBoxes(Targets)
	    for i: number, Box: Part in Boxes do
	        local Chest = Targets and Targets[i]
	        if Chest ~= BoxTargets[i] then
	            if Tweens[i] then
	                Tweens[i]:Cancel()
	                Tweens[i] = nil
	            end
	
	            if not Chest then
	                Box.Parent = nil
	            elseif Animate.Enabled and Box.Parent == Camera then
	                Tweens[i] = TweenService:Create(Box, TweenInfo.new(Speed.Value, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CFrame = Chest.CFrame})
	                Tweens[i]:Play()
	            else
	                Box.CFrame = Chest.CFrame
	                Box.Parent = Camera
	            end
	            BoxTargets[i] = Chest
	        end
	
	        if Chest then
	            Box.SelectionBox.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)
	            Box.SelectionBox.Transparency = 1 - OutlineColor.Opacity
	            Box.SelectionBox.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)
	            Box.SelectionBox.SurfaceTransparency = 1 - FillColor.Opacity
	        end
	    end
	end
	
	local function LootChest(Chest)
	    Chest = Chest and Chest.Value or nil
	    
	    local ChestItems = Chest and Chest:GetChildren() or {}
	    if #ChestItems > 1 and (Delays[Chest] or 0) < tick() then
	        Delays[Chest] = tick() + 0.2
	        local Observed = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("ObservedChestFolder")
	        Observed = Observed and Observed.Value or nil
	        bedwars.Client:GetNamespace("Inventory"):Get("SetObservedChest"):SendToServer(Chest)
	
	        for _, v: Instance in ChestItems do
	            if v:IsA("Accessory") then
	                task.spawn(function()
	                    pcall(function()
	                        bedwars.Client:GetNamespace("Inventory"):Get("ChestGetItem"):CallServer(Chest, v)
	                    end)
	                end)
	                if Legit.Enabled then
	                    task.wait(0.2)
	                end
	            end
	        end
	
	        bedwars.Client:GetNamespace("Inventory"):Get("SetObservedChest"):SendToServer(Observed)
	    end
	end
	
	ChestSteal = vape.Categories.World:CreateModule({
	    Name = "ChestSteal",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Chests = Collection("chest", ChestSteal)
	            repeat
	                task.wait()
	            until Store.queueType ~= "bedwars_test"
	            local function GetChestPart(Folder: Instance)
	                for _, v: BasePart in Chests do
	                    local FolderValue: ObjectValue? = v:FindFirstChild("ChestFolderValue")
	                    if FolderValue and FolderValue.Value == Folder then
	                        return v
	                    end
	                end
	                return nil
	            end
	
	            if (not Skywars.Enabled) or Store.queueType:find("skywars") then
	                repeat
	                    local Targets = {}
	                    if Entity.isAlive and Store.matchState ~= 2 then
	                        if Open.Enabled then
	                            if bedwars.AppController:isAppOpen("ChestApp") then
	                                local Observed = LocalPlayer.Character:FindFirstChild("ObservedChestFolder")
	                                LootChest(Observed)
	                                Targets[1] = Observed and Observed.Value and GetChestPart(Observed.Value) or nil
	                            end
	                        else
	                            local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                            local Closest: number = math.huge
	                            for _, v: BasePart in Chests do
	                                local Magnitude: number = (LocalPosition - v.Position).Magnitude
	                                if Magnitude <= Range.Value then
	                                    LootChest(v:FindFirstChild("ChestFolderValue"))
	                                    if Magnitude < Closest then
	                                        Closest, Targets[1] = Magnitude, v
	                                    end
	                                end
	                            end
	                        end
	                    end
	
	                    UpdateBoxes(Targets)
	                    task.wait(0.1)
	                until not ChestSteal.Enabled
	            end
	        else
	            UpdateBoxes(nil)
	        end
	    end,
	    Tooltip = "Grabs items from near chests."
	})
	
	Range = ChestSteal:CreateSlider({
	    Name = "Range",
	    Min = 0,
	    Max = 18,
	    Default = 18,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	Visualize = ChestSteal:CreateToggle({
	    Name = "Visualize",
	    Function = function(Callback: boolean)
	        FillColor.Object.Visible = Callback
	        OutlineColor.Object.Visible = Callback
	        Animate.Object.Visible = Callback
	        Speed.Object.Visible = Callback
	        if Callback then
	            local Part: Part = Instance.new("Part")
	            Part.Size = Vector3.new(3, 3, 3)
	            Part.Anchored = true
	            Part.CanCollide = false
	            Part.CanQuery = false
	            Part.CanTouch = false
	            Part.CastShadow = false
	            Part.Transparency = 1
	            local Selection: SelectionBox = Instance.new("SelectionBox")
	            Selection.Adornee = Part
	            Selection.LineThickness = 0.04
	            Selection.Parent = Part
	            bedwars.QueryUtil:setQueryIgnored(Part, true)
	            Boxes[1] = Part
	        else
	            UpdateBoxes(nil)
	            for _, v: Part in Boxes do
	                v:Destroy()
	            end
	            table.clear(Boxes)
	            table.clear(Tweens)
	            table.clear(BoxTargets)
	        end
	    end,
	    Tooltip = "Draws a box around the closest chest being looted"
	})
	FillColor = ChestSteal:CreateColorSlider({
	    Name = "Fill Color",
	    DefaultSat = 0,
	    DefaultOpacity = 0.25,
	    Darker = true,
	    Visible = false
	})
	OutlineColor = ChestSteal:CreateColorSlider({
	    Name = "Outline Color",
	    DefaultSat = 0,
	    Darker = true,
	    Visible = false
	})
	Animate = ChestSteal:CreateToggle({
	    Name = "Animate",
	    Default = true,
	    Darker = true,
	    Visible = false,
	    Tooltip = "Glides the box onto the next chest instead of snapping to it"
	})
	Speed = ChestSteal:CreateSlider({
	    Name = "Animation time",
	    Min = 0.01,
	    Max = 0.5,
	    Default = 0.08,
	    Decimal = 100,
	    Suffix = "s",
	    Darker = true,
	    Visible = false
	})
	Open = ChestSteal:CreateToggle({Name = "GUI Check"})
	Legit = ChestSteal:CreateToggle(({Name = "Legit mode"}))
	Skywars = ChestSteal:CreateToggle({
	    Name = "Only Skywars",
	    Function = function()
	        if ChestSteal.Enabled then
	            ChestSteal:Toggle()
	            ChestSteal:Toggle()
	        end
	    end,
	    Default = true
	})
end)

