Run(function()
	local AutoCogsworth
	local Targets
	local Collect
	local Steal
	local Range
	local Delay
	local Overclock
	local OverclockRange
	local NextCollect: number = 0
	local NextOverclock: number = 0
	
	local function GetBots()
	    local Controller = bedwars.GatherBotBasicController
	    return Controller and Controller.gatherBotMap or {}
	end
	
	AutoCogsworth = vape.Categories.Kits:CreateModule({
	    Name = "AutoCogsworth",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextCollect = 0
	            NextOverclock = 0
	
	            repeat
	                if Entity.isAlive then
	                    local Origin: Vector3 = Entity.character.RootPart.Position
	
	                    if Collect.Enabled and tick() >= NextCollect then
	                        for Bot: Model in GetBots() do
	                            if not Bot.Parent then
	                                continue
	                            end
	                            local Owner = Bot:GetAttribute("PlacedByUserId")
	                            if not Steal.Enabled and Owner ~= LocalPlayer.UserId then
	                                continue
	                            end
	                            if (Bot:GetAttribute("HeldItemAmount") or 0) <= 0 then
	                                continue
	                            end
	                            if (Bot:GetPivot().Position - Origin).Magnitude > Range.Value then
	                                continue
	                            end
	
	                            bedwars.Handler:Get("GatherBotCollectItems"):Fire("SendToServer", {
	                                gatherBot = Bot
	                            })
	                            NextCollect = tick() + Delay.Value
	                            break
	                        end
	                    end
	
	                    if Overclock.Enabled and Store.equippedKit == "steam_engineer" and tick() >= NextOverclock and bedwars.AbilityController:canUseAbility("STEAM_ENGINEER_OVERCLOCK", {disableBlockedAbilityAlert = true}) then
	                        local Found: boolean = #Entity.AllPosition({
	                            Range = OverclockRange.Value,
	                            Part = "RootPart",
	                            Players = Targets.Players.Enabled,
	                            NPCs = Targets.NPCs.Enabled
	                        }) > 0
	
	                        if Found then
	                            NextOverclock = tick() + 1
	                            bedwars.AbilityController:useAbility("STEAM_ENGINEER_OVERCLOCK")
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoCogsworth.Enabled
	        end
	    end,
	    Tooltip = "Empties gather bots from across the map and overclocks when a fight starts"
	})
	
	Targets = AutoCogsworth:CreateTargets({
	    Players = true,
	    NPCs = true
	})
	Collect = AutoCogsworth:CreateToggle({
	    Name = "Collect bots",
	    Default = true,
	    Tooltip = "The games own collect prompt stops at 10 studs, the server never checks it"
	})
	Steal = AutoCogsworth:CreateToggle({
	    Name = "Steal enemy bots",
	    Tooltip = "Also empties gather bots that somebody else placed"
	})
	Range = AutoCogsworth:CreateSlider({
	    Name = "Range",
	    Min = 5,
	    Max = 500,
	    Default = 250,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	Delay = AutoCogsworth:CreateSlider({
	    Name = "Delay",
	    Min = 0.1,
	    Max = 3,
	    Default = 0.3,
	    Decimal = 100,
	    Suffix = function(Val: number)
	        return Val <= 1 and "sec" or "secs"
	    end
	})
	Overclock = AutoCogsworth:CreateToggle({
	    Name = "Overclock",
	    Default = true,
	    Function = function(Callback: boolean)
	        if OverclockRange then
	            OverclockRange.Object.Visible = Callback
	        end
	    end
	})
	OverclockRange = AutoCogsworth:CreateSlider({
	    Name = "Overclock range",
	    Min = 1,
	    Max = 60,
	    Default = 25,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
end)

Run(function()
	local AutoConqueror
	local Targets
	local Banner
	local Mode
	local Range = {}
	local Cooldown
	local Switch
	local SwitchDelay = {}
	local NextPlace: number = 0
	local Placing: boolean = false
	
	local Banners: {[string]: string} = {
	    Fire = "damage_banner",
	    Defense = "defense_banner",
	    Heal = "heal_banner"
	}
	
	local function PlaceBanner()
	    if Placing or tick() < NextPlace or not Entity.isAlive then
	        return
	    end
	
	    local ItemType: string = Banners[Banner.Value]
	    local Item = getItem(Banners[Banner.Value])
	    local Item = Item and (Item.amount or 1) > 0 and Item or nil
	    if not Item then
	        return
	    end
	
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    for _, v: Instance in CollectionService:GetTagged("flag-kit") do
	        if v:IsA("BasePart") and v.Name == ItemType and (v.Position - LocalPosition).Magnitude <= bedwars.ConquerorBalance.CONQUEROR_FLAG_RADIUS / 2 then
	            return
	        end
	    end
	
	    local Character = Entity.character
	    local Base: Vector3 = roundPos(Character.RootPart.Position - Vector3.new(0, Character.HipHeight + 1.5, 0))
	    local Spot: Vector3?
	    for _, v: Vector3 in {Vector3.new(3, 3, 0), Vector3.new(-3, 3, 0), Vector3.new(0, 3, 3), Vector3.new(0, 3, -3), Vector3.new(0, 3, 0)} do
	        local Position: Vector3 = Base + v
	        if not getPlacedBlock(Position) and getPlacedBlock(Position - Vector3.new(0, 3, 0)) then
	            Spot = Position
	            break
	        end
	    end
	    if not Spot then
	        return
	    end
	
	    Placing = true
	    NextPlace = tick() + Cooldown.Value
	    local Hotbar = Switch.Enabled and store.hand.tool and getHotbar(store.hand.tool) or nil
	
	    if not Switch.Enabled or hotbarSwitch(getHotbar(Item.tool)) then
	        if Switch.Enabled then
	            task.wait(SwitchDelay.Value)
	        end
	
	        bedwars.placeBlock(Spot, ItemType)
	
	        if Hotbar then
	            task.wait(SwitchDelay.Value)
	            hotbarSwitch(Hotbar)
	        end
	    end
	    Placing = false
	end
	
	AutoConqueror = vape.Categories.Kits:CreateModule({
	    Name = "AutoConqueror",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextPlace = 0
	            Placing = false
	
	            AutoConqueror:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)
	                if Mode.Value ~= "On attack" or DamageTable.damageType ~= 0 or store.equippedKit ~= "vesta" then
	                    return
	                end
	
	                local Character: Model? = LocalPlayer.Character
	                if (DamageTable.fromEntity and DamageTable.fromEntity.Name == LocalPlayer.Name) or (Character and DamageTable.entityInstance == Character) then
	                    task.spawn(PlaceBanner)
	                end
	            end))
	
	            repeat
	                if Mode.Value == "On near" and Entity.isAlive and store.equippedKit == "vesta" and Entity.EntityPosition({
	                    Range = Range.Value,
	                    Part = "RootPart",
	                    Players = Targets.Players.Enabled,
	                    NPCs = Targets.NPCs.Enabled,
	                    Priority = Targets.Priority.Value,
	                    Wallcheck = Targets.Walls.Enabled or nil
	                }) then
	                    PlaceBanner()
	                end
	                task.wait(0.1)
	            until not AutoConqueror.Enabled
	        else
	            Placing = false
	        end
	    end,
	    Tooltip = "Drops a Conqueror banner beside you when a fight starts"
	})
	
	Targets = AutoConqueror:CreateTargets({
	    Players = true,
	    NPCs = false
	})
	Banner = AutoConqueror:CreateDropdown({
	    Name = "Banner",
	    List = {"Fire", "Defense", "Heal"},
	    Tooltip = "Which banner to put down, Fire gives the damage buff"
	})
	Mode = AutoConqueror:CreateDropdown({
	    Name = "Place on",
	    List = {"On attack", "On near"},
	    Function = function(Val: string)
	        if Range.Object then
	            Range.Object.Visible = Val == "On near"
	        end
	    end,
	    Tooltip = "On attack waits until you trade hits, On near drops it as soon as someone walks up"
	})
	Range = AutoConqueror:CreateSlider({
	    Name = "Range",
	    Min = 5,
	    Max = 100,
	    Default = 30,
	    Darker = true,
	    Visible = false,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "How close an enemy has to be for On near"
	})
	Cooldown = AutoConqueror:CreateSlider({
	    Name = "Cooldown",
	    Min = 1,
	    Max = 60,
	    Default = 30,
	    Suffix = "seconds",
	    Tooltip = "Time before it puts another one down, a banner lasts 30 seconds"
	})
	Switch = AutoConqueror:CreateToggle({
	    Name = "Legit switch",
	    Function = function(Callback: boolean)
	        if SwitchDelay.Object then
	            SwitchDelay.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Holds the banner through the hotbar and puts your item back after"
	})
	SwitchDelay = AutoConqueror:CreateSlider({
	    Name = "Switch delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Default = 0.08,
	    Darker = true,
	    Visible = false,
	    Suffix = "seconds"
	})
end)

