Run(function()
	local AutoKaliyah
	local Range
	local Stacks
	local Delay
	local NoSlow
	
	local Legit: number = GetFunctionRange(bedwars.DragonSlayerController.hasEligiblePunchTarget) or 14.4
	local Modifier, Old
	local NoSlowUntil: number = 0
	
	local function Punch()
	    if NoSlow.Enabled then
	        if not Old then
	            Modifier = bedwars.SprintController:getMovementStatusModifier()
	            Old = Modifier.addModifier
	            Modifier.addModifier = function(self, Data)
	                if NoSlow.Enabled and tick() < NoSlowUntil and Data and Data.moveSpeedMultiplier == 0 then
	                    Data.moveSpeedMultiplier = 1
	                end
	                return Old(self, Data)
	            end
	
	            AutoKaliyah:Clean(function()
	                Modifier.addModifier = Old
	                Modifier, Old = nil, nil
	                NoSlowUntil = 0
	            end)
	        end
	        NoSlowUntil = math.max(NoSlowUntil, tick() + Delay.Value + 0.1)
	    end
	
	    task.wait(Delay.Value)
	    bedwars.AbilityController:useAbility("dragon_slayer_punch")
	end
	
	AutoKaliyah = vape.Categories.Kits:CreateModule({
	    Name = "AutoKaliyah",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                if Entity.isAlive and Store.equippedKit == "dragon_slayer" and bedwars.AbilityController:canUseAbility("dragon_slayer_punch", {disableBlockedAbilityAlert = true}) then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    for Target: Model, Emblem: any in bedwars.DragonSlayerController.dragonEmblems do
	                        if Emblem.stackCount >= Stacks.Value and Target.PrimaryPart and (Target.PrimaryPart.Position - LocalPosition).Magnitude <= Range.Value then
	                            Punch()
	                            break
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoKaliyah.Enabled
	        end
	    end,
	    Tooltip = 'Automatically uses the "punch" ability from kaliyah'
	})
	
	NoSlow = AutoKaliyah:CreateToggle({
	    Name = "No Slow",
	    Default = true,
	    Tooltip = 'Prevents you from being slowed down after using the "Punch" ability'
	})
	Range = AutoKaliyah:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 20,
	    Default = 18,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	AutoKaliyah:CreateButton({
	    Name = "Sync to legit range",
	    Function = function()
	        Range:SetValue(Legit)
	    end
	})
	Stacks = AutoKaliyah:CreateSlider({
	    Name = "Stacks",
	    Min = 1,
	    Max = 3,
	    Default = 1,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stack" or "stacks"
	    end,
	    Tooltip = "How many emblems a target needs before the punch fires, 3 stacks deals 25 damage against a wall instead of 10"
	})
	Delay = AutoKaliyah:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 1,
	    Default = 0.1,
	    Decimal = 100
	})
end)

Run(function()
	local AutoKit
	local Legit
	local Toggles = {}
	local Running = {}
	
	local function NewSession()
	    local Session = {Tasks = {}}
	
	    function Session:Clean(Task: any)
	        table.insert(self.Tasks, type(Task) == "function" and {Disconnect = Task} or Task)
	    end
	
	    function Session:Stop()
	        if self.Thread and coroutine.status(self.Thread) ~= "dead" then
	            task.cancel(self.Thread)
	        end
	        for _, v: any in self.Tasks do
	            v:Disconnect()
	        end
	        table.clear(self.Tasks)
	    end
	
	    return Session
	end
	
	local function KitCollection(Id, Callback: (Instance) -> (), Range: number, Specific: boolean, Session)
	    local Objects = type(Id) == "table" and Id or Collection(Id, Session)
	    repeat
	        if Entity.isAlive then
	            local LocalPosition: Vector3 = Entity.character.RootPart.Position
	            for _, v: Instance in Objects do
	                if (vape.Modules.InfiniteFly or {}).Enabled or not AutoKit.Enabled then
	                    break
	                end
	                local Part = not v:IsA("Model") and v or (v.PrimaryPart or v:FindFirstChildWhichIsA("BasePart", true))
	                if Part and (Part.Position - LocalPosition).Magnitude <= (not Legit.Enabled and Specific and math.huge or Range) then
