	local function StopKits()
	    for Kit: string, Session: any in Running do
	        Running[Kit] = nil
	        Session:Stop()
	    end
	end
	
	local function SyncKits()
	    local Kits: {string} = Store.equippedKits or {}
	    for Kit: string, Session: any in Running do
	        if not table.find(Kits, Kit) or not Toggles[Kit].Enabled then
	            Running[Kit] = nil
	            Session:Stop()
	        end
	    end
	
	    for _, v: string in Kits do
	        if AutoKitFunctions[v] and Toggles[v].Enabled and not Running[v] then
	            local Session = NewSession()
	            Running[v] = Session
	            Session.Thread = task.spawn(AutoKitFunctions[v], Session)
	        end
	    end
	end
	
	AutoKit = vape.Categories.Kits:CreateModule({
	    Name = "AutoKit",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoKit:Clean(StopKits)
	            repeat
	                if Store.matchState ~= 0 then
	                    SyncKits()
	                end
	                task.wait(0.5)
	            until not AutoKit.Enabled
	        end
	    end,
	    Tooltip = "Automatically uses kit abilities for every kit you have, including both kits in Kit Fusion."
	})
	
	Legit = AutoKit:CreateToggle({Name = "Legit Range"})
	local function KitName(Kit: string): string
	    local Meta = bedwars.BedwarsKitMeta[Kit]
	    return Meta and Meta.name or Kit
	end
	
	local SortTable: {string} = {}
	for Kit: string in AutoKitFunctions do
	    table.insert(SortTable, Kit)
	end
	table.sort(SortTable, function(A: string, B: string)
	    return KitName(A) < KitName(B)
	end)
	for _, v: string in SortTable do
	    Toggles[v] = AutoKit:CreateToggle({
	        Name = KitName(v),
	        Default = true
	    })
	end
end)

Run(function()
	local AutoKrystal
	
	local function GetBed(): BasePart?
	    local LocalPosition: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Vector3.zero
	    for _, v: BasePart in CollectionService:GetTagged("bed") do
	        if (LocalPosition - v.Position).Magnitude <= 22 and not v:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) then
	            return v
	        end
	    end
	    return
	end
	
	AutoKrystal = vape.Categories.Kits:CreateModule({
	    Name = "AutoKrystal",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                local Bed = Entity.isAlive and Store.equippedKit == "glacial_skater" and bedwars.AbilityController:canUseAbility("skating_freeze", {disableBlockedAbilityAlert = true}) and GetBed()
	                if Bed then
	                    for _, v: BasePart in Store.blocks do
	                        if (Bed.Position - v.Position).Magnitude <= 20 and v:GetAttribute("PlacedByUserId") then
	                            bedwars.AbilityController:useAbility("skating_freeze")
	                            break
	                        end
	                    end
	                end
