	    Tooltip = "Automatically uses freeze ability when near\nopponent's bed defense."
	})
end)

Run(function()
	local AutoLani
	local Delay
	local UseEnemy
	local Enemy
	local Player
	
	local Request = bedwars.Handler:Get("PaladinAbilityRequest")
	
	AutoLani = vape.Categories.Kits:CreateModule({
	    Name = "AutoLani",
	    Function = function(Callback: boolean)
	        if Callback then
	            local OldStart
	
	            repeat
	                local Start = LocalPlayer:GetAttribute("PaladinStartTime")
	                if OldStart and OldStart ~= Start then
	                    local Target = UseEnemy.Enabled and Players:FindFirstChild(Enemy.Value) or not UseEnemy.Enabled and Players:FindFirstChild(Player.Value) or nil
	                    if Target then
	                        task.delay(Delay.Value, function()
	                            Request:Fire("SendToServer", {target = Target})
	                        end)
	                    end
	                end
	                OldStart = Start
	                task.wait(0.1)
	            until not AutoLani.Enabled
	        end
	    end,
	    Tooltip = 'Automatically uses the "scepter of light" ability'
	})
	
	local Friends, Enemies = {"None"}, {"None"}
	
	local function AddConnection(TargetPlayer: Player, Connected: boolean?)
	    local Friendly: boolean = TargetPlayer:GetAttribute("Team") == LocalPlayer:GetAttribute("Team")
	
	    if not Connected then
	        vape:Clean(TargetPlayer:GetAttributeChangedSignal("Team"):Connect(function()
	            AddConnection(TargetPlayer, true)
	        end))
	    end
	
	    if Friendly and not table.find(Friends, TargetPlayer.Name) then
	        table.insert(Friends, TargetPlayer.Name)
	        Player:Change(Friends)
	    elseif not Friendly and TargetPlayer.Team and TargetPlayer.Team.Name ~= "Spectators" and not table.find(Enemies, TargetPlayer.Name) then
	        table.insert(Enemies, TargetPlayer.Name)
	        Enemy:Change(Enemies)
	    end
	end
	
	Player = AutoLani:CreateDropdown({
	    Name = "Selected Player",
	    List = {},
	    Tooltip = "Player to use the ability on"
	})
	Enemy = AutoLani:CreateDropdown({
	    Name = "Selected Enemy",
	    List = {},
	    Visible = false,
	    Tooltip = "Target to use the ability on"
	})
	UseEnemy = AutoLani:CreateToggle({
	    Name = "Use enemy",
	    Function = function(Callback: boolean)
	        Enemy.Object.Visible = Callback
	        Player.Object.Visible = not Callback
	    end,
	    Tooltip = "Uses the ability on other people instead of your teammates"
	})
	Delay = AutoLani:CreateSlider({
	    Name = "Delay",
	    Min = 1,
	    Max = 20,
	    Default = 5,
	    Decimal = 10,
	    Suffix = function(Val: number)
	        return Val <= 1 and "sec" or "secs"
	    end,
	    Tooltip = "Delay between triggers"
	})
	for _, v: Player in Players:GetPlayers() do
	    AddConnection(v)
	end
	vape:Clean(Players.PlayerAdded:Connect(AddConnection))
end)

Run(function()
	local AutoLasso
	local Targets
	local Range
	local FireRate
	local SwitchDelay
	local NextFire: number = 0
	local Session = nil
	
	local function ThrowLasso()
	    local Item = GetItem("lasso")
	    local Source = Item and bedwars.ItemMeta.lasso.projectileSource or nil
	    local Target = Source and GetFacingEntity({
	        Part = "RootPart",
	        Range = Range.Value,
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Priority = Targets.Priority.Value,
	        Wallcheck = Targets.Walls.Enabled,
	        Limit = 10
	    }) or nil
	    if not Target then
	        return
	    end
	
	    NextFire = tick() + 0.5
	    local Current = Session
	    local Previous: Tool? = Store.hand.tool
	    local Hotbar: number? = GetHotbar(Item.tool)
	    if Hotbar then
	        bedwars.Store:dispatch({type = "InventorySelectHotbarSlot", slot = Hotbar})
	    else
	        SwitchItem(Item.tool)
	    end
	    task.wait(math.max(LocalPlayer:GetNetworkPing() * 2, Store.ping.total or 0, 0.05))
	    if AutoLasso.Enabled and Session == Current and Entity.isAlive and Target.RootPart.Parent and Store.hand.tool == Item.tool then
	        if FireProjectile(Item, "lasso", Source.projectileType("lasso"), Target) then
	            NextFire = tick() + Source.fireDelaySec + FireRate:GetRandomValue()
	            task.wait(SwitchDelay.Value)
	        end
	    end
	    if Previous and Previous.Parent and Session == Current and (not Store.hand.tool or Store.hand.tool == Item.tool) then
	        local PreviousSlot: number? = GetHotbar(Previous)
	        if PreviousSlot then bedwars.Store:dispatch({type = "InventorySelectHotbarSlot", slot = PreviousSlot}) else SwitchItem(Previous) end
	    end
	end
	
	AutoLasso = vape.Categories.Kits:CreateModule({
	    Name = "AutoLasso",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Current = {}
	            Session = Current
	            NextFire = 0
	
	            repeat
	                local Meleeing: boolean = (tick() - bedwars.SwordController.lastSwing) < 0.3 or Store.attacking or (workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack) < 0.3
	                if Entity.isAlive and (Store.equippedKit == "cowgirl" or table.find(Store.equippedKits or {}, "cowgirl")) and (Store.hand.toolType == "sword" or Store.hand.tool and Store.hand.tool.Name == "lasso") and Meleeing and tick() >= NextFire then
	                    ThrowLasso()
	                end
	                task.wait(0.1)
	            until not AutoLasso.Enabled or Session ~= Current
	        end
	    end,
	    Tooltip = "Automatically throws Lassy's lasso at whoever you're meleeing"
	})
	
	Targets = AutoLasso:CreateTargets({
	    Players = true,
	    NPCs = false
	})
	Range = AutoLasso:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 60,
	    Default = 22,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	FireRate = AutoLasso:CreateTwoSlider({
	    Name = "Fire Rate",
	    Min = 0,
	    Max = 1,
	    DefaultMin = 0.05,
	    DefaultMax = 0.12,
	    Decimal = 100
	})
	SwitchDelay = AutoLasso:CreateSlider({
	    Name = "Switch Delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Suffix = "seconds",
	    Default = 0.02
	})
end)

Run(function()
	local AutoLumen
	local Targets
	local Range
	local FullCharge
	local Delay
	
	local Balance = bedwars.LumenBalance or {MIN_CHARGE_TIME = 0.65, MAX_CHARGE_TIME = 1.25}
	local Sword: string = "light_sword"
	local Cooldown: number = 0
	
	local function ChargedSwing()
	    local ChargeController = bedwars.SwordChargeController
	    if ChargeController:getChargeState() ~= bedwars.ChargeState.Idle then
	        return
	    end
	
	    ChargeController:startCharging(Sword)
	    local Started: number = ChargeController:getChargeStartTime()
	    if Started == 0 then
	        return
	    end
	
	    local ItemMeta = bedwars.ItemMeta[Sword]
	    local Charged = ItemMeta and ItemMeta.sword and ItemMeta.sword.chargedAttack
	    local TargetTime: number = (FullCharge.Enabled and (Charged and Charged.maxChargeTimeSec or Balance.MAX_CHARGE_TIME) or (Charged and Charged.minChargeTimeSec or Balance.MIN_CHARGE_TIME)) + 0.05
	    repeat
	        task.wait()
	    until not AutoLumen.Enabled or not Entity.isAlive or (tick() - Started) >= TargetTime
	
	    local ChargeTime: number = tick() - Started
	    ChargeController:stopCharging(Sword)
	    if not AutoLumen.Enabled or not Entity.isAlive then
	        return
	    end
	
	    local Tool = Store.hand.tool
	    if not Tool or Tool.Name ~= Sword then
	        return
	    end
	
	    local Charged = bedwars.ItemMeta[Sword].sword.chargedAttack
	    if not (Charged.skipSwingDamage and ChargeTime > (Charged.minChargeTimeSec or Balance.MIN_CHARGE_TIME)) then
	        bedwars.SwordController:swingSwordAtMouse(ChargeTime)
	    end
	
	    bedwars.SyncEvents.SwordChargedSwing:fire(LocalPlayer, Tool, {chargeTime = ChargeTime})
	    Cooldown = tick() + Delay.Value
	end
	
	AutoLumen = vape.Categories.Kits:CreateModule({
	    Name = "AutoLumen",
	    Function = function(Callback: boolean)
	        if Callback then
	            Cooldown = 0
	
	            repeat
	                if Entity.isAlive and Store.equippedKit == "lumen" and Store.hand.tool and Store.hand.tool.Name == Sword and tick() >= Cooldown then
	                    local Target = Entity.EntityMouse({
	                        Origin = Entity.character.RootPart.Position,
	                        Range = Range.Value,
	                        Part = "RootPart",
	                        Players = Targets.Players.Enabled,
	                        NPCs = Targets.NPCs.Enabled,
	                        Priority = Targets.Priority.Value,
	                        Wallcheck = Targets.Walls.Enabled
	                    })
	
	                    if Target then
	                        ChargedSwing()
