Run(function()
	local AutoSophia
	local Targets
	local Range
	local FireRate
	local SwitchDelay
	local NextFire: number = 0
	local NextSwap: number = 0
	
	local Staffs: {string} = {"frost_staff_3", "frost_staff_2", "frost_staff_1"}
	
	local function ShootStaff()
	    local Item, ItemType
	    for _, v: string in Staffs do
	        Item = GetItem(v)
	        if Item then
	            ItemType = v
	            break
	        end
	    end
	    local Source = Item and bedwars.ItemMeta[ItemType].projectileSource or nil
	    local Target = Source and GetFacingEntity({
	        Part = "RootPart",
	        Range = Range.Value,
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Priority = Targets.Priority.Value,
	        Wallcheck = Targets.Walls.Enabled,
	        Limit = 10
	    }) or nil
	    if not Target then
	        return
	    end
	
	    local Ready: boolean = bedwars.FrostyGunController.projectileMode == bedwars.FrostyGunMode.PROJECTILE
	    local Swapping: boolean = not Ready and tick() >= NextSwap and bedwars.AbilityController:canUseAbility("frosty_gun_swap", {disableBlockedAbilityAlert = true})
	    if not Ready and not Swapping then
	        return
	    end
	
	    local Hotbar = Store.hand.tool and GetHotbar(Store.hand.tool) or nil
	    if HotbarSwitch(GetHotbar(Item.tool)) then
	        task.wait(Store.ping.total or 0)
	        if Ready then
	            if FireProjectile(Item, ItemType, Source.projectileType(ItemType), Target) then
	                NextFire = tick() + Source.fireDelaySec + FireRate:GetRandomValue()
	                task.wait(SwitchDelay.Value)
	            end
	        else
	            NextSwap = tick() + 1
	            bedwars.AbilityController:useAbility("frosty_gun_swap")
	            task.wait(SwitchDelay.Value)
	        end
	        HotbarSwitch(Hotbar)
	    end
	end
	
	AutoSophia = vape.Categories.Kits:CreateModule({
	    Name = "AutoSophia",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextFire, NextSwap = 0, 0
	
	            repeat
	                if Entity.isAlive and Store.equippedKit == "winter_lady" and Store.hand.toolType == "sword" and (tick() - bedwars.SwordController.lastSwing) < 0.2 and tick() >= NextFire then
	                    ShootStaff()
	                end
	                task.wait(0.1)
	            until not AutoSophia.Enabled
	        end
	    end,
	    Tooltip = "Automatically shoots Sophia's frost staff at whoever you're meleeing, swapping it out of mist mode when needed"
	})
	
	Targets = AutoSophia:CreateTargets({
	    Players = true,
	    NPCs = false
	})
	Range = AutoSophia:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 60,
	    Default = 22,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	FireRate = AutoSophia:CreateTwoSlider({
	    Name = "Fire Rate",
	    Min = 0,
	    Max = 1,
	    DefaultMin = 0.05,
	    DefaultMax = 0.12,
	    Decimal = 100
	})
	SwitchDelay = AutoSophia:CreateSlider({
	    Name = "Switch Delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Suffix = "seconds",
	    Default = 0.02
	})
end)

Run(function()
	local AutoStar
	local Streamer
	local Range
	local Animation
	local Delay
	
	local Cooldowns: {[Instance]: number} = {}
	
	AutoStar = vape.Categories.Kits:CreateModule({
	    Name = "AutoStarCollector",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoStar:Clean(ProximityPromptService.PromptShown:Connect(function(Prompt: ProximityPrompt)
	                if Streamer.Enabled and Prompt.Name == "stars_ProximityPrompt" then
	                    task.wait(0.1)
	                    Prompt:InputHoldBegin()
	                end
	            end))
	
	            repeat
	                if not Streamer.Enabled and Entity.isAlive then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    for _, v: Model in CollectionService:GetTagged("stars") do
	                        if tick() > (Cooldowns[v] or 0) and v.PrimaryPart and (LocalPosition - v.PrimaryPart.Position).Magnitude <= Range.Value then
	                            if Delay.Value > 0 then
	                                task.wait(Delay.Value)
	                            end
	
	                            if (LocalPosition - v.PrimaryPart.Position).Magnitude <= Range.Value then
	                                if Animation.Enabled then
	                                    bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.PUNCH)
	                                    bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM)
	                                end
	
	                                bedwars.StarCollectorController:collectEntity(LocalPlayer, v, v.Name)
	                                Cooldowns[v] = tick() + 1
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoStar.Enabled
	        else
	            table.clear(Cooldowns)
	        end
	    end,
	    Tooltip = "Automatically collects stars"
	})
	
	Streamer = AutoStar:CreateToggle({
	    Name = "Streamer mode",
	    Function = function(Callback: boolean)
	        if Delay then
	            Delay.Object.Visible = not Callback
	            Range.Object.Visible = not Callback
	            Animation.Object.Visible = not Callback
	        end
	    end,
	    Tooltip = "Useful for when ur screensharing"
	})
	Animation = AutoStar:CreateToggle({
	    Name = "Animation",
	    Default = true,
	    Tooltip = "Plays the collect animation"
	})
	Range = AutoStar:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 20,
	    Default = 12,
	    Suffix = function(Val: number)
	        return Val > 1 and "studs" or "stud"
	    end
	})
	Delay = AutoStar:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 1,
	    Default = 0.2,
	    Decimal = 100,
	    Suffix = function(Val: number)
	        return Val > 1 and "secs" or "sec"
	    end
	})
end)

