Run(function()
	local AutoVoidRegent
	local Height
	local FallSpeed
	local Switch
	local SwitchDelay = {}
	local LimitItem
	local NextSlam: number = 0
	
	local function Slam(Axe)
	    if store.hand.tool ~= Axe.tool then
	        if Switch.Enabled then
	            hotbarSwitch(getHotbar(Axe.tool))
	        else
	            switchItem(Axe.tool, 0)
	        end
	        task.wait(SwitchDelay.Value)
	    end
	
	    if AutoVoidRegent.Enabled and Entity.isAlive and bedwars.AbilityController:canUseAbility("void_axe_jump", {disableBlockedAbilityAlert = true}) then
	        bedwars.VoidAxeController:useVoidAxe()
	    end
	end
	
	AutoVoidRegent = vape.Categories.Kits:CreateModule({
	    Name = "AutoVoidRegent",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextSlam = 0
	
	            AutoVoidRegent:Clean(RunService.Heartbeat:Connect(function()
	                if not Entity.isAlive or store.equippedKit ~= "regent" or tick() < NextSlam or not bedwars.VoidAxeController then
	                    return
	                end
	
	                local Root: BasePart = Entity.character.RootPart
	                if Root.AssemblyLinearVelocity.Y > -FallSpeed.Value then
	                    return
	                end
	                if not bedwars.AbilityController:canUseAbility("void_axe_jump", {disableBlockedAbilityAlert = true}) then
	                    return
	                end
	                if not Entity.Raycast(Root.Position, Vector3.new(0, -Height.Value, 0), store.airRay) then
	                    return
	                end
	
	                local Axe
	                if store.hand.tool and store.hand.tool.Name == "void_axe" then
	                    Axe = store.hand
	                elseif not LimitItem.Enabled then
	                    Axe = getItem("void_axe")
	                end
	                if not Axe then
	                    return
	                end
	
	                NextSlam = tick() + bedwars.VoidRegentBalance.AXE_COOLDOWN
	                task.spawn(Slam, Axe)
	            end))
	        end
	    end,
	    Tooltip = "Slams the void axe down right before you land"
	})
	
	Height = AutoVoidRegent:CreateSlider({
	    Name = "Height",
	    Min = 3,
	    Max = 60,
	    Default = 15,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "Slams once the ground is this close beneath you"
	})
	FallSpeed = AutoVoidRegent:CreateSlider({
	    Name = "Fall speed",
	    Min = 0,
	    Max = 100,
	    Default = 10,
	    Tooltip = "Only slams once you are dropping this fast"
	})
	Switch = AutoVoidRegent:CreateToggle({
	    Name = "Legit switch",
	    Function = function(Callback: boolean)
	        if SwitchDelay.Object then
	            SwitchDelay.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Takes the axe out through the hotbar instead of silently"
	})
	SwitchDelay = AutoVoidRegent:CreateSlider({
	    Name = "Switch delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Default = 0.05,
	    Darker = true,
	    Visible = false,
	    Suffix = "seconds"
	})
	LimitItem = AutoVoidRegent:CreateToggle({
	    Name = "Limit to items",
	    Tooltip = "Only slams while the axe is already held"
	})
end)

