Run(function()
	local AutoZeno
	local Targets
	local TargetMode
	local Limit
	local AFKCheck
	local AutoShockWave
	local ShockwaveRange
	local UseStrike
	local UseStorm
	local Range
	local Delay
	
	local function GetAttackData()
	    if Limit.Enabled then
	        local Tool: Tool? = Store.hand.tool
	        local ItemType: string? = Tool and Tool.Name
	        if ItemType and bedwars.WizardUtil:isWizardStaff(ItemType) then
	            return Tool, ItemType
	        end
	        return nil
	    end
	
	    for _, v: any in Store.inventory.inventory.items do
	        if bedwars.WizardUtil:isWizardStaff(v.itemType) and v.tool then
	            SwitchItem(v.tool, 0)
	            return v.tool, v.itemType
	        end
	    end
	
	    return nil
	end
	
	AutoZeno = vape.Categories.Kits:CreateModule({
	    Name = "AutoZeno",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Attempts: {[string]: number} = {}
	            repeat
	                if Entity.isAlive and not (AFKCheck.Enabled and IsAfk()) then
	                    local Staff, ItemType = GetAttackData()
	                    if Staff and ItemType then
	                        local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                        local CastRange: number = math.min(Range.Value, bedwars.WizardUtil:getCastRange(ItemType))
	                        local Shockwave: boolean = AutoShockWave.Enabled and bedwars.WizardUtil:hasAbility(ItemType, "SHOCKWAVE")
	                        local Ent = Entity.EntityPosition({
	                            Origin = LocalPosition,
	                            Range = math.max(CastRange, Shockwave and ShockwaveRange.Value or 0),
	                            Part = "RootPart",
	                            Players = Targets.Players.Enabled,
	                            NPCs = Targets.NPCs.Enabled,
	                            Priority = Targets.Priority.Value,
	                            Sort = SortMethods[TargetMode.Value]
	                        })
	
	                        if Ent then
	                            local Distance: number = (LocalPosition - Ent.RootPart.Position).Magnitude
	                            local TargetPosition: Vector3 = Ent.RootPart.Position + ((Ent.Humanoid.MoveDirection or Vector3.zero) * (1 + LocalPlayer:GetNetworkPing()))
	                            local Abilities = {
	                                {"LIGHTNING_STORM", UseStorm.Enabled and Distance <= CastRange},
	                                {"SHOCKWAVE", Shockwave and Distance <= ShockwaveRange.Value},
	                                {"LIGHTNING_STRIKE", UseStrike.Enabled and Distance <= CastRange}
	                            }
	
	                            for _, v: any in Abilities do
	                                if not v[2] or (Attempts[v[1]] or 0) > tick() then
	                                    continue
	                                end
	                                if not bedwars.WizardUtil:hasAbility(ItemType, v[1]) then
	                                    continue
	                                end
	
	                                local Controller = bedwars.WizardStaffController
	                                if not Controller then
	                                    continue
	                                end
	
	                                local Success, Allowed = pcall(Controller.canCastAbility, Controller, v[1])
	                                if not Success or not Allowed then
	                                    continue
	                                end
	                                Success, Allowed = pcall(bedwars.AbilityController.canUseAbility, bedwars.AbilityController, v[1], {disableBlockedAbilityAlert = true})
	                                if not Success or not Allowed then
	                                    continue
	                                end
	
	                                Attempts[v[1]] = tick() + math.max(Delay.Value, 0.25)
	                                if pcall(bedwars.AbilityController.useAbility, bedwars.AbilityController, v[1], newproxy(true), {target = v[1] == "SHOCKWAVE" and Vector3.zero or TargetPosition}) then
	                                    task.wait(Delay.Value)
	                                    break
	                                end
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoZeno.Enabled
	        end
	    end,
	    Tooltip = "Automatically uses zeno's staff."
	})
	
	Targets = AutoZeno:CreateTargets({
	    Players = true,
	    NPCs = false
	})
	local Methods: {string} = {"Damage", "Distance"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	TargetMode = AutoZeno:CreateDropdown({
	    Name = "Target Mode",
	    List = Methods,
	    Default = "Distance"
	})
	Limit = AutoZeno:CreateToggle({
	    Name = "Limit to item",
	    Default = true
	})
	AFKCheck = AutoZeno:CreateToggle({
	    Name = "AFK check",
	    Tooltip = "Stops casting once you have not touched your mouse or keyboard for 30 seconds"
	})
	UseStrike = AutoZeno:CreateToggle({
	    Name = "Use Lightning Strike",
	    Default = true
	})
	UseStorm = AutoZeno:CreateToggle({Name = "Use Lightning Storm"})
	AutoShockWave = AutoZeno:CreateToggle({
	    Name = "Auto Shockwave",
	    Function = function(Callback: boolean)
	        if ShockwaveRange then
	            ShockwaveRange.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Automatically uses the shockwave ability when a target is near"
	})
	ShockwaveRange = AutoZeno:CreateSlider({
	    Name = "Shockwave Range",
	    Min = 1,
	    Max = 12,
	    Decimal = 5,
	    Default = 12,
	    Darker = true,
	    Visible = false,
	    Suffix = function(Val: number)
	        return Val > 1 and "studs" or "stud"
	    end
	})
	Range = AutoZeno:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 60,
	    Decimal = 5,
	    Default = 35,
	    Suffix = function(Val: number)
	        return Val > 1 and "studs" or "stud"
	    end
	})
	Delay = AutoZeno:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 10,
	    Decimal = 5,
	    Default = 0.5,
	    Suffix = function(Val: number)
	        return Val > 1 and "secs" or "sec"
	    end
	})
end)

Run(function()
	local AutoZephyr
	local Lead
	
	local TeleportLimits: {[string]: number} = {
	    Fly = 2,
	    InfiniteJump = 1.7
	}
	
	local function GetPullIn(): number?
	    local TPDown = vape.Modules.TPDown
	    if TPDown and TPDown.Enabled then
	        return TPDown.PullIn
	    end
	
	    local AirTime: number = tick() - (Entity.character.AirTime or tick())
	    for Name: string, Limit: number in TeleportLimits do
	        local Module = vape.Modules[Name]
	        local Option = Module and Module.Options["TP Down"]
	        if Module and Module.Enabled and Option and Option.Enabled then
	            return Limit - AirTime
	        end
	    end
	    return nil
	end
	
	AutoZephyr = vape.Categories.Kits:CreateModule({
	    Name = "AutoZephyr",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Humanoid: Humanoid? = nil
	            local StateConnection: RBXScriptConnection? = nil
	            local Used: number = 0
	            local NextJump: number = 0
	
	            AutoZephyr:Clean(function()
	                if StateConnection then
	                    StateConnection:Disconnect()
	                    StateConnection = nil
	                end
	            end)
	
	            AutoZephyr:Clean(RunService.PreSimulation:Connect(function()
	                if not Entity.isAlive or vape.MovementOwner then
	                    return
	                end
	
	                if Entity.character.Humanoid ~= Humanoid then
	                    if StateConnection then
	                        StateConnection:Disconnect()
	                    end
	                    Humanoid = Entity.character.Humanoid
	                    Used = 0
	                    StateConnection = Entity.character.Humanoid.StateChanged:Connect(function(Old: Enum.HumanoidStateType, New: Enum.HumanoidStateType)
	                        if New == Enum.HumanoidStateType.Landed then
	                            Used = 0
	                        elseif Old == Enum.HumanoidStateType.Freefall and New == Enum.HumanoidStateType.Jumping then
	                            Used += 1
	                        end
	                    end)
	                end
	
	                if Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air or NextJump > tick() then
	                    return
	                end
	
	                local Controller = bedwars.JumpHeightController
	                local Allowed: number = Controller and Controller.allowedAirJumps or 0
	                local PullIn: number? = GetPullIn()
	                if Used < Allowed and PullIn and PullIn <= Lead.Value then
	                    NextJump = tick() + 0.25
	                    bedwars.Handler:Get("NotifyAirJump"):Fire()
	                    Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	                    Entity.character.AirTime = tick()
	                end
	            end))
	        end
	    end,
	    Tooltip = "Uses a Zephyr air jump right before TPDown, or the TP Down option of Fly or InfiniteJump, would pull you down, so you stay up instead. Needs Zephyr's air jumps (5 orbs)"
	})
	
	Lead = AutoZephyr:CreateSlider({
	    Name = "Lead",
	    Min = 0.05,
	    Max = 0.5,
	    Default = 0.15,
	    Decimal = 100,
	    Suffix = function(Val: number)
	        return Val == 1 and "second" or "seconds"
	    end,
	    Tooltip = "How long before the pull down it jumps"
	})
end)

Run(function()
	local AutoZola
	local Mode
	local Range
	local Links: {[Instance]: number} = {}
	local NextLink: number = 0
	
	local function IsLinked(Character: Model)
	    local Expiry: number? = Links[Character]
	    if Expiry and Expiry > tick() then
	        return true
	    end
	    Links[Character] = nil
	    return false
	end
	
	local function AttemptLink(Character: Model?)
	    if not Character or tick() < NextLink or IsLinked(Character) then
	        return
	    end
	    local Count: number = 0
	    for LinkedCharacter: Instance in Links do
	        if IsLinked(LinkedCharacter) then
	            Count += 1
	        end
	    end
	    if Count >= bedwars.SoulBrokerConstants.MAX_SOUL_LINKS then
	        return
	    end
	
	    Links[Character] = tick() + 1
	    NextLink = tick() + 1
	    bedwars.Handler:Get("AttemptSoulLink"):Fire("CallServerAsync", Character)
	end
	
	AutoZola = vape.Categories.Kits:CreateModule({
	    Name = "AutoZola",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoZola:Clean(bedwars.Handler:Get("SoulLinkFormed").Remote:Connect(function(LinkTable)
	                if LinkTable.broker == LocalPlayer and not LinkTable.guard then
	                    Links[LinkTable.target] = tick() + bedwars.SoulBrokerConstants.SOUL_LINK_DURATION
	                end
	            end))
	
	            AutoZola:Clean(bedwars.Handler:Get("SoulLinkRemoved").Remote:Connect(function(LinkTable)
	                if LinkTable.broker == LocalPlayer and not LinkTable.guard then
	                    Links[LinkTable.target] = nil
	                end
	            end))
	
	            AutoZola:Clean(VapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)
	                if Mode.Value ~= "On Hit" or DamageTable.fromEntity ~= LocalPlayer.Character then
	                    return
	                end
	                if not Entity.isAlive or Store.equippedKit ~= "soul_broker" then
	                    return
	                end
	
	                local Target = Entity.getEntity(DamageTable.entityInstance)
	                if Target and Target.Player and Target.Targetable and (Entity.character.RootPart.Position - Target.RootPart.Position).Magnitude <= Range.Value then
	                    AttemptLink(Target.Character)
	                end
	            end))
	
	            repeat
	                if Mode.Value == "On See" and tick() >= NextLink and Entity.isAlive and Store.equippedKit == "soul_broker" then
	                    for _, v: any in Entity.AllPosition({
	                        Range = Range.Value,
	                        Part = "RootPart",
	                        Players = true,
	                        Wallcheck = true
	                    }) do
	                        if not IsLinked(v.Character) then
	                            AttemptLink(v.Character)
	                            break
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoZola.Enabled
	        end
	    end,
	    Tooltip = "Automatically soul links enemies"
	})
	
	Mode = AutoZola:CreateDropdown({
	    Name = "Mode",
	    List = {"On See", "On Hit"},
	    Tooltip = "On See - Links enemies as soon as you can see them\nOn Hit - Links enemies whenever you hit them",
	    Default = "On See"
	})
	Range = AutoZola:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 50,
	    Default = 30,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
end)

Run(function()
	local CryptAura
	local Range
	local Delay
	local NextClaim: number = 0
	
	local Claimed = setmetatable({}, {__mode = "k"})
	
	local Activate = bedwars.Handler:Get("ActivateGravestone")
	
	CryptAura = vape.Categories.Kits:CreateModule({
	    Name = "CryptAura",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextClaim = 0
	            table.clear(Claimed)
	
	            repeat
	                if Entity.isAlive and Store.equippedKit == "necromancer" and tick() >= NextClaim then
	                    local Origin: Vector3 = Entity.character.RootPart.Position
	                    for _, v: Instance in CollectionService:GetTagged("Gravestone") do
	                        if not Claimed[v] and v:GetAttribute("GravestoneSecret") and (v:GetPivot().Position - Origin).Magnitude <= Range.Value then
	                            Claimed[v] = true
	                            NextClaim = tick() + Delay.Value
	                            Activate:Fire("CallServer", {
	                                secret = v:GetAttribute("GravestoneSecret"),
	                                position = v:GetAttribute("GravestonePosition"),
	                                skeletonData = {
	                                    associatedPlayerUserId = v:GetAttribute("GravestonePlayerUserId"),
	                                    armorType = v:GetAttribute("ArmorType"),
	                                    weaponType = v:GetAttribute("SwordType"),
	                                    bowType = v:GetAttribute("BowType")
	                                }
	                            })
	                            break
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not CryptAura.Enabled
	        end
	    end,
	    Tooltip = "Automatically claims the gravestones enemies drop into your undead army"
	})
	
	Range = CryptAura:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 40,
	    Default = 12,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	Delay = CryptAura:CreateSlider({
	    Name = "Delay",
	    Min = 0.1,
	    Max = 3,
	    Default = 0.3,
	    Decimal = 10,
	    Suffix = function(Val: number)
	        return Val <= 1 and "sec" or "secs"
	    end
	})
end)

Run(function()
	local DaveyAim
	local Mode
	local Position
	local Range
	local PlaceCannon
	local Switch
	local LaunchCannon
	local ShowTarget
	local OldDaveyAim
	
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.RespectCanCollide = true
	
	local function PlaceCannonBlock()
	    local Item = GetItem("cannon")
	    if not Item then
	        SendNotification("DaveyAim", "No cannon in your inventory.", 5, "warning")
	        return nil
	    end
	
	    local Root: BasePart = Entity.character.RootPart
	    local Feet: Vector3 = RoundPosition(Root.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0))
	    local Spot, Closest = nil, math.huge
	
	    for X: number = -3, 3 do
	        for Z: number = -3, 3 do
	            for Y: number = 0, 1 do
	                local Cell: Vector3 = Feet + Vector3.new(X * 3, Y * 3, Z * 3)
	                local Distance: number = (Root.Position - Cell).Magnitude
	                if Distance > Range.Value or Distance >= Closest or Cell == Feet or Cell == Feet + Vector3.yAxis * 3 then
	                    continue
	                end
	                if GetPlacedBlock(Cell) or GetPlacedBlock(Cell + Vector3.yAxis * 3) or not GetPlacedBlock(Cell - Vector3.yAxis * 3) then
	                    continue
	                end
	                Spot, Closest = Cell, Distance
	            end
	        end
	    end
	
	    local PlacePosition: Vector3? = Spot
	    if not PlacePosition then
	        SendNotification("DaveyAim", "Nowhere to put a cannon.", 5, "warning")
	        return nil
	    end
	
	    if Switch.Enabled then
	        SwitchItem(Item.tool)
	        local Hotbar = GetHotbar(Item.tool)
	        if Hotbar then
	            HotbarSwitch(Hotbar)
	        end
	    end
	
	    bedwars.placeBlock(PlacePosition, "cannon")
	
	    local Timeout: number = tick() + 1
	    repeat
	        task.wait(0.05)
	        for _, v: BasePart in CollectionService:GetTagged("cannon") do
	            if (v.Position - PlacePosition).Magnitude < 1.5 then
	                return v
	            end
	        end
	    until tick() > Timeout
	
	    return nil
	end
	
	local function GetApex(Delta: Vector3, Time: number)
	    local Rise: number = ((Delta + Vector3.new(0, workspace.Gravity * Time * Time * 0.5, 0)) / Time).Y
	    return Rise > 0 and (Rise * Rise) / (2 * workspace.Gravity) or 0
	end
	
	local function FindLaunchSpeed(Func, Depth: number?)
	    local Success, Constants = pcall(debug.getconstants, Func)
	    if not Success then
	        return
	    end
	
	    local Speed, Matched
	    for _, v: any in Constants do
	        if v == "LaunchSelfFromCannon" then
	            Matched = true
	        elseif type(v) == "number" and v > 0 then
	            Speed = Speed or v
	        end
	    end
	    if Matched and Speed then
	        return Speed
	    end
	    if (Depth or 0) >= 3 then
	        return
	    end
	
	    local Found, Upvalues = pcall(debug.getupvalues, Func)
	    if not Found then
	        return
	    end
	
	    for _, v: any in Upvalues do
	        if type(v) == "function" then
	            local Result: number? = FindLaunchSpeed(v, (Depth or 0) + 1)
	            if Result then
	                return Result
	            end
	        end
	    end
	end
	
	local function SolveTime(Delta: Vector3, Velocity: Vector3, Speed: number, Fast: number, Slow: number)
	    for _ = 1, 60 do
	        local Middle: number = (Fast + Slow) / 2
	        if ((Delta + Vector3.new(0, workspace.Gravity * Middle * Middle * 0.5, 0)) / Middle - Velocity).Magnitude > Speed then
	            Fast = Middle
	        else
	            Slow = Middle
	        end
	    end
	
	    return (Fast + Slow) / 2
	end
	
	local function GetLaunchTime(Origin: Vector3, Delta: Vector3, Velocity: Vector3, Speed: number)
	    local Low, Up = 0.0001, 20
	
	    for _ = 1, 50 do
	        local First, Second = Low + (Up - Low) / 3, Up - (Up - Low) / 3
	        if ((Delta + Vector3.new(0, workspace.Gravity * First * First * 0.5, 0)) / First - Velocity).Magnitude < ((Delta + Vector3.new(0, workspace.Gravity * Second * Second * 0.5, 0)) / Second - Velocity).Magnitude then
	            Up = Second
	        else
	            Low = First
	        end
	    end
	
	    local Middle: number = (Low + Up) / 2
	    if ((Delta + Vector3.new(0, workspace.Gravity * Middle * Middle * 0.5, 0)) / Middle - Velocity).Magnitude > Speed then
	        return
	    end
	
	    local Candidates: {number} = {
	        SolveTime(Delta, Velocity, Speed, 0.0001, Middle),
	        SolveTime(Delta, Velocity, Speed, 20, Middle)
	    }
	    if OldDaveyAim.Enabled then
	        for Step: number = -24, 24 do
	            local FlightTime: number = Middle * (1 + Step * 0.05)
	            if FlightTime > 0.05 and ((Delta + Vector3.new(0, workspace.Gravity * FlightTime * FlightTime * 0.5, 0)) / FlightTime - Velocity).Magnitude <= Speed then
	                table.insert(Candidates, FlightTime)
	            end
	        end
	    end
	    table.sort(Candidates, function(A: number, B: number)
	        return GetApex(Delta, A) < GetApex(Delta, B)
	    end)
	
	    for _, v: number in Candidates do
	        local Arc: Vector3 = (Delta + Vector3.new(0, workspace.Gravity * v * v * 0.5, 0)) / v
	        if Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air and Arc.Y <= 0 then
	            continue
	        end
	        local Previous: Vector3 = Origin
	        local Lower: Vector3 = Vector3.yAxis * math.max(Entity.character.HipHeight - 2, 0)
	        local Blocked: boolean = false
	        local Steps: number = math.clamp(math.ceil(math.max(v * 60, (Arc.Magnitude * v + workspace.Gravity * v * v * 0.5) / 6)), 12, 240)
	        for Step: number = 1, Steps do
	            local Elapsed: number = v * Step / Steps
	            local Point: Vector3 = Origin + Arc * Elapsed - Vector3.new(0, workspace.Gravity * Elapsed * Elapsed * 0.5, 0)
	            local Hit: RaycastResult? = workspace:Spherecast(Previous, 2, Point - Previous, RayCheck) or workspace:Spherecast(Previous - Lower, 2, Point - Previous, RayCheck)
	            local Landing: boolean = Hit ~= nil and Step == Steps and Hit.Normal.Y > 0.7 and ((Hit.Position - Origin - Delta) * Vector3.new(1, 0, 1)).Magnitude <= 2.5
	            if Hit and not Landing then
	                Blocked = true
	                break
	            end
	            Previous = Point
	        end
	
	        if not Blocked then
	            return v
	        end
	    end
	
	    return nil
	end
	
	local function TrackFlight(Cannon: BasePart, Direction: Vector3, Speed: number, Time: number, Target: Vector3, Visual: Part?, Manual: boolean?)
	    local Root: BasePart = Entity.character.RootPart
	    local Humanoid: Humanoid = Entity.character.Humanoid
	    local Velocity: Vector3 = Root.AssemblyLinearVelocity
	    local Controller = bedwars.CannonHandController
	    local Flight = {Root = Root}
	    local Active: boolean = false
	    local Cancelled: boolean = false
	    local LaunchStart: number = 0
	    local FlightOrigin: Vector3 = Root.Position
	    local FlightVelocity: Vector3 = (Target - FlightOrigin + Vector3.yAxis * workspace.Gravity * Time * Time * 0.5) / Time
	    local AutoRotate: boolean = Humanoid.AutoRotate
	    local Legacy: boolean = OldDaveyAim.Enabled
	    local Deadline: number = tick() + (Manual and 30 or 2) + Store.ping.total
	    local Old = Controller.launchSelf
	    local Launch
	
	    local function Restore()
	        if Controller.launchSelf == Launch then
	            Controller.launchSelf = Old
	        end
	    end
	
	    Launch = function(self, Block: BasePart, ...)
	        if Block ~= Cannon or Cancelled then
	            return Old(self, Block, ...)
	        end
	
	        Active = true
	        Velocity = Root.AssemblyLinearVelocity
	        FlightOrigin = Root.Position
	        FlightVelocity = (Target - FlightOrigin + Vector3.yAxis * workspace.Gravity * Time * Time * 0.5) / Time
	        Store.cannonFlight = Flight
	        Deadline = tick() + 2 + Store.ping.total
	        local Call = Old(self, Block, ...)
	        LaunchStart = tick()
	        Restore()
	        return Call
	    end
	    Controller.launchSelf = Launch
	
	    task.spawn(function()
	        local Launched: boolean = false
	        local Airborne: boolean = false
	        local Elapsed: number = 0
	
	        repeat
	            local Delta: number = RunService.PreSimulation:Wait()
	            if Cancelled or not Entity.isAlive or Entity.character.RootPart ~= Root or (Active and Store.cannonFlight ~= Flight) then
	                break
	            end
	
	            if Active and not Launched and (Root.AssemblyLinearVelocity - Velocity):Dot(Direction) > Speed * 0.5 then
	                Launched = true
	                Deadline = LaunchStart + Time + 3
	                Humanoid.AutoRotate = false
	                Humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
	                Root.AssemblyAngularVelocity = Vector3.zero
	            end
	            if Launched then
	                local Grounded: boolean = Humanoid.FloorMaterial ~= Enum.Material.Air or (Root.AssemblyLinearVelocity.Y <= 0 and workspace:Raycast(Root.Position, Vector3.yAxis * -(Entity.character.HipHeight + 0.05), RayCheck) ~= nil)
	                if not Grounded then
	                    Airborne = true
	                elseif Airborne or tick() - LaunchStart > 0.2 then
	                    break
	                end
	                Elapsed += Delta
	                if Legacy then
	                    if Elapsed < Time then
	                        local IdealPosition: Vector3 = FlightOrigin + FlightVelocity * Elapsed - Vector3.yAxis * workspace.Gravity * Elapsed * Elapsed * 0.5
	                        local IdealVelocity: Vector3 = FlightVelocity - Vector3.yAxis * workspace.Gravity * Elapsed
	                        local Ceiling: number = math.sqrt(Speed * Speed + 2 * workspace.Gravity * math.max(FlightOrigin.Y - Root.Position.Y, 0))
	                        local Corrected: Vector3 = IdealVelocity + (IdealPosition - Root.Position) * 6
	                        local StepVelocity: Vector3 = Corrected.Magnitude > Ceiling and Corrected.Unit * Ceiling or Corrected
	                        if workspace:Spherecast(Root.Position, 2, StepVelocity * Delta, RayCheck) then
	                            break
	                        end
	                        Root.AssemblyLinearVelocity = StepVelocity
	                    else
	                        Root.AssemblyLinearVelocity = Vector3.new(0, Root.AssemblyLinearVelocity.Y, 0)
	                        if Elapsed >= Time + 0.5 then
	                            break
	                        end
	                    end
	                elseif Elapsed >= Time then
	                    break
	                end
	            end
	            if Visual then
	                Visual.Tag.TextLabel.Text = `Landing ({math.floor((Target - Root.Position).Magnitude)} studs)`
	            end
	        until tick() > Deadline
	
	        Cancelled = true
	        Restore()
	        if Store.cannonFlight == Flight then
	            Store.cannonFlight = nil
	        end
	        if Launched and Humanoid.Parent and not Humanoid.AutoRotate then
	            Humanoid.AutoRotate = AutoRotate
	        end
	        if Legacy and Launched and Entity.isAlive and Entity.character.RootPart == Root then
	            Root.AssemblyLinearVelocity = Vector3.new(0, math.min(Root.AssemblyLinearVelocity.Y, 0), 0)
	        end
	        if Visual then
	            Visual:Destroy()
	        end
	    end)
	
	    return function()
	        Cancelled = true
	        Restore()
	    end
	end
	
	DaveyAim = vape.Categories.Kits:CreateModule({
	    Name = "DaveyAim",
	    Function = function(Callback: boolean)
	        if Callback then
	            DaveyAim:Toggle()
	            if not Entity.isAlive or Store.cannonFlight then
	                return
	            end
	
	            local Cannons: {BasePart} = {}
	            local CannonOrigin: Vector3 = Entity.character.RootPart.Position
	            for _, v: BasePart in Store.blocks do
	                if v.Name == "cannon" and (CannonOrigin - v.Position).Magnitude <= Range.Value then
	                    table.insert(Cannons, v)
	                end
	            end
	            if #Cannons > 1 then
	                table.sort(Cannons, function(A: BasePart, B: BasePart)
	                    return (CannonOrigin - A.Position).Magnitude < (CannonOrigin - B.Position).Magnitude
	                end)
	            end
	
	            local Cannon = Cannons[1] or (PlaceCannon.Enabled and PlaceCannonBlock())
	            if not Cannon then
	                if not PlaceCannon.Enabled then
	                    SendNotification("DaveyAim", "No cannon in range.", 5, "warning")
	                end
	                return
	            end
	
	            local CameraAim: boolean = Position.Value == "Camera" or UserInputService.TouchEnabled
	            local AimRay: Ray = CameraAim and Ray.new(Camera.CFrame.Position, Camera.CFrame.LookVector) or cloneref(LocalPlayer:GetMouse()).UnitRay
	            RayCheck.FilterDescendantsInstances = {LocalPlayer.Character, Camera, Cannon}
	            local RayResult: RaycastResult? = workspace:Raycast(AimRay.Origin, AimRay.Direction * 10000, RayCheck)
	            if not RayResult then
	                SendNotification("DaveyAim", "No position found.", 5, "warning")
	                return
	            end
	
	            local LocalPosition: Vector3 = Entity.character.RootPart.Position
	            local TargetPosition: Vector3 = RayResult.Position + Vector3.new(0, Entity.character.HipHeight, 0)
	            local Velocity: Vector3 = Entity.character.RootPart.AssemblyLinearVelocity
	            local CannonSpeed: number = (FindLaunchSpeed(bedwars.CannonHandController.launchSelf) or 200)
	            local MaxRange: number = (CannonSpeed * CannonSpeed) / workspace.Gravity
	            if (TargetPosition - LocalPosition).Magnitude > MaxRange then
	                SendNotification("DaveyAim", `Too far away ({math.floor((TargetPosition - LocalPosition).Magnitude)} studs away, {math.floor(MaxRange)} max).`, 5, "warning")
	                return
	            end
	
	            local Time: number? = GetLaunchTime(LocalPosition, TargetPosition - LocalPosition, Velocity, CannonSpeed)
	            if not Time then
	                SendNotification("DaveyAim", "No clear cannon arc to that position.", 5, "warning")
	                return
	            end
	
	            local LaunchDirection: Vector3 = (((TargetPosition - LocalPosition) + Vector3.new(0, workspace.Gravity * Time * Time * 0.5, 0)) / Time - Velocity).Unit
	            local Visual: Part?
	            if ShowTarget.Enabled then
	                local BlockPosition: Vector3 = RoundPosition(RayResult.Position - RayResult.Normal * 1.5)
	                Visual = Instance.new("Part")
	                Visual.Size = Vector3.new(3, 3, 3)
	                Visual.CFrame = CFrame.new(BlockPosition)
	                Visual.Anchored = true
	                Visual.CanCollide = false
	                Visual.CanQuery = false
	                Visual.CanTouch = false
	                Visual.CastShadow = false
	                Visual.Transparency = 1
	                local Selection: SelectionBox = Instance.new("SelectionBox")
	                Selection.Adornee = Visual
	                Selection.LineThickness = 0.04
	                Selection.Color3 = Color3.new(1, 1, 1)
	                Selection.SurfaceColor3 = Color3.new(1, 1, 1)
	                Selection.SurfaceTransparency = 0.75
	                Selection.Parent = Visual
	                local TagSize: Vector2 = GetFontBounds("Landing (000 studs)", 14, UIPallet.Font)
	                local Billboard: BillboardGui = Instance.new("BillboardGui")
	                Billboard.Name = "Tag"
	                Billboard.Size = UDim2.fromOffset(TagSize.X + 8, TagSize.Y + 7)
	                Billboard.StudsOffsetWorldSpace = (TargetPosition - BlockPosition) + Vector3.new(0, 2, 0)
	                Billboard.AlwaysOnTop = true
	                Billboard.Parent = Visual
	                local Tag: TextLabel = Instance.new("TextLabel")
	                Tag.Size = Billboard.Size
	                Tag.BackgroundColor3 = Color3.new()
	                Tag.BackgroundTransparency = 0.5
	                Tag.BorderSizePixel = 0
	                Tag.RichText = true
	                Tag.FontFace = UIPallet.Font
	                Tag.TextSize = 14
	                Tag.TextColor3 = Color3.new(1, 1, 1)
	                Tag.Parent = Billboard
	                bedwars.QueryUtil:setQueryIgnored(Visual, true)
	                Visual.Parent = Camera
	            end
	            if Visual then
	                Visual.Tag.TextLabel.Text = `Landing ({math.floor((TargetPosition - LocalPosition).Magnitude)} studs)`
	            end
	
	            if Mode.Value == "Legit" then
	                local AimDirection: Vector3 = LaunchDirection
	                local StartLook: Vector3 = Camera.CFrame.LookVector
	                local Angle: number = math.deg(math.acos(math.clamp(StartLook:Dot(AimDirection), -1, 1)))
	                local Duration: number = math.clamp(Angle / 300, 0.15, 0.8)
	                local Elapsed, Alpha = 0, 0
	
	                repeat
	                    Elapsed += RunService.PostSimulation:Wait()
	                    Alpha = math.clamp(Elapsed / Duration, 0, 1)
	                    local Eased: number = Alpha < 0.5 and (2 * Alpha * Alpha) or (1 - ((-2 * Alpha + 2) ^ 2) / 2)
	                    local Look: Vector3 = StartLook:Lerp(AimDirection, Eased)
	                    if Look.Magnitude > 0.001 then
	                        local CameraPosition: Vector3 = Camera.CFrame.Position
	                        Camera.CFrame = CFrame.lookAt(CameraPosition, CameraPosition + Look.Unit)
	                    end
	                until Alpha >= 1 or not Entity.isAlive
	                if not Entity.isAlive then
	                    if Visual then
	                        Visual:Destroy()
	                    end
	                    return
	                end
	                bedwars.CannonController:startAiming(Cannon)
	                task.wait(Cannon.AimPrompt.HoldDuration)
	
	                local Ready: number = tick() + 1
	                repeat
	                    RunService.PostSimulation:Wait()
	                until Cannon.StopAimingPrompt.Enabled or tick() > Ready or not Cannon.Parent
	
	                bedwars.CannonController:stopAiming()
	            end
	            task.wait((Cannon.StopAimingPrompt.HoldDuration + (0.2 + Store.ping.total)) + RunService.PostSimulation:Wait())
	
	            if Mode.Value == "Legit" then
	                local Success, Aiming = pcall(function()
	                    return bedwars.CannonController:isAiming()
	                end)
	                if Success and Aiming then
	                    pcall(function()
	                        bedwars.CannonController:stopAiming()
	                    end)
	                end
	            end
	
	            local BlockPosition: Vector3 = bedwars.BlockController:getBlockPosition(Cannon.Position)
	            local Aimed: boolean?
	            local Timeout: number = tick() + 1
	            repeat
	                bedwars.Handler:Get("AimCannon"):Fire("SendToServer", {
	                    cannonBlockPos = BlockPosition,
	                    lookVector = LaunchDirection
	                })
	                task.wait(0.15)
	                local Look = Cannon:GetAttribute("LookVector")
	                Aimed = Look and (Look - LaunchDirection).Magnitude < 0.0001
	            until Aimed or tick() > Timeout or not Cannon.Parent
	
	            if not Aimed then
	                SendNotification("DaveyAim", "Cannon refused the aim.", 5, "warning")
	                if Visual then
	                    Visual:Destroy()
	                end
	                return
	            end
	
	            if not Entity.isAlive or not Cannon.Parent then
	                if Visual then
	                    Visual:Destroy()
	                end
	                return
	            end
	
	            if LaunchCannon.Enabled then
	                TrackFlight(Cannon, LaunchDirection, CannonSpeed, Time, TargetPosition, Visual)
	                bedwars.CannonHandController:launchSelf(Cannon)
	            else
	                local Launched, StillAimed = false, true
	                local Cancel = TrackFlight(Cannon, LaunchDirection, CannonSpeed, Time, TargetPosition, Visual, true)
	                local Connection: RBXScriptConnection = Cannon.LaunchSelfPrompt.Triggered:Connect(function(PromptPlayer: Player)
	                    if PromptPlayer == LocalPlayer and not Launched and Entity.isAlive then
	                        Launched = true
	                    end
	                end)
	                local LaunchDeadline: number = tick() + 30
	
	                repeat
	                    RunService.PostSimulation:Wait()
	                    local Look = Cannon.Parent and Cannon:GetAttribute("LookVector")
	                    StillAimed = typeof(Look) ~= "Vector3" or (Look - LaunchDirection).Magnitude < 0.0001
	                until Launched or not StillAimed or tick() > LaunchDeadline or not Entity.isAlive or not Cannon.Parent
	
	                Connection:Disconnect()
	                if not Launched then
	                    Cancel()
	                    if not StillAimed then
	                        SendNotification("DaveyAim", "Cannon was re-aimed before you launched.", 5, "warning")
	                    end
	                    if Visual then
	                        Visual:Destroy()
	                    end
	                    return
	                end
	            end
	        end
	    end,
	    Tooltip = "Aims a nearby cannon at your cursor and launches you onto it"
	})
	
	Mode = DaveyAim:CreateDropdown({
	    Name = "Aim Mode",
	    List = {"Blatant", "Legit"},
	    Default = "Blatant"
	})
	Position = DaveyAim:CreateDropdown({
	    Name = "Position Mode",
	    List = {"Mouse", "Camera"},
	    Default = "Mouse"
	})
	Range = DaveyAim:CreateSlider({
	    Name = "Search Range",
	    Min = 1,
	    Max = 18,
	    Default = 10,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	PlaceCannon = DaveyAim:CreateToggle({
	    Name = "Place Cannon",
	    Function = function(Callback: boolean)
	        if Switch then
	            Switch.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Puts a cannon down on the nearest free block when there is none in range",
