Run(function()
	local KitSpy
	local Viewer
	local Notifications
	local Teammates
	local Self
	local Range
	local Window
	local Delay
	local Items
	local Extras
	local Toggles = {}
	
	local ExtraLabels: {[string]: string} = {
	    ["alchemist_ingedients"] = "ingredient",
	    ["alchemy_crystal"] = "crystal",
	    ["crystalheart_seed"] = "crystalheart seed",
	    ["forest_environment_plant"] = "plant",
	    ["ghost"] = "ghost",
	    ["murder_coin"] = "coin",
	    ["shadow_coin"] = "shadow coin",
	    ["soulvine_seed"] = "soulvine seed",
	    ["spirit_gardener_energy"] = "energy",
	    ["spirit_gardener_seeds"] = "seed",
	    ["tearbloom_seed"] = "tearbloom seed"
	}
	
	local Totals: {[Player]: {[string]: number}} = {}
	local Panel, InfoLabel
	local Expanded: boolean = false
	local DigAnimation = bedwars.GameAnimationUtil:getAssetId(bedwars.AnimationType.SHOVEL_DIG)
	local Animators = setmetatable({}, {__mode = "k"})
	
	local function PlayerName(TargetPlayer: Player?)
	    return TargetPlayer and (TargetPlayer.DisplayName or TargetPlayer.Name) or "someone"
	end
	
	local function Ignored(TargetPlayer: Player)
	    if TargetPlayer == LocalPlayer then
	        return Self.Enabled
	    end
	    return Teammates.Enabled and TargetPlayer.Team == LocalPlayer.Team
	end
	
	local function AmountText(Amount: number, Label: string)
	    return `{Amount} {Label}{Amount == 1 and "" or "s"}`
	end
	
	local function RefreshViewer()
	    if not Panel then
	        return
	    end
	
	    local List = {}
	    for TargetPlayer: Player, Kinds: {[string]: number} in Totals do
	        local Total, Text = 0, {}
	        for Label: string, Amount: number in Kinds do
	            Total += Amount
	            table.insert(Text, AmountText(Amount, Label))
	        end
	        table.sort(Text)
	        table.insert(List, {Name = PlayerName(TargetPlayer), Total = Total, Text = table.concat(Text, ", ")})
	    end
	    table.sort(List, function(A, B)
	        return A.Total > B.Total
	    end)
	
	    local Lines: {string} = {"<b>KitSpy</b>"}
	    if #List == 0 then
	        table.insert(Lines, "Nothing spotted yet")
	    else
	        for i: number, v: any in List do
	            if not Expanded and i > 5 then
	                table.insert(Lines, `+{#List - 5} more`)
	                break
	            end
	            table.insert(Lines, `{v.Name}: {v.Text}`)
	        end
	    end
	
	    InfoLabel.Text = table.concat(Lines, "\n")
	    local Size: Vector2 = GetFontBounds(removeTags(InfoLabel.Text), InfoLabel.TextSize, InfoLabel.FontFace)
	    local TitleSize: Vector2 = GetFontBounds("KitSpy", InfoLabel.TextSize, Font.new(InfoLabel.FontFace.Family, Enum.FontWeight.Bold))
	    Panel.Size = UDim2.fromOffset(math.max(Size.X, TitleSize.X) + 16, Size.Y + 16)
	    Panel.Visible = Viewer.Enabled
	end
	
	local function AddTotal(TargetPlayer: Player, Label: string, Amount: number)
	    local Kinds: {[string]: number} = Totals[TargetPlayer] or {}
	    Kinds[Label] = (Kinds[Label] or 0) + Amount
	    Totals[TargetPlayer] = Kinds
	    RefreshViewer()
	    return Kinds[Label]
	end
	
	local function CreateViewer()
	    if Panel then
	        return
	    end
	
	    Panel = Instance.new("TextButton")
	    Panel.Name = "KitSpyViewer"
	    Panel.Position = UDim2.fromOffset(12, 260)
	    Panel.BackgroundColor3 = Color3.new()
	    Panel.BackgroundTransparency = 0.5
	    Panel.Text = ""
	    Panel.AutoButtonColor = false
	    Panel.Visible = false
	    if vape.ThreadFix then
	        setthreadidentity(8)
	    end
	    Panel.Parent = vape.gui.ScaledGui
	    addBlur(Panel)
	
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(0, 5)
	    Corner.Parent = Panel
	
	    InfoLabel = Instance.new("TextLabel")
	    InfoLabel.Size = UDim2.new(1, -16, 1, -16)
	    InfoLabel.Position = UDim2.fromOffset(8, 8)
	    InfoLabel.BackgroundTransparency = 1
	    InfoLabel.TextXAlignment = Enum.TextXAlignment.Left
	    InfoLabel.TextYAlignment = Enum.TextYAlignment.Top
	    InfoLabel.TextSize = 16
	    InfoLabel.TextColor3 = Color3.new(1, 1, 1)
	    InfoLabel.TextStrokeColor3 = Color3.new()
	    InfoLabel.TextStrokeTransparency = 0.8
	    InfoLabel.Font = Enum.Font.Arial
	    InfoLabel.RichText = true
	    InfoLabel.Parent = Panel
	
	    Panel.MouseButton1Click:Connect(function()
	        Expanded = not Expanded
	        RefreshViewer()
	    end)
	end
	
	local function InventoryCount(TargetPlayer: Player, ItemType: string)
	    local Total: number = 0
	    for _, v: any in (store.inventories[TargetPlayer] or {items = {}}).items do
	        if v.itemType == ItemType then
	            Total += (v.amount or 1)
	        end
	    end
	    return Total
	end
	
	local function RecentItems(TargetPlayer: Player, Filtered: boolean)
	    local Now, Found = workspace:GetServerTimeNow(), {}
	    for _, v: any in (store.inventories[TargetPlayer] or {items = {}}).items do
	        if (Now - (v.addedToBackpackTime or 0)) > Window.Value then
	            continue
	        end
	        if Filtered and #Items.ListEnabled > 0 and not table.find(Items.ListEnabled, v.itemType) then
	            continue
	        end
	        local Meta = bedwars.ItemMeta[v.itemType]
	        table.insert(Found, `{(v.amount or 1) > 1 and `{v.amount}x ` or ""}{Meta and Meta.displayName or v.itemType}`)
	    end
	    return Found
	end
	
	local function Report(TargetPlayer: Player, Verb: string, Filtered: boolean)
	    local Found: {string} = RecentItems(TargetPlayer, Filtered)
	    if #Found == 0 then
	        return
	    end
	
	    notif("KitSpy", `{PlayerName(TargetPlayer)} {Verb} {table.concat(Found, ", ")}`, 8, "info")
	end
	
	local function NearestPlayer(Position: Vector3)
	    local Closest, Distance = nil, Range.Value
	    for _, v: any in Entity.List do
	        if not v.Player or Ignored(v.Player) then
	            continue
	        end
	
	        local Magnitude: number = (v.RootPart.Position - Position).Magnitude
	        if Magnitude <= Distance then
	            Closest, Distance = v.Player, Magnitude
	        end
	    end
	    return Closest
	end
	
	local function Credit(TargetPlayer: Player, Label: string, Amount: number)
	    local Total: number = AddTotal(TargetPlayer, Label, Amount)
	    if Notifications.Enabled then
	        notif("KitSpy", `{PlayerName(TargetPlayer)} picked up {AmountText(Amount, Label)} ({Total} total)`, 5, "info")
	    end
	end
	
	local function TrackCollectable(Tags, Label: string, ItemType: string?, LabelMap: {[string]: string}?)
	    local Positions, Pending, Counts = {}, {}, {}
	
	    local function ObjectAdded(Objects: {Instance}, Object: Instance)
	        table.insert(Objects, Object)
	
	        local Part = Object:IsA("Model") and (Object.PrimaryPart or Object:FindFirstChildWhichIsA("BasePart", true)) or Object
	        if Part then
	            Positions[Object] = Part.Position
	        end
	    end
	
	    local function ObjectRemoved(Objects: {Instance}, Object: Instance, Tag: string)
	        local Index: number? = table.find(Objects, Object)
	        if Index then
	            table.remove(Objects, Index)
	        end
	
	        local Position: Vector3? = Positions[Object]
	        Positions[Object] = nil
	        if not Position then
	            return
	        end
	
	        if not ItemType then
	            local TargetPlayer: Player? = NearestPlayer(Position)
	            if TargetPlayer then
	                Credit(TargetPlayer, LabelMap and LabelMap[Tag] or Label, 1)
	            end
	            return
	        end
	
	        table.insert(Pending, {Position = Position, Time = tick()})
	    end
	
	    local Objects: {Instance} = collection(Tags, KitSpy, ObjectAdded, ObjectRemoved)
	
	    if ItemType then
	        for _, v: any in Entity.List do
	            if v.Player then
	                Counts[v.Player] = InventoryCount(v.Player, ItemType)
	            end
	        end
	    end
	
	    repeat
	        local Now: number = tick()
	
	        for _, v: Instance in Objects do
	            local Part = v:IsA("Model") and (v.PrimaryPart or v:FindFirstChildWhichIsA("BasePart", true)) or v
	            if Part then
	                Positions[v] = Part.Position
	            end
	        end
	
	        for i: number = #Pending, 1, -1 do
	            if (Now - Pending[i].Time) > Window.Value then
	                table.remove(Pending, i)
	            end
	        end
	
	        if ItemType then
	            for _, v: any in Entity.List do
	                local TargetPlayer: Player? = v.Player
	                if not TargetPlayer or Ignored(TargetPlayer) then
	                    continue
	                end
	
	                local Amount: number = InventoryCount(TargetPlayer, ItemType)
	                local Previous: number? = Counts[TargetPlayer]
	                Counts[TargetPlayer] = Amount
	
	                if not Previous or Amount <= Previous or not v.RootPart then
	                    continue
	                end
	
	                for i: number = #Pending, 1, -1 do
	                    if (v.RootPart.Position - Pending[i].Position).Magnitude > Range.Value then
	                        continue
	                    end
	
	                    table.remove(Pending, i)
	                    Credit(TargetPlayer, Label, Amount - Previous)
	                    break
	                end
	            end
	        end
	
	        task.wait(0.2)
	    until not KitSpy.Enabled
	end
	
	local function TrackDigging()
	    local function EntityAdded(Ent)
	        if not Ent.Player or Ignored(Ent.Player) then
	            return
	        end
	
	        local Animator: Animator? = Ent.Humanoid:FindFirstChildOfClass("Animator")
	        if not Animator or Animators[Animator] then
	            return
	        end
	        Animators[Animator] = Animator.AnimationPlayed:Connect(function(Track: AnimationTrack)
	            if Track.Animation.AnimationId ~= DigAnimation then
	                return
	            end
	
	            task.delay(Delay.Value, Report, Ent.Player, "dug up", true)
	        end)
	    end
	
	    KitSpy:Clean(Entity.Events.EntityAdded:Connect(EntityAdded))
	    KitSpy:Clean(function()
	        for _, v: RBXScriptConnection in Animators do
	            v:Disconnect()
	        end
	        table.clear(Animators)
	    end)
	
	    for _, v: any in Entity.List do
	        EntityAdded(v)
	    end
	end
	
	local function TrackBounties()
	    local Hunters: {[Player]: Player} = {}
	
	    KitSpy:Clean(function()
	        table.clear(Hunters)
	    end)
	
	    KitSpy:Clean(bedwars.Handler:Get("BountyHunterTargetChanged").Remote:Connect(function(Data)
	        local Hunter = typeof(Data) == "table" and Data.hunter
	        if typeof(Hunter) ~= "Instance" or not Hunter:IsA("Player") then
	            return
	        end
	
	        local Target: Player? = Data.newTargetUserId ~= 0 and Players:GetPlayerByUserId(Data.newTargetUserId) or nil
	        Hunters[Hunter] = Target
	
	        if Target and Notifications.Enabled and not Ignored(Hunter) then
	            notif("KitSpy", `{PlayerName(Hunter)} is now hunting {PlayerName(Target)}`, 12, "info")
	        end
	    end))
	
	    KitSpy:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)
	        local Victim: Player? = Players:GetPlayerFromCharacter(DeathTable.entityInstance)
	        local Killer: Player? = Players:GetPlayerFromCharacter(DeathTable.fromEntity)
	        if not Victim or not Killer or Hunters[Killer] ~= Victim then
	            return
	        end
	
	        Hunters[Killer] = nil
	        if Ignored(Killer) then
	            return
	        end
	
	        AddTotal(Killer, "bounty", 1)
	        notif("KitSpy", `{PlayerName(Killer)} claimed their bounty on {PlayerName(Victim)}`, 20, "alert")
	        task.delay(Delay.Value, Report, Killer, "looted", false)
	    end))
	
	    KitSpy:Clean(Players.PlayerRemoving:Connect(function(TargetPlayer: Player)
	        Hunters[TargetPlayer] = nil
	        for Hunter: Player, v: Player in Hunters do
	            if v == TargetPlayer then
	                Hunters[Hunter] = nil
	            end
	        end
	    end))
	end
	
	local function TrackFishing()
	    KitSpy:Clean(bedwars.Handler:Get("FishCaught").Remote:Connect(function(Data)
	        local TargetPlayer = typeof(Data) == "table" and Data.catchingPlayer
	        if not TargetPlayer or not Data.dropData or not Data.dropData.drops or Ignored(TargetPlayer) then
	            return
	        end
	
	        local Text: {string} = {}
	        for _, v: any in Data.dropData.drops do
	            local Meta = bedwars.ItemMeta[v.itemType]
	            table.insert(Text, AmountText(v.amount, (Meta and Meta.displayName or v.itemType):lower()))
	        end
	
	        if #Text == 0 then
	            return
	        end
	
	        AddTotal(TargetPlayer, "catch", 1)
	        if Notifications.Enabled then
	            notif("KitSpy", `{PlayerName(TargetPlayer)} caught {table.concat(Text, ", ")}`, 20, "info")
	        end
	    end))
	end
	
	local KitSpyFunctions = {
	    beekeeper = function()
	        TrackCollectable("bee", "bee", "bee")
	    end,
	    bigman = function()
	        TrackCollectable("treeOrb", "tree orb")
	    end,
	    bounty_hunter = TrackBounties,
	    farmer_cletus = function()
	        TrackCollectable("HarvestableCrop", "crop")
	    end,
	    fisherman = TrackFishing,
	    jailor = function()
	        TrackCollectable("jailor_soul", "soul")
	    end,
	    metal_detector = function()
	        TrackCollectable("hidden-metal", "metal")
	        TrackDigging()
	    end,
	    spirit_assassin = function()
	        TrackCollectable("EvelynnSoul", "spirit")
	    end,
	    star_collector = function()
	        TrackCollectable("stars", "star")
	    end
	}
	
	KitSpy = vape.Categories.Kits:CreateModule({
	    Name = "KitSpy",
	    Function = function(Callback: boolean)
	        if Callback then
	            CreateViewer()
	            RefreshViewer()
	
	            for Kit: string, v: (...any) -> ...any in KitSpyFunctions do
	                if Toggles[Kit].Enabled then
	                    task.spawn(v)
	                end
	            end
	
	            if #Extras.ListEnabled > 0 then
	                task.spawn(TrackCollectable, Extras.ListEnabled, "collectable", nil, ExtraLabels)
	            end
	        elseif Panel then
	            Panel.Visible = false
	        end
	    end,
	    Tooltip = "Reports what other players are doing with their kit, from bee pickups to bounty claims"
	})
	
	Viewer = KitSpy:CreateToggle({
	    Name = "Viewer",
	    Function = function()
	        RefreshViewer()
	    end,
	    Tooltip = "Shows a panel with everything each player has picked up, click it to expand",
	    Default = true
	})
	Notifications = KitSpy:CreateToggle({
	    Name = "Notifications",
	    Default = true,
	    Tooltip = "Sends a notification every time someone is caught using their kit"
	})
	Teammates = KitSpy:CreateToggle({
	    Name = "Ignore teammates",
	    Default = true
	})
	Self = KitSpy:CreateToggle({
	    Name = "Ignore yourself",
	    Default = true
	})
	Range = KitSpy:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 40,
	    Default = 25,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "How close a player must be to the pickup to be blamed for taking it"
	})
	Window = KitSpy:CreateSlider({
	    Name = "Window",
	    Min = 1,
	    Max = 10,
	    Default = 3,
	    Suffix = function(Val: number)
	        return Val > 1 and "secs" or "sec"
	    end,
	    Tooltip = "How recently something must have happened to still count as that pickup"
	})
	Delay = KitSpy:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 2,
	    Default = 0.5,
	    Decimal = 100,
	    Suffix = function(Val: number)
	        return Val == 1 and "sec" or "secs"
	    end,
	    Tooltip = "Wait before reading their inventory after a dig or a bounty kill"
	})
	Items = KitSpy:CreateTextList({
	    Name = "Items",
	    Placeholder = "item type (iron_ingot)",
	    Darker = true,
	    Tooltip = "Only report these item types when someone digs, leave it empty to report everything"
	})
	Extras = KitSpy:CreateTextList({
	    Name = "Collectables",
	    Default = {
	        "alchemist_ingedients",
	        "alchemy_crystal",
	        "crystalheart_seed",
	        "ghost",
	        "murder_coin",
	        "shadow_coin",
	        "soulvine_seed",
	        "spirit_gardener_energy",
	        "spirit_gardener_seeds",
	        "tearbloom_seed"
	    },
	    Darker = true,
	    Tooltip = "Extra collectable tags to watch, reported by whoever was closest when they vanished"
	})
	KitSpy:CreateButton({
	    Name = "Reset totals",
	    Function = function()
	        table.clear(Totals)
	        RefreshViewer()
	    end
	})
	
	local function KitName(Kit: string)
	    local Meta = bedwars.BedwarsKitMeta[Kit]
	    return Meta and Meta.name or Kit
	end
	
	local SortedKits: {string} = {}
	for Kit: string in KitSpyFunctions do
	    table.insert(SortedKits, Kit)
	end
	table.sort(SortedKits, function(A: string, B: string)
	    return KitName(A) < KitName(B)
	end)
	for _, v: string in SortedKits do
	    Toggles[v] = KitSpy:CreateToggle({
	        Name = KitName(v),
	        Default = true
	    })
	end
end)

Run(function()
	local AutoPickpocket
	local Targets
	local Range
	local Hidden
	
	local Legit: number = GetFunctionRange(bedwars.MimicController.onKitLocalActivated) or 25
	local MimicPickPocket = bedwars.Handler:Get("MimicBlockPickPocketPlayer")
	local Sounds = {bedwars.SoundList.MIMIC_PICKPOCKET_1, bedwars.SoundList.MIMIC_PICKPOCKET_2, bedwars.SoundList.MIMIC_PICKPOCKET_3}
	local RandomGenerator: Random = Random.new()
	local Attempted = setmetatable({}, {__mode = "k"})
	local Ready, Warned = false, 0
	
	AutoPickpocket = vape.Categories.Kits:CreateModule({
	    Name = "AutoPickpocket",
	    Function = function(Callback: boolean)
	        if Callback then
	            Ready = false
	            AutoPickpocket:Clean(bedwars.Client:Get("MimicBlockPickPocketReady"):Connect(function(Event)
	                if Event.player == LocalPlayer then
	                    Ready = Event.ready and true or false
	                end
	            end))
	
	            repeat
	                local Success, Error = pcall(function()
	                    if not Entity.isAlive or Store.equippedKit ~= "mimic" then
	                        return
	                    end
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    local NearbyTargets = Entity.AllPosition({
	                        Range = Range.Value,
	                        Origin = LocalPosition,
	                        Wallcheck = Targets.Walls.Enabled or nil,
	                        Part = "RootPart",
	                        Players = true,
	                        Sort = SortMethods.Distance
	                    })
	
	                    for _, v: any in NearbyTargets do
	                        if not Ready then
	                            break
	                        end
	                        if not v.Character:HasTag("MimicBLockPickPocketPlayer") then
	                            continue
	                        end
	                        if Attempted[v.Character] and tick() - Attempted[v.Character] < 0.5 then
	                            continue
	                        end
	                        Attempted[v.Character] = tick()
	                        Ready = false
	
	                        if MimicPickPocket:Fire("CallServer", v.Player) then
	                            bedwars.AudioManager:playAudio(Sounds[RandomGenerator:NextInteger(1, #Sounds)], {
	                                playbackSpeedMultiplier = 1.27,
	                                position = LocalPosition
	                            })
	                        end
	                        break
	                    end
	
	                    if #NearbyTargets <= 0 and Hidden.Enabled and bedwars.AbilityController:canUseAbility("MIMIC_BLOCK_HIDDEN", {disableBlockedAbilityAlert = true}) then
	                        bedwars.AbilityController:useAbility("MIMIC_BLOCK_HIDDEN")
	                    end
	                end)
	
	                if not Success and tick() - Warned > 5 then
	                    Warned = tick()
	                    warn(`[catvape] AutoPickpocket: {Error}`)
	                end
	                task.wait(0.1)
	            until not AutoPickpocket.Enabled
	            table.clear(Attempted)
	        end
	    end,
	    Tooltip = "Automatically pickpockets with milo kit."
	})
	
	Targets = AutoPickpocket:CreateTargets({Players = true, Walls = true})
	
	Range = AutoPickpocket:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 30,
	    Default = Legit,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	AutoPickpocket:CreateButton({
	    Name = "Sync to legit range",
	    Function = function()
	        Range:SetValue(Legit)
	    end
	})
	Hidden = AutoPickpocket:CreateToggle({
	    Name = "Hide when clear",
	    Tooltip = "Goes back into the block once nobody is in range"
	})
end)

Run(function()
	local RavenTP
	
	RavenTP = vape.Categories.Kits:CreateModule({
